async function fetchTelegramFileBase64(fileId) {
  const fileInfo = await this.helpers.httpRequest({ method: 'GET', url: 'https://api.telegram.org/bot' + botToken + '/getFile?file_id=' + fileId });
  const fileUrl = 'https://api.telegram.org/file/bot' + botToken + '/' + fileInfo.result.file_path;
  const fileBuffer = await this.helpers.httpRequest({ method: 'GET', url: fileUrl, encoding: 'arraybuffer' });
  const base64 = Buffer.isBuffer(fileBuffer) ? fileBuffer.toString('base64') : Buffer.from(fileBuffer).toString('base64');
  return base64;
}

async function handlePhotoBarcode(lang) {
  try {
    const largestPhoto = message.photo[message.photo.length - 1];
    const base64 = await fetchTelegramFileBase64.call(this, largestPhoto.file_id);

    // Read whatever barcode/product code is visible in the photo
    const visionResp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.anthropic.com/v1/messages',
      headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
