          role: 'user',
          content: [
            { type: 'image', source: { type: 'base64', media_type: 'image/jpeg', data: base64 } },
            { type: 'text', text: 'Read any barcode number, product code, or SKU visible in this image. Reply with ONLY the code/number itself, nothing else. If you cannot find one clearly, reply with exactly: NONE' }
          ]
        }]
      })
    });
    await logAiUsage.call(this, visionResp, 'photo_barcode_read');
    const code = (visionResp && visionResp.content && visionResp.content[0] && visionResp.content[0].text || '').trim();

    if (!code || code === 'NONE') {
      await notifySeller.call(this, t(lang, '⚠️ ما قدرت ألقط باركود واضح بالصورة. جرب صورة أوضح أو اكتب الكود يدوياً.', "⚠️ I couldn't clearly read a barcode in that photo. Try a clearer photo, or type the code manually."));
      return;
    }

    // Check if seller_products actually has a barcode column yet
    let hasBarcodeColumn = false;
    try {
      const spec = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/',
        headers: { 'apikey': serviceRoleKey, 'Authorization': 'Bearer ' + serviceRoleKey, 'Accept': 'application/openapi+json' }
      });
