      hasBarcodeColumn = !!(def && def.properties && def.properties.barcode);
    } catch (e) { logSystemError.call(this, chatId, 'Checking database schema for barcode column', e && e.message); }

    if (!hasBarcodeColumn) {
      await notifySeller.call(this, t(lang,
        `📷 قريت الكود: ${code}\n\n⚠️ لسا ما عندنا حقل باركود بجدول المنتجات — لازم نضيفه أول.`,
        `📷 Read code: ${code}\n\n⚠️ There's no barcode field on products yet — that needs to be added first.`
      ));
      return;
    }

    // Look up a product with this barcode
    const matches = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_products?chat_id=eq.' + chatId + '&barcode=eq.' + encodeURIComponent(code) + '&select=*&limit=1',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
    });

    if (matches && matches.length > 0) {
      const p = matches[0];
      await notifySeller.call(this, t(lang,
        `📷 <b>${p.product_name}</b>\nالجملة: ${p.wholesale_price ?? '—'}\nالمفرد: ${p.retail_price ?? '—'}\nالمخزون: ${p.stock_quantity ?? 'غير متتبع'}`,
        `📷 <b>${p.product_name}</b>\nWholesale: ${p.wholesale_price ?? '—'}\nRetail: ${p.retail_price ?? '—'}\nStock: ${p.stock_quantity ?? 'not tracked'}`
      ));
      return;
    }

    // No match — offer to link this barcode to a product
    await setBotState.call(this, 'awaiting_barcode_link', { barcode_value: code });
    await notifySeller.call(this, t(lang,
      `📷 قريت الكود: ${code}\n\nما لقيته مرتبط بأي منتج. اكتب اسم المنتج اللي تريد تربطه فيه، أو "الغاء" لتلغي.`,
      `📷 Read code: ${code}\n\nNot linked to any product yet. Type the product name to link it, or "cancel" to skip.`
    ));
  } catch (e) {
    await notifySeller.call(this, '⚠️ ' + e.message);
  }
}

async function handleAnswerScopeChoice(userText, lang) {
  const state = await getBotState.call(this);
  const ctx = state.context || {};
  const lowerText = (userText || '').toLowerCase().trim();

  const isGeneral = /^(general|عام|1|1️⃣)$/i.test(lowerText) || lowerText.includes('general') || lowerText.includes('عام');
  const isSpecific = /^(specific|خاص|2|2️⃣)$/i.test(lowerText) || lowerText.includes('specific') || lowerText.includes('خاص');

  if (!isGeneral && !isSpecific) {
    await notifySeller.call(this, t(lang,
      'ما فهمت — رد بـ "عام" أو "خاص" بس.',
      'Didn\'t quite catch that — just reply "general" or "specific".'
    ));
    return;
  }

  const { phone, question, replyToMessageId, answerType } = ctx;
  await setBotState.call(this, 'idle', {});

  try {
    if (answerType === 'text') {
      const answerText = ctx.answerText;
      if (isGeneral) {
        await this.helpers.httpRequest({ method: 'POST', url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_knowledge', headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json' }, body: JSON.stringify({ category: 'general', question, answer: answerText, chat_id: chatId }) });
      }
      await this.helpers.httpRequest({ method: 'PATCH', url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/pending_questions?telegram_message_id=eq.' + replyToMessageId, headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' }, body: JSON.stringify({ status: 'answered', answer: answerText }) });
      await this.helpers.httpRequest({ method: 'POST', url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/conversations', headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' }, body: JSON.stringify({ phone_number: phone, role: 'assistant', message: answerText, timestamp: new Date().toISOString(), seller_id: chatId }) });
      await sendWhatsApp.call(this, phone, answerText);
      await notifySeller.call(this, t(lang, `✅ تم الإرسال! (${isGeneral ? 'حفظته كمعرفة عامة' : 'خاص بهذا الزبون بس'})`, `✅ Sent! (${isGeneral ? 'saved as general knowledge' : 'kept specific to this customer'})`));
      await sendAIFollowUp.call(this, phone, question, answerText);
    } else if (answerType === 'media') {
      const { mediaType, mediaUrl, caption, answerNote, docFileName } = ctx;
      if (isGeneral) {
        const generalNote = answerNote + (mediaType === 'document' ? '' : ` (${mediaUrl})`);
        await this.helpers.httpRequest({ method: 'POST', url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_knowledge', headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json' }, body: JSON.stringify({ category: 'general', question, answer: generalNote, chat_id: chatId }) });
      }
      const waPayload = mediaType === 'image'
        ? { messaging_product: 'whatsapp', to: phone, type: 'image', image: { link: mediaUrl, caption: caption || '' } }
        : mediaType === 'video'
          ? { messaging_product: 'whatsapp', to: phone, type: 'video', video: { link: mediaUrl, caption: caption || '' } }
          : { messaging_product: 'whatsapp', to: phone, type: 'document', document: { link: mediaUrl, filename: docFileName || 'pricing.pdf', caption: caption || '' } };

      await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://graph.facebook.com/v19.0/' + phoneNumberId + '/messages',
        headers: { 'Authorization': 'Bearer ' + metaToken, 'Content-Type': 'application/json' },
        body: JSON.stringify(waPayload)
      });

      await this.helpers.httpRequest({ method: 'PATCH', url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/pending_questions?telegram_message_id=eq.' + replyToMessageId, headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' }, body: JSON.stringify({ status: 'answered', answer: answerNote }) });
      await this.helpers.httpRequest({ method: 'POST', url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/conversations', headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' }, body: JSON.stringify({ phone_number: phone, role: 'assistant', message: answerNote, timestamp: new Date().toISOString(), seller_id: chatId }) });

      await notifySeller.call(this, t(lang, `✅ تم الإرسال! (${isGeneral ? 'حفظته كمعرفة عامة' : 'خاص بهذا الزبون بس'})`, `✅ Sent! (${isGeneral ? 'saved as general knowledge' : 'kept specific to this customer'})`));
      await sendAIFollowUp.call(this, phone, question, answerNote);
    }
  } catch (e) {
    const metaErrorMsg = extractMetaErrorMessage(e);
    await notifySeller.call(this, t(lang, '⚠️ فشل الإرسال — ' + metaErrorMsg, '⚠️ Send failed — ' + metaErrorMsg));
  }
}

