async function saveProductFromFields(finalFields, lang, visibleMsg) {
  // Auto-detect currency from what the seller actually typed, if not already set —
  // e.g. mentioning "$" or "USD" should set their currency automatically, instead
  // of silently defaulting to IQD just because it was never explicitly asked.
  try {
    const currentConfigResp = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_sales_config?chat_id=eq.' + chatId + '&select=currency_label&limit=1',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
    });
    const currentCurrency = currentConfigResp && currentConfigResp[0] && currentConfigResp[0].currency_label;
    if (!currentCurrency) {
      const allPriceText = JSON.stringify(finalFields);
      const currencyDetectResp = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api.anthropic.com/v1/messages',
        headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
        body: JSON.stringify({
          model: 'claude-haiku-4-5-20251001',
          max_tokens: 20,
          system: 'Detect which currency is used in this text (look for symbols like $, €, £, or codes/words like USD, dollar, dinar, IQD, euro, etc). Reply with ONLY the 3-letter ISO currency code (e.g. USD, IQD, EUR), or NONE if genuinely no currency signal is present.',
          messages: [{ role: 'user', content: allPriceText }]
        })
      });
      await logAiUsage.call(this, currencyDetectResp, 'currency_auto_detect');
      const detectedCurrency = (currencyDetectResp.content[0].text || '').trim().toUpperCase();
      if (detectedCurrency && detectedCurrency !== 'NONE' && /^[A-Z]{3}$/.test(detectedCurrency)) {
        await this.helpers.httpRequest({
          method: 'POST',
          url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_sales_config?on_conflict=chat_id',
          headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'resolution=merge-duplicates' },
          body: JSON.stringify({ chat_id: chatId, currency_label: detectedCurrency })
        });
      }
    }
  } catch (e) { logSystemError.call(this, chatId, 'Saving detected currency setting', e && e.message); }

  let saveSucceeded = true;
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_products',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
      body: JSON.stringify({
        chat_id: chatId,
        product_name: finalFields.product_name || '',
        product_category: (finalFields.product_category || 'general').toLowerCase(),
        wholesale_price: finalFields.wholesale_price || null,
        retail_price: finalFields.retail_price || null,
        target_customers: finalFields.target_customers || '',
        key_features: finalFields.key_features || '',
        common_questions: finalFields.common_questions || '',
        payment_methods: finalFields.payment_methods || '',
        delivery_info: finalFields.delivery_info || '',
        competitors_difference: finalFields.competitors_difference || '',
        special_offers: finalFields.special_offers || '',
        escalation_rules: finalFields.escalation_rules || '',
              delivery_timing_preference: finalFields.delivery_timing_preference || '',
        cost_price: finalFields.cost_price || null,
        track_stock: !!finalFields.track_stock,
        stock_quantity: finalFields.stock_quantity || null,
        low_stock_threshold: finalFields.low_stock_threshold || null,
        order_flow_type: finalFields.order_flow_type || 'physical_goods',
        is_active: true,
        updated_at: new Date().toISOString()
      })
    });
  } catch (e) {
    saveSucceeded = false;
  }

  await setBotState.call(this, 'idle', {});
  if (saveSucceeded) {
    await notifySeller.call(this, visibleMsg + t(lang, '\n\n<b>تريد تضيف منتج ثاني؟</b> اكتب "أضف منتج جديد"\n<b>تريد تحذف منتج؟</b> اكتب "احذف منتج [الاسم]"', '\n\n<b>Add another product?</b> Type "add new product"\n<b>Delete a product?</b> Type "delete product [name]"'));
  } else {
    await notifySeller.call(this, t(lang, '⚠️ صار خطأ وما انحفظ المنتج. جرب مرة ثانية.', '⚠️ Something went wrong and the product wasn\'t saved. Please try again.'));
  }
  return saveSucceeded;
}

async function handleDynamicProductOnboarding(userText, lang, botState, mediaInfo, fullLanguage, fullDialect) {
  const gatheredFields = botState.context?.gathered_fields || {};
  const productHistory = botState.context?.product_history || [];

  // Detect if the seller is explicitly confirming they're done (save/done/finish/
  // complete) — used below to inject an extra, turn-specific instruction that
  // forces the model to actually emit the completion tag right now, since a
  // generic instruction from many turns earlier can get diluted in a long
  // conversation and treated as already-satisfied.
  const isExplicitFinish = /^(save|done|finish|complete|احفظ|خلص|تمام|كملنا)$/i.test((userText || '').trim());

  let sellerProfile = null;
  try {
    const rows = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/sellers?chat_id=eq.' + chatId + '&select=*&limit=1',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
    });
    sellerProfile = rows && rows.length > 0 ? rows[0] : null;
  } catch (e) { sellerProfile = null; }

  if (mediaInfo && mediaInfo.base64) {
    const contentBlock = mediaInfo.mediaType === 'application/pdf'
      ? { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: mediaInfo.base64 } }
      : { type: 'image', source: { type: 'base64', media_type: mediaInfo.mediaType || 'image/jpeg', data: mediaInfo.base64 } };
    const textBlock = { type: 'text', text: userText || 'Please read this file/image and extract product details from it.' };
    productHistory.push({ role: 'user', content: [contentBlock, textBlock] });
  } else if (userText) {
    productHistory.push({ role: 'user', content: userText });
  }

  const systemPrompt = `CRITICAL FORMATTING RULE — READ THIS FIRST: Never use markdown. Never use asterisks (* or **) for bold or emphasis. Never use bullet points or numbered lists with symbols. Telegram displays these as literal characters, not formatting, so using them makes your messages look broken. Write plain, natural conversational sentences only, exactly like a normal text message to a friend.

${aiName ? `You are ${aiName}, helping` : 'You are helping'} a business owner register a new product for their WhatsApp sales AI.

DEFAULT MODE — ASK EVERYTHING AT ONCE: Unless the seller has explicitly asked you to go one question at a time, your first message should present ALL the remaining fields you need in one single, clearly organized message — not one question per message. Structure it like this: first list the REQUIRED details you truly need (product name, at least one price — wholesale or retail, either one or both is fine depending on their business, the product's cost price, who their target customers are, and whether they want to track stock quantity for this product), then list the OPTIONAL details as a second group, explicitly telling the seller they can skip any or all of the optional ones by simply not answering them — leaving them blank is completely fine. Keep the tone natural and conversational, not like a rigid form, but make the required-vs-optional distinction clear.

IF THE SELLER SAYS SOMETHING LIKE "ask me one at a time" / "one by one" / similar: switch immediately to asking exactly one natural question per message from then on for the rest of this registration, adapting to their business and market as you go.

QUICK ADD — SAVE IMMEDIATELY WHEN POSSIBLE: If a seller's message (their very first one, or any message) already contains all the REQUIRED details (a clear product name, at least one price — wholesale or retail, either one or both is fine, the product's cost price, their target customers, and a clear answer on whether to track stock), do not ask anything else first — proceed straight to summarizing what you have and asking them to confirm with "save"/"done", exactly as usual, without demanding the optional fields be filled in. The optional fields can always be added later by editing the product.

BUSINESS PROFILE: ${sellerProfile ? `${sellerProfile.business_name_location || ''} | Selling type: ${sellerProfile.selling_type_audience || ''} | Category: ${sellerProfile.business_category || ''}` : 'Unknown — ask naturally as needed.'}

FIELDS GATHERED SO FAR FOR THIS PRODUCT: ${JSON.stringify(gatheredFields)}

FIELDS YOU STILL NEED — REQUIRED: product_name, at least one of wholesale_price/retail_price (one or both, whichever fits their business), cost_price, target_customers, track_stock (yes/no). OPTIONAL (use judgment, skip freely if the seller doesn't answer): product_category, key_features, common_questions, payment_methods, delivery_info, competitors_difference, special_offers, escalation_rules, delivery_timing_preference, order_flow_type

IMPORTANT — always ask about escalation_rules before finishing: ask the seller specifically "In which situations should I message you directly instead of handling it myself?" (or similar natural phrasing). Examples of what sellers typically say: needing exact pricing quotes, stock/availability questions, anything they haven't told you the answer to, or specific policy questions. Capture their answer as-is — this becomes the ONLY situations where you'll actually message the seller once live, so it needs to reflect what THEY actually want, not a generic assumption.

IMPORTANT — always ask about delivery_timing_preference before finishing (this varies a lot between businesses — don't assume): ask the seller specifically "When should I collect the customer's delivery address or shipping details — right when they confirm the order, or later at some other point (like once the order is ready to ship)?" (or similar natural phrasing). Different businesses genuinely work differently here — some collect address immediately, others (like B2B manufacturers with long production times) only collect it much later via a freight forwarder once goods are ready. Capture their actual answer as-is, since this directly controls when the AI asks customers for address information.

CRITICAL — CLASSIFY order_flow_type (do NOT ask this as a direct question; infer it yourself from everything the seller has already described about how their business actually works):
- "physical_goods" — sells countable physical items that get shipped/delivered somewhere (has quantities, needs a delivery address, may have wholesale/retail pricing or MOQ)
- "service_booking" — sells a service, consultation, appointment, or booking (no physical shipping, may need a date/time or location for an in-person service, no quantity in the traditional sense)
- "digital_product" — sells something delivered digitally (software, courses, digital downloads, licenses — no physical shipping, no delivery address needed)
- "subscription" — sells recurring/repeat billing access to something (a plan, membership, or ongoing service)
This determines what questions and flow the AI will use with real customers later, so get it right based on what the seller actually described — do not default to "physical_goods" just because that's common; if their business is clearly a service or digital product, classify it as such.

RULES:
- By default, ask for all remaining fields in one consolidated, clearly organized message (required fields first, then optional fields marked as skippable) — do not ask one question per message unless the seller has explicitly asked you to. Adapt the specific wording and examples to their business type and market (e.g. a clothing retailer in Erbil gets different examples than a bulk wholesaler in another city). If the seller has asked to go one at a time, follow that instead for the rest of this conversation.
- If their last answer was too vague, off-topic, or doesn't actually answer what you asked, do NOT accept it — ask a clearer, more specific follow-up instead, like a real person would.
- The seller may also send a PHOTO or PDF (e.g. a price list, product photo, catalog page, or scanned document) instead of typing. If you receive one, read it directly and extract as many product fields as you can from it (name, prices, features, etc). Then confirm what you read back to the seller and ask only about whatever's still missing or unclear.
- Once you have enough usable info to let Ahmad sell this product well (use judgment, doesn't need every field filled): do NOT immediately declare it finished. Instead, summarize what you've gathered, ask if anything's missing or needs correcting, and tell the seller to type "save" (or "done"/"confirm") once they're happy with it, to actually finalize and register the product. Only output the ONBOARDING_COMPLETE tag once the seller explicitly confirms with one of those words — never on the same turn where you first suggest things look complete.
- Reply in ${fullLanguage ? fullLanguage + (fullDialect ? ' (' + fullDialect + ' dialect/accent)' : '') : (lang === 'english' ? 'English' : 'Arabic (Iraqi dialect)')}, matching the seller's exact wording style naturally.

FINAL REMINDER BEFORE YOU ANSWER: Do not use any asterisks or markdown symbols anywhere in your reply. Plain text only.

OUTPUT FORMAT — MANDATORY, NO EXCEPTIONS:
Every single reply you write MUST end with exactly one of these two tags — there is no valid reply that omits both. This applies EVERY turn, including if the seller just said something short like "done," "continue," "yes," or "ok" — that means "finish now," which still requires the completion tag below, not just a confident-sounding closing message with no tag.

If you are asking another question (not finished yet): write your natural question to the seller, then on a new line add exactly:
[FIELDS_SO_FAR: {"field_name": "value", ...}]
(include only fields you've gathered so far, valid JSON, merge with what's already gathered)

If you have enough info and are DONE: write a short friendly confirmation message to the seller, then on a new line add exactly — this exact tag, with the closing "}]" always present, is what actually saves the product, so never skip it or the product is silently lost even if your message sounds complete:
[ONBOARDING_COMPLETE: {"product_name": "...", "product_category": "...", "wholesale_price": number or null, "retail_price": number or null, "cost_price": number or null, "target_customers": "...", "track_stock": true or false, "stock_quantity": number or null, "low_stock_threshold": number or null, "key_features": "...", "common_questions": "...", "payment_methods": "...", "delivery_info": "...", "competitors_difference": "...", "special_offers": "...", "escalation_rules": "...", "delivery_timing_preference": "...", "order_flow_type": "physical_goods" | "service_booking" | "digital_product" | "subscription"}]${isExplicitFinish ? `

THE SELLER JUST SAID THIS EXACT MESSAGE: "${userText}" — THIS MEANS THEY ARE CONFIRMING THEY ARE DONE RIGHT NOW. YOU MUST OUTPUT THE [ONBOARDING_COMPLETE: {...}] TAG IN THIS REPLY, using everything gathered across the whole conversation above. Do NOT just write a confident-sounding closing message without the tag — that alone does not save anything. The tag is mandatory in this exact reply, no matter how many times you've already said things sound finished in earlier turns.` : ''}`;

  let assistantReply = '';
  try {
    const resp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.anthropic.com/v1/messages',
      headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 1500,
        system: systemPrompt,
        messages: productHistory.length > 0 ? productHistory : [{ role: 'user', content: 'Start asking me about my new product.' }]
      })
    });
    await logAiUsage.call(this, resp, 'product_onboarding_conversation');
    assistantReply = (resp && resp.content && resp.content[0] && resp.content[0].text) || '';
    assistantReply = assistantReply.replace(/\*\*/g, '').replace(/\*/g, ''); // safety net — strip any markdown asterisks regardless of prompt compliance
  } catch (e) {
    await notifySeller.call(this, t(lang, '⚠️ صار خطأ، جرب مرة ثانية.', '⚠️ Something went wrong, please try again.'));
    return;
  }

  productHistory.push({ role: 'assistant', content: assistantReply });

  const completeJsonStr = extractTaggedJson(assistantReply, 'ONBOARDING_COMPLETE');
  const fieldsJsonStr = extractTaggedJson(assistantReply, 'FIELDS_SO_FAR');

  // Safety net: if the model started an ONBOARDING_COMPLETE block but the object
  // itself never closes (a genuine truncation, e.g. cut off mid-string by a token
  // limit) — extractTaggedJson returns null in that specific case. This is
  // different from the model simply forgetting a trailing "]", which is now
  // handled correctly above without needing a retry.
  if (!completeJsonStr && /\[ONBOARDING_COMPLETE:/.test(assistantReply)) {
    await notifySeller.call(this, t(lang,
      '⚠️ صار خطأ بسيط وما اكتملت المعلومات بشكل صحيح. اكتب "خلص" أو "تمام" لأعيد المحاولة.',
      "⚠️ That took a bit long and got cut off before finishing. Just type \"done\" or \"continue\" and I'll wrap it up properly."
    ));
    await setBotState.call(this, 'onboarding', { phase: 'specific', gathered_fields: gatheredFields, product_history: productHistory });
    return;
  }

  if (completeJsonStr) {
    let finalFields = {};
    try { finalFields = JSON.parse(completeJsonStr); } catch (e) { finalFields = gatheredFields; }
    const visibleMsg = assistantReply.replace(/\[ONBOARDING_COMPLETE:[\s\S]*$/, '').trim();
    await saveProductFromFields.call(this, finalFields, lang, visibleMsg);
    return;
  }

  // Last resort only: the seller explicitly confirmed they're done, and even with
  // the strengthened turn-specific instruction above, the model still didn't
  // produce the tag. Rather than leaving the seller stuck in limbo, save using
  // whatever's already accumulated in gathered_fields — but this only ever runs
  // after the AI genuinely had its chance to tag it correctly first.
  if (isExplicitFinish && gatheredFields && gatheredFields.product_name) {
    const visibleMsg = assistantReply.replace(/\[FIELDS_SO_FAR:[\s\S]*$/, '').trim() || t(lang, '✅ تم حفظ المنتج بنجاح!', '✅ Product saved successfully!');
    await saveProductFromFields.call(this, gatheredFields, lang, visibleMsg);
    return;
  }

  let newGathered = gatheredFields;
  if (fieldsJsonStr) {
    try { newGathered = JSON.parse(fieldsJsonStr); } catch (e) { newGathered = gatheredFields; }
  }
  const visibleMsg = assistantReply.replace(/\[FIELDS_SO_FAR:[\s\S]*$/, '').trim();

  await setBotState.call(this, 'onboarding', { phase: 'specific', gathered_fields: newGathered, product_history: productHistory });
  await notifySeller.call(this, visibleMsg);
}

