async function extractAndLearnFromConversation(customerPhone, outcome) {
  try {
    // Fetch the conversation
    const convResponse = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/conversations?phone_number=eq.' + customerPhone + '&select=role,message,timestamp&order=timestamp.asc&limit=50',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
    });
    const conversations = convResponse || [];
    if (conversations.length < 3) return; // Not enough to learn from

    const conversationText = conversations.map(m => `${m.role === 'user' ? 'Customer' : 'Ahmad'}: ${m.message}`).join('\n');

    // ═══ FETCH THIS SELLER'S REAL BUSINESS CONTEXT (generic, not hardcoded) ═══
    let myBizDesc = 'this business';
    let myBizCategory = 'general';
    try {
      const myProfile = await this.helpers.httpRequest({ method: 'GET', url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/sellers?chat_id=eq.' + chatId + '&select=business_name_location,business_category&limit=1', headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey } });
      if (myProfile && myProfile.length > 0) {
        myBizDesc = myProfile[0].business_name_location || myBizDesc;
        myBizCategory = myProfile[0].business_category || myBizCategory;
      }
    } catch (e) { logSystemError.call(this, chatId, 'Fetching business profile info', e && e.message); }

    // Ask Claude to extract intelligence
    const learningResponse = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.anthropic.com/v1/messages',
      headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 500,
        system: `You extract sales intelligence from conversations for ${myBizDesc}.
Return ONLY JSON:
{
  "product_category": "${myBizCategory}",
  "market": "local_market",
  "customer_type": "wholesale" or "retail",
  "outcome": "ordered" or "rejected" or "pending",
  "what_worked": "what approach or message moved the customer forward",
  "objection_type": "price" or "quality" or "timing" or "supplier" or "none",
  "objection_resolution": "how was the objection handled",
  "conversation_summary": "2-3 sentence summary of the conversation",
  "winning_message": "the single most effective message in the conversation"
}
Return ONLY valid JSON.`,
        messages: [{ role: 'user', content: `Outcome: ${outcome}\n\nConversation:\n${conversationText}` }]
      })
    });

    await logAiUsage.call(this, learningResponse, 'learning_intelligence_extraction');
    let intelligence = null;
    try {
      intelligence = JSON.parse(learningResponse.content[0].text.trim().replace(/```json|```/g, ''));
    } catch(e) { return; }

    // Save to intelligence_logs
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/intelligence_logs',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
      body: JSON.stringify({
        product_category: intelligence.product_category || myBizCategory,
        market: intelligence.market || 'iraq_wholesale',
        customer_type: intelligence.customer_type || 'unknown',
        outcome: intelligence.outcome || outcome,
        what_worked: intelligence.what_worked || '',
        objection_type: intelligence.objection_type || 'none',
        objection_resolution: intelligence.objection_resolution || '',
        conversation_summary: intelligence.conversation_summary || '',
        created_at: new Date().toISOString()
      })
    });

    // Update product_playbooks with new learnings
    await updatePlaybook.call(this, intelligence);

  } catch(e) {
    // Silent fail — learning is background task
  }
}

async function updatePlaybook(intelligence) {
  try {
    const category = intelligence.product_category || myBizCategory;

    // Get existing playbook
    const existing = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/product_playbooks?product_category=eq.' + category + '&select=*&limit=1',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
    });

    const pb = existing && existing.length > 0 ? existing[0] : null;
    const currentObjestions = pb ? (pb.common_objections || []) : [];
    const currentWinning = pb ? (pb.winning_responses || []) : [];
    const totalConvs = pb ? ((pb.total_conversations || 0) + 1) : 1;
    const totalOrders = pb ? ((pb.total_orders || 0) + (intelligence.outcome === 'ordered' ? 1 : 0)) : (intelligence.outcome === 'ordered' ? 1 : 0);
    const closeRate = totalConvs > 0 ? Math.round((totalOrders / totalConvs) * 100) : 0;

    // Add new objection if found and not duplicate
    let updatedObjections = [...currentObjestions];
    if (intelligence.objection_type && intelligence.objection_type !== 'none' && intelligence.objection_resolution) {
      const exists = updatedObjections.some(o => o.objection === intelligence.objection_type);
      if (!exists) {
        updatedObjections.push({ objection: intelligence.objection_type, response: intelligence.objection_resolution });
        if (updatedObjections.length > 20) updatedObjections = updatedObjections.slice(-20);
      }
    }

    // Add winning message if order was placed
    let updatedWinning = [...currentWinning];
    if (intelligence.outcome === 'ordered' && intelligence.winning_message) {
      if (!updatedWinning.includes(intelligence.winning_message)) {
        updatedWinning.push(intelligence.winning_message);
        if (updatedWinning.length > 10) updatedWinning = updatedWinning.slice(-10);
      }
    }

    const updateData = {
      common_objections: updatedObjections,
      winning_responses: updatedWinning,
      total_conversations: totalConvs,
      total_orders: totalOrders,
      close_rate_percentage: closeRate,
      last_updated: new Date().toISOString()
    };

    if (pb) {
      await this.helpers.httpRequest({
        method: 'PATCH',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/product_playbooks?product_category=eq.' + category,
        headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
        body: JSON.stringify(updateData)
      });
    } else {
      await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/product_playbooks',
        headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
        body: JSON.stringify({ product_category: category, market: 'iraq_wholesale', ...updateData })
      });
    }
  } catch (e) { logSystemError.call(this, chatId, 'Updating product category', e && e.message); }
}

