// MESSAGE VOLUME — how many customer messages/conversations happened,
// optionally within a specific date range. Genuine, honest data, no guessing.
// ═══════════════════════════════════════════════
async function handleMessageVolume(userText, lang) {
  try {
    const todayForDateMath = new Date().toISOString().split('T')[0];
    const extractResp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.anthropic.com/v1/messages',
      headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 100,
        system: `Today's real date is ${todayForDateMath}. Use this to correctly compute any relative date phrase (e.g. "last 7 days", "this month", "yesterday") — do NOT guess or assume any other date. Extract the date range mentioned in this message about message/conversation volume. Reply with ONLY this JSON:
{
  "since": "YYYY-MM-DD or null if no start date mentioned",
  "until": "YYYY-MM-DD or null if no end date mentioned (use ${todayForDateMath} if they said something like 'until now')"
}
IMPORTANT: if a date is written like "1/7/2026" (day/month/year, ambiguous slash format), interpret it as DAY/MONTH/YEAR (so "1/7/2026" = July 1st, 2026), NOT month/day/year — this is the more common convention outside the US. Only use month/day interpretation if the numbers make DD/MM impossible (e.g. "13/2/2026" must be Feb 13, since there's no 13th month).`,
        messages: [{ role: 'user', content: userText }]
      })
    });
    await logAiUsage.call(this, extractResp, 'message_volume_date_extraction');
    const rawExtractText = (extractResp && extractResp.content && extractResp.content[0] && extractResp.content[0].text) || 'NO_RESPONSE';
    let dateRange = { since: null, until: null };
    try { dateRange = JSON.parse(rawExtractText.trim().replace(/```json|```/g, '')); } catch (e) { logSystemError.call(this, chatId, 'Parsing date range from AI response', e && e.message); }

    let url = 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/conversations?seller_id=eq.' + chatId + '&role=eq.user&select=id';
    if (dateRange.since) url += '&timestamp=gte.' + dateRange.since;
    if (dateRange.until) url += '&timestamp=lte.' + dateRange.until + 'T23:59:59';

    const resp = await this.helpers.httpRequest({
      method: 'GET',
      url: url + '&limit=10000',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Prefer': 'count=exact' }
    });
    const count = Array.isArray(resp) ? resp.length : 0;

    const periodLabel = (dateRange.since && dateRange.until)
      ? `${dateRange.since} to ${dateRange.until}`
      : (lang === 'english' ? 'all time' : 'كل الفترة');

    await notifySeller.call(this, t(lang,
      `📩 استلمت ${count} رسالة من الزبائن (${periodLabel})`,
      `📩 You received ${count} customer message(s) (${periodLabel})`
    ));
  } catch (e) {
    await notifySeller.call(this, '⚠️ ' + e.message);
  }
}

