async function handlePosToggle(userText, lang) {
  const turningOn = /شغل|فعل|enable|turn on|activate/i.test(userText);
  const turningOff = /أوقف|ايقاف|disable|turn off|deactivate|stop/i.test(userText);

  // Follow-up and broadcast are NOT true POS features (they live in bot_settings,
  // not pos_settings), so they're handled as a special case here rather than through
  // updatePosSettings, which would silently write to the wrong table.
  if (/follow.?up|متابعة/i.test(userText)) {
    await updateSetting.call(this, 'followup_active', turningOn ? 'true' : (turningOff ? 'false' : 'true'));
    await notifySeller.call(this, t(lang,
      turningOff ? '✅ المتابعة متوقفة.' : '✅ المتابعة مفعّلة.',
      turningOff ? '✅ Follow-up OFF.' : '✅ Follow-up ON.'
    ));
    return;
  }
  if (/broadcast|بث/i.test(userText)) {
    await updateSetting.call(this, 'broadcast_active', turningOn ? 'true' : (turningOff ? 'false' : 'true'));
    await notifySeller.call(this, t(lang,
      turningOff ? '✅ البث متوقف.' : '✅ البث مفعّل.',
      turningOff ? '✅ Broadcast OFF.' : '✅ Broadcast ON.'
    ));
    return;
  }

  let field = null;
  if (/مخزون|inventory|stock/i.test(userText) && !/نفاد|low stock|alert|تنبيه/i.test(userText)) field = 'inventory_tracking_active';
  else if (/نفاد|low stock|alert|تنبيه/i.test(userText)) field = 'low_stock_alerts_active';
  else if (/فاتورة|فواتير|invoice/i.test(userText)) field = 'auto_invoice_active';

  if (!field) {
    await notifySeller.call(this, t(lang, '⚠️ ما فهمت شنو الميزة اللي تريد تشغلها/توقفها. اكتب "عرض POS" لتشوف الميزات المتوفرة.', '⚠️ Not sure which feature you mean. Type "show POS" to see available features.'));
    return;
  }

  await updatePosSettings.call(this, { [field]: turningOn ? true : (turningOff ? false : true) });
  await showPosMenu.call(this, lang);
}

