// ═══════════════════════════════════════════════
// AD REGISTRATION — lets a seller link a Meta ad ID to a product/offer
// conversationally, writing to ad_product_mapping (owned by the parallel
// Meta Ads integration work — this function only inserts/updates rows,
// never touches that table's structure).
// ═══════════════════════════════════════════════
// ═══════════════════════════════════════════════
// SET AD ACCOUNT ID — a narrow, dedicated setter for just this one field
// on seller_ad_config, since that table's other fields (tokens) are too
// sensitive for generic free-form editing. Also helps a seller who doesn't
// know where to find this ID yet.
// ═══════════════════════════════════════════════
// ═══════════════════════════════════════════════
// META ADS MANAGEMENT — conversational campaign/ad-set/ad viewing, editing,
// and strategy discussion. Covers: performance reports with AI commentary,
// pausing/resuming/budget changes, and open strategic conversation using
// real performance data as context.
// ═══════════════════════════════════════════════
function resolveAdDateRange(plan) {
  // Returns { urlParam: string to append to the Meta Insights URL, label: human-readable description, daysBack: approx days for our own date math }
  const range = plan.date_range;
  if (range === 'custom' && plan.custom_since && plan.custom_until) {
    return {
      urlParam: 'time_range=' + encodeURIComponent(JSON.stringify({ since: plan.custom_since, until: plan.custom_until })),
      label: plan.custom_since + ' to ' + plan.custom_until,
      daysBack: Math.max(1, Math.round((new Date(plan.custom_until) - new Date(plan.custom_since)) / (1000 * 60 * 60 * 24)))
    };
  }
  const presetMap = {
    today: { preset: 'today', label: 'today', daysBack: 1 },
    yesterday: { preset: 'yesterday', label: 'yesterday', daysBack: 2 },
    last_7d: { preset: 'last_7d', label: 'the last 7 days', daysBack: 7 },
    last_30d: { preset: 'last_30d', label: 'the last 30 days', daysBack: 30 },
    last_90d: { preset: 'last_90d', label: 'the last 90 days', daysBack: 90 },
    this_year: { preset: 'this_year', label: 'this year', daysBack: 365 },
    last_year: { preset: 'last_year', label: 'last year', daysBack: 365 }
  };
  const chosen = presetMap[range] || presetMap.last_7d;
  return { urlParam: 'date_preset=' + chosen.preset, label: chosen.label, daysBack: chosen.daysBack };
}

async function getAdConfigForManagement() {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_ad_config?chat_id=eq.' + chatId + '&select=ad_account_id,meta_ads_token,enabled&limit=1',
    headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
  });
  return resp && resp.length > 0 ? resp[0] : null;
}

// Wraps findMetaObjectsByName with a fallback: if the hint is a raw numeric ID and the
// guessed level finds nothing, the ID might actually belong to a different level (e.g. an
// ad ID when the classifier assumed "campaign") — retry the other levels before giving up.
async function resolveMetaObjectsWithIdFallback(nameHint, level, adAccountPath, token) {
  const first = await findMetaObjectsByName.call(this, nameHint, level, adAccountPath, token);
  if (first.length > 0) return { matches: first, resolvedLevel: level };
  if (nameHint && /^\d{10,}$/.test(nameHint.trim())) {
    const otherLevels = ['campaign', 'adset', 'ad'].filter(l => l !== level);
    for (const tryLevel of otherLevels) {
      const retry = await findMetaObjectsByName.call(this, nameHint, tryLevel, adAccountPath, token);
      if (retry.length > 0) return { matches: retry, resolvedLevel: tryLevel };
    }
  }
  return { matches: first, resolvedLevel: level };
}

async function findMetaObjectsByName(nameHint, level, adAccountPath, token) {
  // level: 'campaign' | 'adset' | 'ad'
  const endpoint = level === 'campaign' ? 'campaigns' : level === 'adset' ? 'adsets' : 'ads';
  // daily_budget/lifetime_budget only exist on campaigns and ad sets — requesting them
  // for individual ads makes Meta reject the whole call with a 400.
  const budgetFields = level === 'ad' ? '' : ',daily_budget,lifetime_budget';
  let resp;
  try {
    resp = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://graph.facebook.com/v19.0/' + adAccountPath + '/' + endpoint + '?fields=id,name,status' + budgetFields + '&limit=100&access_token=' + token
    });
  } catch (e) {
    return [];
  }
  const all = (resp && resp.data) || [];
  if (!nameHint) return all;
  const trimmedHint = nameHint.trim();
  // A hint that's purely numeric (10+ digits, matching Meta's real ID format) is almost
  // certainly a literal object ID the seller copy-pasted — match it exactly, not as a
  // name substring (numeric IDs never appear inside human-readable ad/campaign names).
  if (/^\d{10,}$/.test(trimmedHint)) {
    const idMatch = all.filter(o => o.id === trimmedHint);
    if (idMatch.length > 0) return idMatch;
  }
  const lower = trimmedHint.toLowerCase();
  return all.filter(o => (o.name || '').toLowerCase().includes(lower));
}

// Fetches child objects (ad sets under a campaign, or ads under an ad set) scoped to ONE
// specific parent, instead of searching the whole ad account — avoids false-positive name
// matches across unrelated campaigns that happen to share similar ad set/ad names.
async function findChildMetaObjects(parentNameHint, childLevel, adAccountPath, token) {
  const parentLevel = childLevel === 'adset' ? 'campaign' : 'adset';
  const parentMatches = await findMetaObjectsByName.call(this, parentNameHint, parentLevel, adAccountPath, token);
  if (parentMatches.length !== 1) return { parentMatches, children: null };
  const parent = parentMatches[0];
  const childEndpoint = childLevel === 'adset' ? 'adsets' : 'ads';
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://graph.facebook.com/v19.0/' + parent.id + '/' + childEndpoint + '?fields=id,name,status&limit=100&access_token=' + token
  });
  const children = (resp && resp.data) || [];
  return { parentMatches, parent, children };
}

async function manageMetaAds(userText, lang) {
  try {
    const adConfig = await getAdConfigForManagement.call(this);
    if (!adConfig || !adConfig.ad_account_id || !adConfig.meta_ads_token) {
      await notifySeller.call(this, t(lang,
        '⚠️ لسا ما سويت اعداد حساب الاعلانات. ابعثلي: "رقم حساب الاعلانات هو ..."',
        '⚠️ Ads account isn\'t set up yet. Send me: "my ad account id is ..."'
      ));
      return;
    }
    const adAccountPath = adConfig.ad_account_id.startsWith('act_') ? adConfig.ad_account_id : 'act_' + adConfig.ad_account_id;
    const token = adConfig.meta_ads_token;
    const todayForAdsDateMath = new Date().toISOString().split('T')[0];

    // Classify what the seller actually wants
    const planResp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.anthropic.com/v1/messages',
      headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 300,
        system: `Today's real date is ${todayForAdsDateMath}. Use this to correctly compute any relative date phrase (e.g. "since last month", "the past 2 weeks") if the seller uses one for a custom range — do NOT guess or assume any other date.

Classify this seller's request about their Meta ad account. Reply with ONLY this JSON:
{
  "intent": "view_report" | "edit" | "strategy_discussion" | "set_metric_preference" | "set_alert_rule" | "true_roas" | "list_structure" | "set_daily_digest",
  "level": "campaign" | "adset" | "ad" | null,
  "name_hint": "any campaign/ad set/ad name OR raw numeric ID they mentioned (e.g. 'ad 120247804554290311' => name_hint: '120247804554290311'), or null",
  "parent_hint": "if they're asking about ad sets/ads WITHIN a specific campaign/ad set (e.g. 'how many ad sets in my 27/6/2026 campaign'), the name of that PARENT campaign/ad set — or null",
  "date_range": "today" | "yesterday" | "last_7d" | "last_30d" | "last_90d" | "this_year" | "last_year" | "custom" | null,
  "custom_since": "for date_range=custom only — start date in YYYY-MM-DD format, or null",
  "custom_until": "for date_range=custom only — end date in YYYY-MM-DD format, or null",
  "edit_action": "pause" | "activate" | "set_budget" | "rename" | null,
  "new_budget": "null, or the plain daily budget number exactly as the seller said it, in normal currency units (NOT cents/smallest-unit) — e.g. \"$10/day\" => 10, \"set budget to 15000\" => 15000. Do not convert or divide it yourself; that conversion happens elsewhere in the code.",
  "new_name": null or a string,
  "requested_metrics": ["array of specific Meta ad metrics they asked about, using these exact field names: spend, impressions, clicks, ctr, cpc, cpm, reach, frequency, unique_clicks, actions (for conversions/purchases), messages_started (for how many people started a WhatsApp conversation because of the ad — use this for questions like 'how many people messaged us', 'how many conversations did this campaign generate'), cpa (cost per purchase/acquisition — use this for questions like 'what's my CPA', 'cost per purchase', 'cost per acquisition', 'cost per conversion' — this is DIFFERENT from cpc, which is cost per click), cost_per_message (cost per messaging conversation started — different from cpa/cost per sale), roas (return on ad spend) — empty array if they didn't ask for anything specific. For set_daily_digest, list every metric they want included in their recurring daily report."],
  "alert_metric": "for set_alert_rule only — one of: ctr, cpc, cpm, spend, cost_per_purchase — or null",
  "alert_condition": "for set_alert_rule only — 'above' or 'below' — or null",
  "alert_threshold": "for set_alert_rule only — a number — or null"
}
- "view_report" = they want to see PERFORMANCE/metrics/spend/results (could be asking for everything, or specific metrics — check requested_metrics)
- "list_structure" = they want a factual STRUCTURAL answer about what exists — how many campaigns/ad sets/ads there are, or their names/status — NOT performance data (e.g. "how many ad sets do I have", "how many ad sets are in my 27/6/2026 campaign", "what ad sets do I have", "list my campaigns"). If they mention a specific parent campaign/ad set by name, put it in parent_hint and set level to what they're counting (e.g. asking about ad sets inside a campaign => level: "adset", parent_hint: that campaign's name).
- "edit" = they want to pause, resume, change budget, or rename something
- "strategy_discussion" = they're sharing an idea, asking what to test, or want advice — not asking for raw numbers or a specific edit
- "set_metric_preference" = they want to SAVE which metrics they want to see by default going forward WHEN THEY ASK A QUESTION (e.g. "always show me CPA and reach", "I only care about spend and purchases from now on") — this is NOT a recurring automatic daily message, just a default for when they ask something themselves
- "set_daily_digest" = they want a recurring AUTOMATIC message sent to them EVERY DAY (without asking) with specific metrics — e.g. "every day send me ad spend, cost per message, cost per sale, and ROAS", "send me a daily ads report with CPC and reach", "give me my ad numbers every day automatically". The key distinguishing signal is "every day"/"daily"/"automatically" — this is fundamentally different from set_metric_preference, which only affects what shows up when they ask a question themselves.
- "set_alert_rule" = they want to set up a custom alert/threshold (e.g. "alert me if CTR drops below 2%", "tell me if CPC goes above 1 dollar")
- "true_roas" = they want their REAL profit-based ROAS/ROI, using actual product cost and real sales — not just Meta's standard purchase-value ROAS (e.g. "what's my real ROAS", "am I actually profitable on ads", "calculate my true return including costs")
Default level to "campaign" if unclear. Default date_range to "last_7d" if unclear.`,
        messages: [{ role: 'user', content: userText }]
      })
    });
    await logAiUsage.call(this, planResp, 'ads_intent_classification');
    let plan = { intent: 'strategy_discussion', level: 'campaign', name_hint: null, parent_hint: null, date_range: 'last_7d', requested_metrics: [] };
    try { plan = JSON.parse(planResp.content[0].text.trim().replace(/```json|```/g, '')); } catch (e) { logSystemError.call(this, chatId, 'Parsing analytics query plan from AI response', e && e.message); }

    // ═══ SET METRIC PREFERENCE ═══
    if (plan.intent === 'set_metric_preference') {
      if (!plan.requested_metrics || plan.requested_metrics.length === 0) {
        await notifySeller.call(this, t(lang, '⚠️ ما فهمت شنو المقاييس اللي تريدها بالضبط.', "⚠️ Couldn't tell exactly which metrics you want."));
        return;
      }
      await this.helpers.httpRequest({
        method: 'PATCH',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_ad_config?chat_id=eq.' + chatId,
        headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
        body: JSON.stringify({ preferred_metrics: plan.requested_metrics })
      });
      await notifySeller.call(this, t(lang, `✅ تمام، من الحين راح أعرضلك هذي المقاييس بشكل افتراضي: ${plan.requested_metrics.join(', ')}`, `✅ Got it — I'll show you these by default from now on: ${plan.requested_metrics.join(', ')}`));
      return;
    }

    // ═══ SET DAILY AD METRICS DIGEST (recurring automatic daily message) ═══
    if (plan.intent === 'set_daily_digest') {
      if (!plan.requested_metrics || plan.requested_metrics.length === 0) {
        await notifySeller.call(this, t(lang, '⚠️ ما فهمت شنو المقاييس اللي تريدها باليومية.', "⚠️ Couldn't tell exactly which metrics you want in the daily digest."));
        return;
      }
      await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/ad_daily_digest_config?on_conflict=chat_id',
        headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'resolution=merge-duplicates' },
        body: JSON.stringify({ chat_id: chatId, enabled: true, metrics: plan.requested_metrics })
      });
      await notifySeller.call(this, t(lang,
        `✅ تمام، بعد اليوم راح أرسلك هذي المقاييس تلقائياً كل يوم مع ملخص المبيعات: ${plan.requested_metrics.join(', ')}`,
        `✅ Done — starting today, I'll automatically send you these ad metrics every day along with your daily sales summary: ${plan.requested_metrics.join(', ')}`
      ));
      return;
    }

    // ═══ SET CUSTOM ALERT RULE ═══
    if (plan.intent === 'set_alert_rule') {
      if (!plan.alert_metric || !plan.alert_condition || plan.alert_threshold === null || plan.alert_threshold === undefined) {
        await notifySeller.call(this, t(lang, '⚠️ ما فهمت شروط التنبيه بالضبط. مثال: "نبهني اذا الـ CTR نزل تحت 2%"', '⚠️ Couldn\'t tell the alert condition exactly. Example: "alert me if CTR drops below 2%"'));
        return;
      }
      const existingRulesResp = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_ad_config?chat_id=eq.' + chatId + '&select=custom_alert_rules&limit=1',
        headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
      });
      let rules = (existingRulesResp && existingRulesResp[0] && existingRulesResp[0].custom_alert_rules) || [];
      if (!Array.isArray(rules)) rules = [];
      rules.push({ metric: plan.alert_metric, condition: plan.alert_condition, threshold: plan.alert_threshold });

      await this.helpers.httpRequest({
        method: 'PATCH',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_ad_config?chat_id=eq.' + chatId,
        headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
        body: JSON.stringify({ custom_alert_rules: rules })
      });
      await notifySeller.call(this, t(lang, `✅ تمام، راح أنبهك اذا ${plan.alert_metric} صار ${plan.alert_condition === 'above' ? 'فوق' : 'تحت'} ${plan.alert_threshold}`, `✅ Got it — I'll alert you if ${plan.alert_metric} goes ${plan.alert_condition} ${plan.alert_threshold}`));
      return;
    }

    // ═══ TRUE ROAS (real profit-based, using actual product cost) ═══
    if (plan.intent === 'true_roas') {
      const dateInfo = resolveAdDateRange(plan);
      const daysBack = dateInfo.daysBack;
      const sinceDate = new Date(Date.now() - daysBack * 24 * 60 * 60 * 1000).toISOString();

      // If the seller named or ID'd a specific ad, scope both the spend and the
      // matched orders to just that ad instead of always computing account-wide.
      let scopedAdId = null;
      let scopedAdName = null;
      let scopedProductFilter = null;
      if (plan.name_hint) {
        const { matches: hintMatches, resolvedLevel } = await resolveMetaObjectsWithIdFallback.call(this, plan.name_hint, plan.level || 'ad', adAccountPath, token);
        if (hintMatches.length === 0) {
          await notifySeller.call(this, t(lang, '⚠️ ما لقيت شي بهذا الاسم أو الرقم.', "⚠️ Couldn't find anything with that name or ID."));
          return;
        }
        if (hintMatches.length > 1) {
          const names = hintMatches.map(m => m.name).join(', ');
          await notifySeller.call(this, t(lang, `⚠️ لقيت أكثر من واحد: ${names}. حدد اكثر بالضبط.`, `⚠️ Found more than one match: ${names}. Be more specific.`));
          return;
        }
        if (resolvedLevel !== 'ad') {
          await notifySeller.call(this, t(lang,
            '⚠️ حالياً أكدر أحسب الربح الحقيقي لإعلان واحد بس، مو لكامبين أو أدست كامل. حدد اسم أو رقم إعلان معين.',
            "⚠️ Right now I can calculate true profit for one specific ad, but not yet for a whole campaign or ad set. Name a specific ad instead."
          ));
          return;
        }
        scopedAdId = hintMatches[0].id;
        scopedAdName = hintMatches[0].name;

        // Find which product this ad is mapped to, so we can filter orders to it.
        try {
          const mappingResp = await this.helpers.httpRequest({
            method: 'GET',
            url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/ad_product_mapping?chat_id=eq.' + chatId + '&ad_id=eq.' + scopedAdId + '&select=product_name',
            headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
          });
          scopedProductFilter = (mappingResp && mappingResp[0] && mappingResp[0].product_name) || null;
        } catch (e) { logSystemError.call(this, chatId, 'Fetching ad-to-product name mapping', e && e.message); }

        if (!scopedProductFilter) {
          await notifySeller.call(this, t(lang,
            `⚠️ الإعلان "${scopedAdName}" مو مربوط بمنتج بعد، فما أكدر أحسب الربح الحقيقي المحدد له. جاوبني بأي منتج هذا الإعلان — مثلاً "ad ${scopedAdName} is for [product]"`,
            `⚠️ "${scopedAdName}" isn't linked to a product yet, so I can't calculate true profit specifically for it. Tell me what product it's for — e.g. "ad ${scopedAdName} is for [product]"`
          ));
          return;
        }
      }

      // Real ad spend for the period — scoped to the specific ad if one was resolved,
      // otherwise the whole account as before.
      let adSpend = 0;
      try {
        const spendUrl = scopedAdId
          ? 'https://graph.facebook.com/v19.0/' + scopedAdId + '/insights?fields=spend&' + dateInfo.urlParam + '&access_token=' + token
          : 'https://graph.facebook.com/v19.0/' + adAccountPath + '/insights?level=account&fields=spend&' + dateInfo.urlParam + '&access_token=' + token;
        const spendResp = await this.helpers.httpRequest({ method: 'GET', url: spendUrl });
        adSpend = parseFloat((spendResp && spendResp.data && spendResp.data[0] && spendResp.data[0].spend) || 0);
      } catch (e) { logSystemError.call(this, chatId, 'Fetching ad spend data from Meta', e && e.message); }

      if (adSpend === 0) {
        await notifySeller.call(this, t(lang, '📊 ما لكيت مصاريف اعلانات بهذي الفترة.', '📊 No ad spend found for this period.'));
        return;
      }

      // Real completed orders for the period — filtered to the ad's mapped product
      // when scoped to a specific ad. NOTE: this matches by product name, which is an
      // approximation (any order for that product counts, not just ones proven to have
      // clicked through this exact ad) — precise per-order ad attribution would need
      // customers.ctwa_clid/ad_id (owned by the ads-attribution conversation).
      let ordersUrl = 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/orders?seller_id=eq.' + chatId + '&order_status=eq.DELIVERED&created_at=gte.' + sinceDate + '&select=id,product_name,order_total,amount_received';
      const ordersResp = await this.helpers.httpRequest({
        method: 'GET',
        url: ordersUrl,
        headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
      });
      let orders = ordersResp || [];
      if (scopedProductFilter) {
        orders = orders.filter(o => o.product_name && o.product_name.toLowerCase().includes(scopedProductFilter.toLowerCase()));
      }

      if (orders.length === 0) {
        await notifySeller.call(this, t(lang, '📊 ما لكيت طلبات مكتملة بهذي الفترة لأحسب الربح الحقيقي.', "📊 No completed orders found in this period to calculate real profit."));
        return;
      }

      // Load products with their cost prices, for matching
      const productsResp = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_products?chat_id=eq.' + chatId + '&select=product_name,cost_price',
        headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
      });
      const products = productsResp || [];

      // Load structured line items for these orders, if any exist (precise path)
      const orderIds = orders.map(o => o.id).filter(Boolean);
      let itemsByOrderId = {};
      if (orderIds.length > 0) {
        try {
          const itemsResp = await this.helpers.httpRequest({
            method: 'GET',
            url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/order_items?seller_id=eq.' + chatId + '&order_id=in.(' + orderIds.join(',') + ')&select=order_id,product_name,quantity',
            headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
          });
          for (const item of (itemsResp || [])) {
            if (!itemsByOrderId[item.order_id]) itemsByOrderId[item.order_id] = [];
            itemsByOrderId[item.order_id].push(item);
          }
        } catch (e) { logSystemError.call(this, chatId, 'Grouping order line items', e && e.message); }
      }

      let totalRevenue = 0;
      let totalCogs = 0;
      let ordersWithKnownCost = 0;
      let ordersWithUnknownCost = 0;
      let usedPreciseItemsCount = 0;

      for (const order of orders) {
        const revenue = (order.amount_received !== null && order.amount_received !== undefined) ? order.amount_received : (order.order_total || 0);
        totalRevenue += revenue;

        const preciseItems = itemsByOrderId[order.id];

        if (preciseItems && preciseItems.length > 0) {
          // Precise path: sum cost across every actual line item, by quantity
          let orderCogs = 0;
          let anyKnown = false;
          for (const item of preciseItems) {
            const matched = products.find(p => p.product_name && item.product_name && p.product_name.toLowerCase() === item.product_name.toLowerCase());
            if (matched && matched.cost_price) {
              orderCogs += matched.cost_price * (item.quantity || 1);
              anyKnown = true;
            }
          }
          totalCogs += orderCogs;
          if (anyKnown) { ordersWithKnownCost++; usedPreciseItemsCount++; } else { ordersWithUnknownCost++; }
        } else {
          // Fallback path (older orders without structured items): best-effort match on first product mentioned
          const matched = products.find(p => p.product_name && order.product_name && order.product_name.toLowerCase().includes(p.product_name.toLowerCase()));
          if (matched && matched.cost_price) {
            totalCogs += matched.cost_price;
            ordersWithKnownCost++;
          } else {
            ordersWithUnknownCost++;
          }
        }
      }

      const metaStyleRoas = adSpend > 0 ? (totalRevenue / adSpend) : 0;
      const trueProfit = totalRevenue - totalCogs - adSpend;
      const trueRoas = adSpend > 0 ? ((totalRevenue - totalCogs) / adSpend) : 0;

      const curSuffixRoas = globalCurrencyLabel ? ' ' + globalCurrencyLabel : '';
      const titleSuffix = scopedAdName ? ` — "${scopedAdName}"` : '';
      let responseMsg = t(lang,
        `📊 <b>الربح الحقيقي${titleSuffix} (${dateInfo.label})</b>\n\nالمبيعات: ${totalRevenue.toLocaleString()}${curSuffixRoas}\nتكلفة المنتجات المعروفة: ${totalCogs.toLocaleString()}${curSuffixRoas}\nمصاريف الاعلانات: ${adSpend.toLocaleString()}${curSuffixRoas}\n\n<b>الربح الصافي: ${trueProfit.toLocaleString()}${curSuffixRoas}</b>\nROAS الحقيقي (بعد خصم التكلفة): ${trueRoas.toFixed(2)}x\nROAS العادي (بدون خصم التكلفة، مثل ميتا): ${metaStyleRoas.toFixed(2)}x`,
        `📊 <b>Real Profit${titleSuffix} (${dateInfo.label})</b>\n\nRevenue: ${totalRevenue.toLocaleString()}${curSuffixRoas}\nKnown product costs: ${totalCogs.toLocaleString()}${curSuffixRoas}\nAd spend: ${adSpend.toLocaleString()}${curSuffixRoas}\n\n<b>Net profit: ${trueProfit.toLocaleString()}${curSuffixRoas}</b>\nTrue ROAS (after real costs): ${trueRoas.toFixed(2)}x\nStandard ROAS (like Meta shows, before costs): ${metaStyleRoas.toFixed(2)}x`
      );
      if (scopedAdId) {
        responseMsg += t(lang,
          `\n\n(هذا الحساب يعتمد على مطابقة اسم المنتج المرتبط بهذا الإعلان مع الطلبات — مو تتبع دقيق لكل نقرة عالإعلان)`,
          `\n\n(This is based on matching orders to the product this ad is mapped to — not precise per-click ad attribution)`
        );
      }

      if (ordersWithUnknownCost > 0) {
        responseMsg += t(lang,
          `\n\n⚠️ ${ordersWithUnknownCost} من ${orders.length} طلب ما عندهم سعر تكلفة محدد، فالحساب تقريبي. عطني سعر التكلفة لباقي المنتجات عشان يكون الحساب أدق.`,
          `\n\n⚠️ ${ordersWithUnknownCost} of ${orders.length} orders don't have a cost price set, so this is an approximation. Tell me the cost for those products to make this more accurate.`
        );
      }
      if (usedPreciseItemsCount > 0 && usedPreciseItemsCount < orders.length) {
        responseMsg += t(lang,
          `\n\n(${usedPreciseItemsCount} من الطلبات استخدمت حساب دقيق للمنتجات، والباقي حساب تقريبي)`,
          `\n\n(${usedPreciseItemsCount} of these orders used precise per-product cost splitting; the rest used a simpler estimate)`
        );
      }

      await notifySeller.call(this, responseMsg);
      return;
    }

    // ═══ VIEW REPORT ═══
    if (plan.intent === 'view_report') {
      const dateInfo = resolveAdDateRange(plan);

      // Use explicitly-requested metrics this time, else the seller's saved
      // default preference, else the standard baseline set.
      let metricsToFetch = (plan.requested_metrics && plan.requested_metrics.length > 0) ? plan.requested_metrics : null;
      if (!metricsToFetch) {
        try {
          const prefResp = await this.helpers.httpRequest({
            method: 'GET',
            url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_ad_config?chat_id=eq.' + chatId + '&select=preferred_metrics&limit=1',
            headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
          });
          if (prefResp && prefResp[0] && prefResp[0].preferred_metrics && prefResp[0].preferred_metrics.length > 0) {
            metricsToFetch = prefResp[0].preferred_metrics;
          }
        } catch (e) { logSystemError.call(this, chatId, 'Fetching seller preferred analytics metrics', e && e.message); }
      }
      if (!metricsToFetch) metricsToFetch = ['spend', 'impressions', 'clicks', 'ctr', 'cpc', 'actions'];

      const apiFieldsToFetch = [...metricsToFetch];
      if (apiFieldsToFetch.includes('messages_started') && !apiFieldsToFetch.includes('actions')) apiFieldsToFetch.push('actions');
      if (apiFieldsToFetch.includes('cpa')) {
        if (!apiFieldsToFetch.includes('spend')) apiFieldsToFetch.push('spend');
        if (!apiFieldsToFetch.includes('actions')) apiFieldsToFetch.push('actions');
      }
      const fieldsParam = ['campaign_name', 'adset_name', 'ad_name', ...apiFieldsToFetch.filter(f => f !== 'messages_started' && f !== 'cpa')].join(',');

      // If the seller named or ID'd a specific object, resolve and scope the insights
      // fetch to just that object instead of always pulling the whole account's data
      // at the guessed level (which previously made it impossible to answer questions
      // about one specific ad/campaign/ad set by name or by raw ID).
      let insightsUrl = 'https://graph.facebook.com/v19.0/' + adAccountPath + '/insights?level=' + (plan.level || 'campaign') + '&fields=' + fieldsParam + '&' + dateInfo.urlParam + '&limit=25&access_token=' + token;
      if (plan.name_hint) {
        const { matches: hintMatches } = await resolveMetaObjectsWithIdFallback.call(this, plan.name_hint, plan.level || 'campaign', adAccountPath, token);
        if (hintMatches.length === 0) {
          await notifySeller.call(this, t(lang, '⚠️ ما لقيت شي بهذا الاسم أو الرقم.', "⚠️ Couldn't find anything with that name or ID."));
          return;
        }
        if (hintMatches.length > 1) {
          const names = hintMatches.map(m => m.name).join(', ');
          await notifySeller.call(this, t(lang, `⚠️ لقيت أكثر من واحد: ${names}. حدد اكثر بالضبط.`, `⚠️ Found more than one match: ${names}. Be more specific.`));
          return;
        }
        insightsUrl = 'https://graph.facebook.com/v19.0/' + hintMatches[0].id + '/insights?fields=' + fieldsParam + '&' + dateInfo.urlParam + '&limit=25&access_token=' + token;
      }
      let insightsResp;
      try {
        insightsResp = await this.helpers.httpRequest({
          method: 'GET',
          url: insightsUrl
        });
      } catch (fetchErr) {
        const metaErrorMsg = extractMetaErrorMessage(fetchErr);
        await notifySeller.call(this, t(lang,
          `⚠️ ما كدرت أجيب البيانات — ${metaErrorMsg}`,
          `⚠️ Couldn't fetch that data — ${metaErrorMsg}`
        ));
        return;
      }
      const rows = (insightsResp && insightsResp.data) || [];

      if (rows.length === 0) {
        await notifySeller.call(this, t(lang, '📊 ما لقيت بيانات لهذي الفترة.', '📊 No data found for this period.'));
        return;
      }

      const monetaryAdMetrics = ['spend', 'cpc', 'cpm', 'cost_per_purchase', 'cpa'];
      const purchaseActionTypes = ['purchase', 'offsite_conversion.fb_pixel_purchase', 'omni_purchase', 'onsite_conversion.purchase', 'onsite_web_purchase', 'onsite_app_purchase', 'onsite_web_app_purchase'];
      const getPurchaseCount = (r) => {
        const p = (r.actions || []).find(a => purchaseActionTypes.includes(a.action_type));
        return p ? parseFloat(p.value) : 0;
      };
      const summaryText = rows.map(r => {
        const name = r.ad_name || r.adset_name || r.campaign_name || 'Unknown';
        const metricParts = metricsToFetch.map(m => {
          if (m === 'actions') {
            return `purchases ${getPurchaseCount(r)}`;
          }
          if (m === 'cpa') {
            const purchases = getPurchaseCount(r);
            const spend = parseFloat(r.spend || 0);
            if (purchases === 0) return `cpa no purchases yet this period, so cost-per-purchase can't be calculated (spend so far: ${spend}${globalCurrencyLabel ? ' ' + globalCurrencyLabel : ''})`;
            return `cpa ${(spend / purchases).toFixed(2)} ${globalCurrencyLabel}`;
          }
          if (m === 'messages_started') {
            const msgStarts = (r.actions || []).find(a => a.action_type === 'onsite_conversion.messaging_conversation_started_7d');
            return `messaging conversations started ${msgStarts ? msgStarts.value : 0}`;
          }
          if (r[m] === undefined) return null;
          const unit = monetaryAdMetrics.includes(m) ? ' ' + globalCurrencyLabel : '';
          return `${m} ${r[m]}${unit}`;
        }).filter(Boolean).join(', ');
        return `Campaign/ad named "${name}" (this is just its name, not a date): ${metricParts}`;
      }).join('\n');

      const commentaryResp = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api.anthropic.com/v1/messages',
        headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
        body: JSON.stringify({
          model: 'claude-haiku-4-5-20251001',
          max_tokens: 500,
          system: `You are a helpful, honest ads advisor talking to a small business owner. Given this ad performance data, write a short, natural summary — what's working, what's not, and one concrete idea worth testing.

CRITICAL — DATA HONESTY: Only reference numbers, dates, and periods that are literally present in the data given to you below. NEVER invent specific dates, NEVER invent a "before vs after" comparison unless the data explicitly contains two distinct periods to compare, and NEVER guess at what "probably changed" between dates you weren't given. If the data only covers one period, just describe that one period — don't imply a trend across a longer timeframe you don't actually have data for.

IMPORTANT — campaign/ad names are arbitrary labels the seller chose, NOT dates, even if they happen to contain numbers or slashes that look date-like (e.g. a campaign literally named "25/3/2025 CA" is just its name — it does NOT mean the data is from March 2025). Every row you're given is from the exact same single period stated below. Never compare rows against each other as if they represent different time periods.

CRITICAL — ALWAYS STATE THE ACTUAL NUMBERS: The seller asked for specific metric values. Always state the literal figures for each campaign/ad (e.g. "705 clicks vs 312 clicks"), never just a vague qualitative comparison like "nearly 3x more" without also giving the real numbers. Being short doesn't mean omitting the actual data requested — it means skipping unnecessary padding, not the numbers themselves.

CRITICAL — NEVER FABRICATE A NUMBER: Every number in your reply must be one that literally appears in the data given to you. If a metric genuinely isn't present for a specific campaign/ad, say "no data for this metric" — never guess, round, or copy a number from a different row/campaign to fill the gap.

Plain conversational tone, no jargon, no markdown. Reply in ${lang === 'english' ? 'English' : 'Arabic (Iraqi dialect)'}. Keep it SHORT — 3-5 lines by default. Only go longer if the seller specifically asked for a detailed explanation or breakdown.`,
          messages: [{ role: 'user', content: `Period: ${dateInfo.label}\n\n${summaryText}` }]
        })
      });
      await logAiUsage.call(this, commentaryResp, 'ads_report_commentary');
      const commentary = commentaryResp.content[0].text.trim();
      await notifySeller.call(this, '📊 ' + commentary);
      return;
    }

    // ═══ LIST STRUCTURE (factual count/list, not performance) ═══
    if (plan.intent === 'list_structure') {
      const level = plan.level || 'campaign';
      if (plan.parent_hint && level !== 'campaign') {
        const { parentMatches, parent, children } = await findChildMetaObjects.call(this, plan.parent_hint, level, adAccountPath, token);
        if (parentMatches.length === 0) {
          await notifySeller.call(this, t(lang, '⚠️ ما لقيت شي بهذا الاسم.', "⚠️ Couldn't find anything with that name."));
          return;
        }
        if (parentMatches.length > 1) {
          const names = parentMatches.map(m => m.name).join(', ');
          await notifySeller.call(this, t(lang, `⚠️ لقيت أكثر من واحد بهذا الاسم: ${names}. حدد اكثر بالضبط.`, `⚠️ Found more than one match: ${names}. Be more specific.`));
          return;
        }
        const label = level === 'adset' ? (lang === 'english' ? 'ad set(s)' : 'أدست') : (lang === 'english' ? 'ad(s)' : 'إعلان');
        if (!children || children.length === 0) {
          await notifySeller.call(this, t(lang, `📋 "${parent.name}" ما عنده أي ${label}.`, `📋 "${parent.name}" has no ${label}.`));
          return;
        }
        const listText = children.map(c => `• ${c.name} (${c.status})`).join('\n');
        await notifySeller.call(this, t(lang,
          `📋 "${parent.name}" عنده ${children.length} ${label}:\n${listText}`,
          `📋 "${parent.name}" has ${children.length} ${label}:\n${listText}`
        ));
        return;
      }
      // No specific parent named — list at the top account level for the requested type.
      const all = await findMetaObjectsByName.call(this, null, level, adAccountPath, token);
      if (all.length === 0) {
        await notifySeller.call(this, t(lang, '📋 ما لقيت شي.', "📋 Nothing found."));
        return;
      }
      const listText = all.map(c => `• ${c.name} (${c.status})`).join('\n');
      await notifySeller.call(this, t(lang, `📋 عندك ${all.length}:\n${listText}`, `📋 You have ${all.length}:\n${listText}`));
      return;
    }

    // ═══ EDIT (pause/resume/budget/rename) ═══
    if (plan.intent === 'edit') {
      const { matches } = await resolveMetaObjectsWithIdFallback.call(this, plan.name_hint, plan.level || 'campaign', adAccountPath, token);
      if (matches.length === 0) {
        await notifySeller.call(this, t(lang, '⚠️ ما لقيت شي بهذا الاسم أو الرقم.', "⚠️ Couldn't find anything with that name or ID."));
        return;
      }
      if (matches.length > 1) {
        const names = matches.map(m => m.name).join(', ');
        await notifySeller.call(this, t(lang, `⚠️ لقيت أكثر من واحد: ${names}. حدد اكثر بالضبط.`, `⚠️ Found more than one match: ${names}. Be more specific.`));
        return;
      }
      const target = matches[0];
      const updateBody = {};
      let summaryOfChange = '';
      let editTarget = target;
      if (plan.edit_action === 'set_budget' && (plan.level || 'campaign') === 'campaign') {
        // Campaigns without Campaign Budget Optimization (CBO) don't accept a direct
        // daily_budget write — the budget actually lives on the ad set(s) underneath.
        // Detect this and redirect automatically instead of failing with a raw 400.
        try {
          const cboCheck = await this.helpers.httpRequest({
            method: 'GET',
            url: 'https://graph.facebook.com/v19.0/' + target.id + '?fields=daily_budget,lifetime_budget&access_token=' + token
          });
          const hasCampaignBudget = !!(cboCheck && (cboCheck.daily_budget || cboCheck.lifetime_budget));
          if (!hasCampaignBudget) {
            const adsetsResp = await this.helpers.httpRequest({
              method: 'GET',
              url: 'https://graph.facebook.com/v19.0/' + target.id + '/adsets?fields=id,name,status&access_token=' + token
            });
            const adsets = (adsetsResp && adsetsResp.data) || [];
            if (adsets.length === 0) {
              await notifySeller.call(this, t(lang, '⚠️ ما لقيت أي أدست تحت هذا الكامبين لأغير ميزانيته.', "⚠️ Couldn't find any ad sets under this campaign to set a budget on."));
              return;
            }
            if (adsets.length > 1) {
              const names = adsets.map(a => a.name).join(', ');
              await notifySeller.call(this, t(lang,
                `⚠️ هذا الكامبين ما عنده ميزانية موحدة (CBO مو مفعل) — الميزانية تنحدد على مستوى الأدست. عندك أكثر من أدست: ${names}. جاوبني بأي أدست تريد تغير ميزانيته.`,
                `⚠️ This campaign doesn't use a shared campaign budget (CBO isn't enabled) — budget is set per ad set. You have more than one: ${names}. Tell me which ad set's budget to change.`
              ));
              return;
            }
            editTarget = adsets[0];
          }
        } catch (cboCheckErr) {
          // If the check itself fails, fall through and try the original target —
          // don't let a diagnostic step block the actual edit attempt.
        }
      }
      if (plan.edit_action === 'pause') { updateBody.status = 'PAUSED'; summaryOfChange = `pause "${target.name}"`; }
      else if (plan.edit_action === 'activate') { updateBody.status = 'ACTIVE'; summaryOfChange = `resume "${target.name}"`; }
      else if (plan.edit_action === 'set_budget' && plan.new_budget) { updateBody.daily_budget = Math.round(plan.new_budget * 100); summaryOfChange = editTarget.id !== target.id ? `set budget for "${target.name}" (ad set "${editTarget.name}") to ${plan.new_budget}` : `set budget for "${target.name}" to ${plan.new_budget}`; }
      else if (plan.edit_action === 'rename' && plan.new_name) { updateBody.name = plan.new_name; summaryOfChange = `rename "${target.name}" to "${plan.new_name}"`; }
      else {
        await notifySeller.call(this, t(lang, '⚠️ ما فهمت شنو التغيير المطلوب بالضبط.', "⚠️ Couldn't tell exactly what change you want."));
        return;
      }

      const settings = await getPosSettings.call(this);
      const needsConfirm = settings.confirmation_mode === 'confirm_always';
      if (needsConfirm) {
        await setBotState.call(this, 'pending_ads_edit_confirm', { targetId: editTarget.id, updateBody, summaryOfChange });
        await notifySeller.call(this, t(lang, `⚠️ راح ${summaryOfChange}. متأكد؟ رد "نعم" أو "لا"`, `⚠️ About to ${summaryOfChange}. Sure? Reply "yes" or "no"`));
        return;
      }

      try {
        await this.helpers.httpRequest({
          method: 'POST',
          url: 'https://graph.facebook.com/v19.0/' + editTarget.id + '?access_token=' + token,
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(updateBody)
        });
        await notifySeller.call(this, t(lang, `✅ تم — ${summaryOfChange}`, `✅ Done — ${summaryOfChange}`));
      } catch (editErr) {
        const metaErrorMsg = extractMetaErrorMessage(editErr);
        await notifySeller.call(this, t(lang,
          `⚠️ ما كدرت ${summaryOfChange} — ${metaErrorMsg}`,
          `⚠️ Couldn't ${summaryOfChange} — ${metaErrorMsg}`
        ));
      }
      return;
    }

    // ═══ STRATEGY DISCUSSION ═══
    let recentSummary = 'No recent data available.';
    try {
      const insightsResp = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://graph.facebook.com/v19.0/' + adAccountPath + '/insights?level=campaign&fields=campaign_name,spend,impressions,clicks,ctr,cpc,actions&date_preset=last_7d&limit=10&access_token=' + token
      });
      const rows = (insightsResp && insightsResp.data) || [];
      if (rows.length > 0) {
        recentSummary = rows.map(r => `${r.campaign_name}: spend ${r.spend || 0} ${globalCurrencyLabel}, clicks ${r.clicks || 0}, CTR ${r.ctr || 0}%`).join('\n');
      }
    } catch (e) { logSystemError.call(this, chatId, 'Building ad campaign summary', e && e.message); }

    const discussResp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.anthropic.com/v1/messages',
      headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 500,
        system: `You are a thoughtful, honest ads advisor discussing strategy with a small business owner. Here's their last 7 days of campaign performance for context:\n\n${recentSummary}\n\nRespond naturally and conversationally to their idea/question, referencing the real data where relevant. Be genuinely helpful, not just agreeable — push back gently if their idea seems risky given the data. Plain tone, no jargon, no markdown. Reply in ${lang === 'english' ? 'English' : 'Arabic (Iraqi dialect)'}. Keep it SHORT — 3-5 lines by default. Only go longer if they specifically asked for a detailed explanation.`,
        messages: [{ role: 'user', content: userText }]
      })
    });
    await logAiUsage.call(this, discussResp, 'ads_strategy_discussion');
    await notifySeller.call(this, discussResp.content[0].text.trim());
  } catch (e) {
    const isAnthropicFailure = (e.config?.url || '').includes('api.anthropic.com');
    if (isAnthropicFailure) {
      await notifySeller.call(this, t(lang,
        '⚠️ يبدو أن رصيد Anthropic API خلص أو صار فيه مشكلة بالفوترة. تحقق من حسابك بموقع Anthropic وأعد الشحن، وبعدين جرب مرة ثانية.',
        "⚠️ It looks like the Anthropic API credit balance may be exhausted (or there's a billing issue). Please check your Anthropic account and top up, then try again."
      ));
    } else {
      await notifySeller.call(this, '⚠️ ' + e.message);
    }
  }
}

async function handlePendingAdsEditConfirm(userText, lang) {
  const state = await getBotState.call(this);
  const { targetId, updateBody, summaryOfChange } = state.context || {};
  const isYes = /نعم|yes|ok|اي|ايه/i.test(userText);
  await setBotState.call(this, 'idle', {});
  if (!isYes) {
    await notifySeller.call(this, t(lang, '✅ تم الإلغاء.', '✅ Cancelled.'));
    return;
  }
  try {
    const adConfig = await getAdConfigForManagement.call(this);
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://graph.facebook.com/v19.0/' + targetId + '?access_token=' + adConfig.meta_ads_token,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(updateBody)
    });
    await notifySeller.call(this, t(lang, `✅ تم — ${summaryOfChange}`, `✅ Done — ${summaryOfChange}`));
  } catch (e) {
    const metaErrorMsg = extractMetaErrorMessage(e);
    await notifySeller.call(this, t(lang, `⚠️ ما كدرت ${summaryOfChange} — ${metaErrorMsg}`, `⚠️ Couldn't ${summaryOfChange} — ${metaErrorMsg}`));
  }
}

async function setAdAccountId(userText, lang) {
