        '📍 To find your Meta Ad Account ID:\n\n1. Open Meta Ads Manager (adsmanager.facebook.com)\n2. Look at the top-left corner — you\'ll see your account name with a number starting with "act_"\n3. Copy that number (without "act_") and send it to me: "my ad account id is 123456789"'
      ));
      return;
    }

    const adAccountId = idMatch[1];

    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_ad_config?on_conflict=chat_id',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'resolution=merge-duplicates' },
