}

async function registerAd(userText, lang) {
  try {
    const extractResp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.anthropic.com/v1/messages',
      headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 200,
        system: `The seller wants to link a Meta ad ID to one of their products, so the AI knows what to lead with when a customer clicks that specific ad. Extract the details, however they phrased it.

Reply with ONLY this JSON, nothing else:
{
  "ad_id": "the ad ID/number mentioned, exactly as given, or null if genuinely not mentioned",
  "product_name": "the product name mentioned, or null",
  "offer_details": "any offer/discount/promotion details mentioned (e.g. '20% off', 'buy 2 get 1 free'), or null if none mentioned"
}`,
        messages: [{ role: 'user', content: userText }]
      })
    });
    await logAiUsage.call(this, extractResp, 'register_ad_extraction');
    let extracted = {};
    try { extracted = JSON.parse(extractResp.content[0].text.trim().replace(/```json|```/g, '')); } catch (e) { logSystemError.call(this, chatId, 'Parsing ad registration details from AI response', e && e.message); }

    if (!extracted.ad_id || !extracted.product_name) {
      await notifySeller.call(this, t(lang,
        '⚠️ محتاج رقم/كود الاعلان واسم المنتج. مثال: "الاعلان 120211234567 هذا لمنتج X، والعرض خصم 20%"',
        '⚠️ Need both the ad ID and the product name. Example: "ad 120211234567 is for product X, offer is 20% off"'
      ));
      return;
    }

    // The seller may refer to an ad by its real Meta ID, or by the short display
    // name Ahmad showed them earlier (e.g. "2", "AD 2") — resolve whatever they said
    // to the actual ad object first, so we never save a mismatched/fake ad_id.
    const adConfigForResolve = await getAdConfigForManagement.call(this);
    let resolvedAdId = extracted.ad_id;
    if (adConfigForResolve && adConfigForResolve.ad_account_id && adConfigForResolve.meta_ads_token) {
      const resolveAccountPath = adConfigForResolve.ad_account_id.startsWith('act_') ? adConfigForResolve.ad_account_id : 'act_' + adConfigForResolve.ad_account_id;
      const { matches: adMatches } = await resolveMetaObjectsWithIdFallback.call(this, extracted.ad_id, 'ad', resolveAccountPath, adConfigForResolve.meta_ads_token);
      if (adMatches.length === 1) {
        resolvedAdId = adMatches[0].id;
      } else if (adMatches.length > 1) {
        const names = adMatches.map(m => m.name).join(', ');
        await notifySeller.call(this, t(lang, `⚠️ لقيت أكثر من إعلان بهذا الاسم: ${names}. حدد اكثر بالضبط.`, `⚠️ Found more than one ad matching that: ${names}. Be more specific.`));
        return;
      } else {
        await notifySeller.call(this, t(lang,
          `⚠️ ما لقيت إعلان حقيقي بالاسم أو الرقم "${extracted.ad_id}". تأكد من الاسم أو الرقم وحاول مرة ثانية.`,
          `⚠️ Couldn't find a real ad matching "${extracted.ad_id}". Double-check the name or ID and try again.`
        ));
        return;
      }
    }

    // Confirm the product actually exists for this seller before linking it
    let matchedProductName = extracted.product_name;
    try {
      const productMatch = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_products?chat_id=eq.' + chatId + '&product_name=ilike.*' + encodeURIComponent(extracted.product_name) + '*&select=product_name&limit=1',
        headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
      });
      if (productMatch && productMatch.length > 0) matchedProductName = productMatch[0].product_name;
    } catch (e) { logSystemError.call(this, chatId, 'Fetching matched product name for ad', e && e.message); }

    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/ad_product_mapping?on_conflict=chat_id,ad_id',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'resolution=merge-duplicates' },
      body: JSON.stringify({
        chat_id: chatId,
        ad_id: resolvedAdId,
        product_name: matchedProductName,
        offer_details: extracted.offer_details || null
      })
    });

    await notifySeller.call(this, t(lang,
      `✅ تم ربط الاعلان ${resolvedAdId} بمنتج "${matchedProductName}"${extracted.offer_details ? ' (العرض: ' + extracted.offer_details + ')' : ''}`,
      `✅ Linked ad ${resolvedAdId} to "${matchedProductName}"${extracted.offer_details ? ' (offer: ' + extracted.offer_details + ')' : ''}`
    ));
  } catch (e) {
    await notifySeller.call(this, '⚠️ ' + e.message);
  }
}

async function generateInvoice(userText, lang) {
  try {
    // Step 1: figure out if this is a brand-new invoice (with items/pricing/etc)
    // or a request to generate an invoice for an already-existing order.
    const extractResp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.anthropic.com/v1/messages',
      headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 500,
        system: `The seller wants an invoice. Figure out which of these two cases it is, and extract accordingly.

CASE "existing_order": they're referencing an order that already happened (e.g. "generate invoice for the last order", "send invoice to 07701234567").

CASE "new": they're describing a full sale right now, with products/quantities/pricing/discount/shipping/payment details (e.g. "invoice for Karim, 10 units of [product] wholesale, 5% discount, 5000 shipping, he paid half").

Reply with ONLY this JSON, nothing else:
{
  "mode": "existing_order" | "new",

  "phone": "phone number if mentioned, else null",
  "customer_hint": "customer name if mentioned, else null",
  "product_hint": "a product name hint, for existing_order mode only, else null",

  "customer_name": "for new mode: customer's name if given, else null",
  "customer_phone": "for new mode: customer's phone if given, else null",
  "items": [ { "product_name": "...", "quantity": number } ],
  "pricing_mode": "wholesale" | "retail" | "a named pricing tier if mentioned" | null,
  "discount_percent": number or null,
  "discount_amount": number or null,
  "shipping": number or null,
  "payment_status": "paid" | "partial" | "debt" | null,
  "amount_paid": number or null,
  "amount_paid_fraction": number or null
}

For amount_paid: use this ONLY if an exact figure is given (e.g. "he paid 20000").
For amount_paid_fraction: use this if payment is described proportionally instead of as an exact number (e.g. "he paid half" = 0.5, "paid a third" = 0.333, "paid most of it, about 80%" = 0.8). Leave both null if payment_status is "paid" or "debt".

If a field isn't mentioned, use null (or an empty array for items). Only use "new" mode if actual products/quantities are described — otherwise use "existing_order".`,
        messages: [{ role: 'user', content: userText }]
      })
    });
    await logAiUsage.call(this, extractResp, 'generate_invoice_extraction');
    let extracted = {};
    try { extracted = JSON.parse(extractResp.content[0].text.trim().replace(/```json|```/g, '')); } catch (e) { logSystemError.call(this, chatId, 'Parsing invoice details from AI response', e && e.message); }

    if (extracted.mode === 'new' && extracted.items && extracted.items.length > 0) {
      await createFullInvoice.call(this, extracted, lang);
      return;
    }

    // ── Existing-order mode (original behavior) ──
    let filterQuery = 'seller_id=eq.' + chatId;
    if (extracted.phone) filterQuery += '&phone=ilike.*' + encodeURIComponent(extracted.phone) + '*';
    if (extracted.product_hint) filterQuery += '&product_name=ilike.*' + encodeURIComponent(extracted.product_hint) + '*';

    const orders = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/orders?' + filterQuery + '&order=created_at.desc&limit=5&select=*',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
    });

    if (!orders || orders.length === 0) {
      await notifySeller.call(this, t(lang, '⚠️ ما لقيت طلب يطابق وصفك. جرب تعطيني رقم الهاتف أو اسم الزبون.', "⚠️ I couldn't find a matching order. Try giving me the customer's phone number or name."));
      return;
    }
    const order = orders[0];

    const settings = await getPosSettings.call(this);
    const invoiceNumber = (settings.invoice_prefix || 'INV') + '-' + String(settings.next_invoice_number || 1).padStart(4, '0');
    await updatePosSettings.call(this, { next_invoice_number: (settings.next_invoice_number || 1) + 1 });

    const manageableTables = await getManageableSchema.call(this);
    if (manageableTables.invoices) {
      try {
        const invCfg = manageableTables.invoices;
        const invValues = {};
        if (invCfg.columns.includes('invoice_number')) invValues.invoice_number = invoiceNumber;
        if (invCfg.columns.includes('customer_phone')) invValues.customer_phone = order.phone;
        if (invCfg.columns.includes('order_id')) invValues.order_id = order.id;
        if (invCfg.columns.includes('total')) invValues.total = order.order_total || order.product_price;
        if (invCfg.columns.includes('subtotal')) invValues.subtotal = order.product_price;
        if (invCfg.columns.includes('status')) invValues.status = 'sent';
        if (invCfg.columns.includes('items')) invValues.items = JSON.stringify([{ product: order.product_name, price: order.product_price }]);
        invValues[invCfg.ownerField] = chatId;
        await this.helpers.httpRequest({
          method: 'POST',
          url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/invoices',
          headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
          body: JSON.stringify(invValues)
        });
      } catch (e) { logSystemError.call(this, chatId, 'Saving invoice to database', e && e.message); }
    }

    const invoiceText = t(lang,
      `🧾 <b>فاتورة ${invoiceNumber}</b>\n\nالزبون: ${order.phone}\nالمنتج: ${order.product_name || ''}\nالمجموع: ${order.order_total || ''}\nالعنوان: ${order.delivery_address || 'غير محدد'}\n\nممكن ترسل هذي الفاتورة للزبون على واتساب.`,
      `🧾 <b>Invoice ${invoiceNumber}</b>\n\nCustomer: ${order.phone}\nProduct: ${order.product_name || ''}\nTotal: ${order.order_total || ''}\nAddress: ${order.delivery_address || 'not set'}\n\nYou can forward this invoice to the customer on WhatsApp.`
    );
    await notifySeller.call(this, invoiceText);
  } catch (e) {
    await notifySeller.call(this, '⚠️ ' + e.message);
  }
}

// ═══════════════════════════════════════════════
// FULL INVOICE CREATION — everything in one message: customer, multiple
// items, wholesale/retail pricing, discount, shipping, payment status.
// ═══════════════════════════════════════════════
async function createFullInvoice(extracted, lang) {
  try {
    // Step 1: resolve each item's real price from seller_products
    const lineItems = [];
    let subtotal = 0;
    for (const item of extracted.items) {
      const products = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_products?chat_id=eq.' + chatId + '&product_name=ilike.*' + encodeURIComponent(item.product_name) + '*&select=*&limit=1',
        headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
      });
      if (!products || products.length === 0) {
        await notifySeller.call(this, t(lang, `⚠️ ما لقيت منتج اسمه "${item.product_name}"`, `⚠️ Couldn't find a product called "${item.product_name}"`));
        return;
      }
      const product = products[0];
      let unitPrice = extracted.pricing_mode === 'wholesale' ? product.wholesale_price : product.retail_price;
      if (unitPrice == null) unitPrice = product.retail_price ?? product.wholesale_price ?? 0;

      // Apply a named pricing tier's adjustment on top, if one was mentioned
      if (extracted.pricing_mode && extracted.pricing_mode !== 'wholesale' && extracted.pricing_mode !== 'retail') {
        try {
          const tiers = await this.helpers.httpRequest({
            method: 'GET',
            url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/pricing_tiers?chat_id=eq.' + chatId + '&name=ilike.*' + encodeURIComponent(extracted.pricing_mode) + '*&select=*&limit=1',
            headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
          });
          if (tiers && tiers.length > 0) {
            unitPrice = unitPrice * (1 + (Number(tiers[0].adjustment_percent) || 0) / 100);
          }
        } catch (e) { logSystemError.call(this, chatId, 'Applying wholesale pricing tier', e && e.message); }
      }

      const qty = Number(item.quantity) || 1;
      const lineTotal = unitPrice * qty;
      subtotal += lineTotal;
      lineItems.push({ product_name: product.product_name, quantity: qty, unit_price: unitPrice, line_total: lineTotal });
    }

    // Step 2: discount, shipping, grand total
    let afterDiscount = subtotal;
    if (extracted.discount_percent) afterDiscount = subtotal * (1 - Number(extracted.discount_percent) / 100);
    else if (extracted.discount_amount) afterDiscount = subtotal - Number(extracted.discount_amount);
    const shipping = Number(extracted.shipping) || 0;
    const grandTotal = afterDiscount + shipping;

    // Step 3: payment status
    let amountPaid = 0;
    if (extracted.payment_status === 'paid') amountPaid = grandTotal;
    else if (extracted.payment_status === 'partial') {
      if (extracted.amount_paid) amountPaid = Number(extracted.amount_paid);
      else if (extracted.amount_paid_fraction) amountPaid = grandTotal * Number(extracted.amount_paid_fraction);
      else amountPaid = 0;
    }
    else if (extracted.payment_status === 'debt') amountPaid = 0;
    const balanceDue = grandTotal - amountPaid;

    // Step 4: upsert the customer
    if (extracted.customer_phone) {
      try {
        await this.helpers.httpRequest({
          method: 'POST',
          url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/customers?on_conflict=phone,seller_id',
          headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'resolution=merge-duplicates' },
          body: JSON.stringify({
            phone: extracted.customer_phone,
            name: extracted.customer_name || null,
            is_wholesale: extracted.pricing_mode === 'wholesale',
            seller_id: chatId
          })
        });
      } catch (e) { logSystemError.call(this, chatId, 'Saving invoice customer info', e && e.message); }
    }

    // Step 5: create an order record summarizing this sale
    const itemsSummary = lineItems.map(li => `${li.quantity}x ${li.product_name}`).join(', ');
    let orderStatus = amountPaid >= grandTotal ? 'DELIVERED' : 'PENDING';
    let createdOrderId = null;
    try {
      const orderCreateResp = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/orders',
        headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=representation' },
        body: JSON.stringify({
          seller_id: chatId,
          phone: extracted.customer_phone || '',
          product_name: itemsSummary,
          order_total: grandTotal,
          order_status: orderStatus
        })
      });
      createdOrderId = (orderCreateResp && orderCreateResp[0] && orderCreateResp[0].id) || null;

      // Save precise per-product line items — this is what lets the ROAS
      // calculation split cost correctly across multiple different products
      // in the same order, instead of only matching the first one.
      if (createdOrderId) {
        for (const li of lineItems) {
          try {
            await this.helpers.httpRequest({
              method: 'POST',
              url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/order_items',
              headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
              body: JSON.stringify({
                order_id: createdOrderId,
                seller_id: chatId,
                product_name: li.product_name,
                quantity: li.quantity,
                unit_price: li.unit_price,
                line_total: li.line_total
              })
            });
          } catch (e) { logSystemError.call(this, chatId, 'Saving invoice line items', e && e.message); }
        }
      }
    } catch (e) { logSystemError.call(this, chatId, 'Saving invoice line item', e && e.message); }

    // Step 6: invoice number + optional invoices table record
    const settings = await getPosSettings.call(this);
    const invoiceNumber = (settings.invoice_prefix || 'INV') + '-' + String(settings.next_invoice_number || 1).padStart(4, '0');
    await updatePosSettings.call(this, { next_invoice_number: (settings.next_invoice_number || 1) + 1 });

    const manageableTables = await getManageableSchema.call(this);
    if (manageableTables.invoices) {
      try {
        const invCfg = manageableTables.invoices;
        const invValues = {};
        if (invCfg.columns.includes('invoice_number')) invValues.invoice_number = invoiceNumber;
        if (invCfg.columns.includes('customer_phone')) invValues.customer_phone = extracted.customer_phone || '';
        if (invCfg.columns.includes('items')) invValues.items = JSON.stringify(lineItems);
        if (invCfg.columns.includes('subtotal')) invValues.subtotal = subtotal;
        if (invCfg.columns.includes('shipping')) invValues.shipping = shipping;
        if (invCfg.columns.includes('total')) invValues.total = grandTotal;
        if (invCfg.columns.includes('status')) invValues.status = amountPaid >= grandTotal ? 'paid' : (amountPaid > 0 ? 'partial' : 'sent');
        invValues[invCfg.ownerField] = chatId;
        await this.helpers.httpRequest({
          method: 'POST',
          url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/invoices',
          headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
          body: JSON.stringify(invValues)
        });
      } catch (e) { logSystemError.call(this, chatId, 'Saving invoice to database', e && e.message); }
    }

    // Step 7: format and send the full itemized invoice
    const itemLines = lineItems.map(li => `${li.quantity} x ${li.product_name} @ ${li.unit_price.toLocaleString()} = ${li.line_total.toLocaleString()}`).join('\n');
    const invoiceText = t(lang,
      `🧾 <b>فاتورة ${invoiceNumber}</b>\n\nالزبون: ${extracted.customer_name || ''} ${extracted.customer_phone || ''}\n\n${itemLines}\n\nالمجموع الفرعي: ${subtotal.toLocaleString()}\n${extracted.discount_percent ? 'الخصم: ' + extracted.discount_percent + '%\n' : (extracted.discount_amount ? 'الخصم: ' + extracted.discount_amount.toLocaleString() + '\n' : '')}الشحن: ${shipping.toLocaleString()}\n<b>المجموع الكلي: ${grandTotal.toLocaleString()}</b>\nالمدفوع: ${amountPaid.toLocaleString()}\n${balanceDue > 0 ? '<b>المتبقي: ' + balanceDue.toLocaleString() + '</b>' : '✅ مدفوع بالكامل'}\n\nممكن ترسل هذي الفاتورة للزبون على واتساب.`,
      `🧾 <b>Invoice ${invoiceNumber}</b>\n\nCustomer: ${extracted.customer_name || ''} ${extracted.customer_phone || ''}\n\n${itemLines}\n\nSubtotal: ${subtotal.toLocaleString()}\n${extracted.discount_percent ? 'Discount: ' + extracted.discount_percent + '%\n' : (extracted.discount_amount ? 'Discount: ' + extracted.discount_amount.toLocaleString() + '\n' : '')}Shipping: ${shipping.toLocaleString()}\n<b>Total: ${grandTotal.toLocaleString()}</b>\nPaid: ${amountPaid.toLocaleString()}\n${balanceDue > 0 ? '<b>Balance due: ' + balanceDue.toLocaleString() + '</b>' : '✅ Fully paid'}\n\nYou can forward this invoice to the customer on WhatsApp.`
    );
    await notifySeller.call(this, invoiceText);
  } catch (e) {
    await notifySeller.call(this, '⚠️ ' + e.message);
  }
}

// ═══════════════════════════════════════════════
// GENERAL BUSINESS MANAGER — conversational CRUD across the whole POS
// Forward-compatible: add new tables here as Claude Code builds new POS features.
// ═══════════════════════════════════════════════
// ═══════════════════════════════════════════════
// DYNAMIC SCHEMA DISCOVERY — reads the live database structure every time,
// so new tables/columns Claude Code adds are picked up automatically with
// zero manual code changes here.
// ═══════════════════════════════════════════════

// Tables that must NEVER be exposed to general seller chat-CRUD, even though
// they may contain chat_id/seller_id — either internal/system tables, or
// tables with existing dedicated flows, or shared/collective data that isn't
// owned by any single seller.
const MANAGEABLE_TABLES_DENYLIST = [
  'sellers', 'pos_settings', 'bot_state', 'seller_preferences',
  'telegram_conversations', 'pending_telegram_messages', 'pending_optin',
  'shared_leads', 'product_playbooks', 'intelligence_logs', 'seller_knowledge',
  'coaching_log', 'seller_onboarding', 'conversations', 'broadcast_log',
  'pending_questions', 'pending_orders', 'client_status', 'seller_ad_config'
];
// Note: seller_ad_config holds sensitive Meta tokens — deliberately kept out
// of generic free-form editing to avoid accidental token corruption. A
// dedicated, narrow command (setAdAccountId) handles the one safe-to-edit
// field a seller should ever set themselves.
// Note: seller_products is intentionally NOT denylisted — the stock-increment
// business rules (returns/purchases/damage/recount) need to reach it directly.
// Adding a brand-new product or deleting one still goes through the richer
// dedicated flows (ONBOARDING / DELETE_PRODUCT intents), which are checked
// before the general manager, so this doesn't bypass that photo/PDF-aware logic.
// Note: seller_products is denylisted here on purpose — it already has its
// own dedicated, richer flows (onboarding, deleteProduct, handleStockUpdate)
// that do more than generic CRUD (photo/PDF ingestion, stock side-effects,
// etc). Add other tables here as new dedicated flows get built for them.

// Internal columns never offered to the AI as editable/insertable fields.
const INTERNAL_COLUMNS = ['id', 'created_at', 'updated_at', 'chat_id', 'seller_id'];

let _schemaCache = null;
async function getManageableSchema() {
  if (_schemaCache) return _schemaCache;
  try {
    const spec = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/',
      headers: { 'apikey': serviceRoleKey, 'Authorization': 'Bearer ' + serviceRoleKey, 'Accept': 'application/openapi+json' }
    });
    const definitions = (spec && (spec.definitions || spec.components?.schemas)) || {};
    const tables = {};
    for (const [tableName, def] of Object.entries(definitions)) {
      if (MANAGEABLE_TABLES_DENYLIST.includes(tableName)) continue;
      const props = def.properties || {};
      const allColumns = Object.keys(props);
      let ownerField = null;
      if (allColumns.includes('chat_id')) ownerField = 'chat_id';
      else if (allColumns.includes('seller_id')) ownerField = 'seller_id';
      else continue; // not seller-scoped — unsafe to expose to general CRUD

      const idField = allColumns.includes('id') ? 'id' : (allColumns.includes('phone') ? 'phone' : allColumns[0]);
      const columns = allColumns.filter(c => !INTERNAL_COLUMNS.includes(c));
      const hasUpdatedAt = allColumns.includes('updated_at');

      tables[tableName] = {
        idField,
        ownerField,
        columns,
        hasUpdatedAt,
        displayName: tableName.replace(/_/g, ' ')
      };
    }
    _schemaCache = tables;
    return tables;
  } catch (e) {
    return {};
  }
}

async function askConfirmationModeChoice(originalText, lang) {
  await setBotState.call(this, 'awaiting_confirmation_mode_choice', { pending_text: originalText });
  await notifySeller.call(this, t(lang,
    'قبل لا نبدأ — شلون تريدني أسوي التغييرات؟\n1. أسوي التغيير على طول بدون ما أسأل\n2. أسألك بس لما أحذف شي\n3. أسألك تأكيد بكل تغيير\n\nرد بـ 1 أو 2 أو 3',
    "Before we start — how should I handle changes?\n1. Just make changes right away, no asking\n2. Ask me before deleting anything\n3. Always ask for confirmation\n\nReply with 1, 2, or 3"
  ));
}

async function handleConfirmationModeChoice(userText, lang, fullLanguage, fullDialect) {
  let mode = null;
  const choice = userText.trim();

  // Fast path: plain Western digit 1/2/3
  if (/^1\b/.test(choice)) mode = 'immediate';
  else if (/^2\b/.test(choice)) mode = 'confirm_delete';
  else if (/^3\b/.test(choice)) mode = 'confirm_always';

  // Fallback: let AI interpret anything else (Arabic-Indic numerals, words like
  // "the first one", "ثنين", "always confirm", voice-transcribed phrasing, etc.)
  if (!mode) {
    try {
      const resp = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api.anthropic.com/v1/messages',
        headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
        body: JSON.stringify({
          model: 'claude-haiku-4-5-20251001',
          max_tokens: 20,
          system: `The seller was asked to choose one of three options:
1 = make changes immediately, no asking
2 = ask before deleting anything
3 = always ask for confirmation

Their reply could be in any language, use words instead of digits, or use non-Western numerals. Reply with ONLY one of these exact words: IMMEDIATE, CONFIRM_DELETE, CONFIRM_ALWAYS, or UNCLEAR if it genuinely doesn't match any of the three.`,
          messages: [{ role: 'user', content: userText }]
        })
      });
      await logAiUsage.call(this, resp, 'confirmation_mode_choice_interpret');
      const result = (resp.content[0].text || '').trim().toUpperCase();
      if (result.includes('IMMEDIATE')) mode = 'immediate';
      else if (result.includes('CONFIRM_DELETE')) mode = 'confirm_delete';
      else if (result.includes('CONFIRM_ALWAYS')) mode = 'confirm_always';
    } catch (e) { logSystemError.call(this, chatId, 'Parsing delete-confirmation mode from AI response', e && e.message); }
  }

  if (!mode) {
    await notifySeller.call(this, t(lang, '⚠️ رد بس بـ 1 أو 2 أو 3', '⚠️ Please reply with just 1, 2, or 3'));
    return;
  }
  await updatePosSettings.call(this, { confirmation_mode: mode });
  const state = await getBotState.call(this);
  const pendingText = state.context && state.context.pending_text;
  await setBotState.call(this, 'idle', {});
  await notifySeller.call(this, t(lang, '✅ تمام، سجلت اختيارك.', '✅ Got it, saved your preference.'));
  if (pendingText) {
    await handleBusinessManagement.call(this, pendingText, lang, fullLanguage, fullDialect);
  }
}

async function fetchTelegramFileText(fileId) {
  const fileInfo = await this.helpers.httpRequest({ method: 'GET', url: 'https://api.telegram.org/bot' + botToken + '/getFile?file_id=' + fileId });
  const fileUrl = 'https://api.telegram.org/file/bot' + botToken + '/' + fileInfo.result.file_path;
  const fileBuffer = await this.helpers.httpRequest({ method: 'GET', url: fileUrl, encoding: 'arraybuffer' });
  const buf = Buffer.isBuffer(fileBuffer) ? fileBuffer : Buffer.from(fileBuffer);
  return buf.toString('utf-8');
}

function parseCsv(text) {
  const lines = text.split(/\r?\n/).filter(l => l.trim().length > 0);
  if (lines.length < 2) return { headers: [], rows: [] };
  const splitLine = (line) => {
    const cells = [];
    let cur = '';
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      const ch = line[i];
      if (ch === '"') { inQuotes = !inQuotes; continue; }
      if (ch === ',' && !inQuotes) { cells.push(cur); cur = ''; continue; }
      cur += ch;
    }
    cells.push(cur);
    return cells.map(c => c.trim());
  };
  const headers = splitLine(lines[0]);
  const rows = lines.slice(1).map(line => {
    const cells = splitLine(line);
    const row = {};
    headers.forEach((h, i) => { row[h] = cells[i]; });
    return row;
  });
  return { headers, rows };
}

async function handleCsvImport(lang, fullLanguage, fullDialect) {
  try {
    const csvText = await fetchTelegramFileText.call(this, message.document.file_id);
    const { headers, rows } = parseCsv(csvText);
    if (headers.length === 0 || rows.length === 0) {
      await notifySeller.call(this, t(lang, '⚠️ ما قدرت أفهم هذا الملف كـ CSV.', "⚠️ Couldn't read this file as a valid CSV."));
      return;
    }

    const manageableTables = await getManageableSchema.call(this);
    const tableOptionsText = Object.entries(manageableTables).map(([table, cfg]) =>
      `TABLE "${table}": columns = ${cfg.columns.join(', ')}`
    ).join('\n');

    let bestTable = null;
    try {
      const matchResp = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api.anthropic.com/v1/messages',
        headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
        body: JSON.stringify({
          model: 'claude-haiku-4-5-20251001',
          max_tokens: 50,
          system: `Given a CSV file's column headers, decide which table it most likely belongs to. Use your judgment on near-matches — e.g. a header called "name" or "wholesale" likely maps to a table's "product_name" or "wholesale_price" column, not a completely unrelated table. Reply with ONLY the exact table name from the list, or NONE if genuinely no table fits.\n\n${tableOptionsText}`,
          messages: [{ role: 'user', content: 'CSV headers: ' + headers.join(', ') }]
        })
      });
      await logAiUsage.call(this, matchResp, 'csv_import_table_match');
      let guess = (matchResp.content[0].text || '').trim();
      // Clean up common formatting noise (quotes, trailing punctuation, extra whitespace)
      guess = guess.replace(/["'.\n]/g, '').trim();

      if (guess && guess.toUpperCase() !== 'NONE') {
        // Exact match first
        if (manageableTables[guess]) {
          bestTable = guess;
        } else {
          // Fallback: find a table name the response actually contains, or vice versa
          const tableNames = Object.keys(manageableTables);
          bestTable = tableNames.find(t => guess.toLowerCase().includes(t.toLowerCase()) || t.toLowerCase().includes(guess.toLowerCase())) || null;
        }
      }
    } catch (e) { logSystemError.call(this, chatId, 'Matching table name from AI suggestion', e && e.message); }

    if (!bestTable) {
      const tableList = Object.keys(manageableTables).join(', ');
      await notifySeller.call(this, t(lang, `⚠️ ما قدرت أعرف هذا الملف يخص أي جدول. الجداول المتوفرة: ${tableList}`, `⚠️ Couldn't tell which table this file matches. Available: ${tableList}`));
      return;
    }

    const cfg = manageableTables[bestTable];

    // Map CSV headers to actual column names using AI (handles "name" → "product_name" etc.)
    let headerMap = {};
    try {
      const mapResp = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api.anthropic.com/v1/messages',
        headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
        body: JSON.stringify({
          model: 'claude-haiku-4-5-20251001',
          max_tokens: 300,
          system: `Map each of these CSV headers to the best-matching column name from this list: ${cfg.columns.join(', ')}. Reply with ONLY a JSON object like {"csv_header": "matching_column"}. If a header genuinely doesn't match any column, omit it.`,
          messages: [{ role: 'user', content: 'CSV headers: ' + headers.join(', ') }]
        })
      });
      await logAiUsage.call(this, mapResp, 'csv_import_header_mapping');
      headerMap = JSON.parse((mapResp.content[0].text || '{}').trim().replace(/```json|```/g, ''));
    } catch (e) { headerMap = {}; }

    const cleanRows = rows.map(r => {
      const row = {};
      for (const h of headers) {
        const mappedColumn = headerMap[h];
        if (mappedColumn && cfg.columns.includes(mappedColumn)) row[mappedColumn] = r[h];
      }
      row[cfg.ownerField] = chatId;
      return row;
    });

    await setBotState.call(this, 'pending_csv_import', { table: bestTable, rows: cleanRows });
    await notifySeller.call(this, t(lang,
      `📄 لقيت ${cleanRows.length} صف يمكن أضيفهم لجدول "${cfg.displayName}".\n\nمتأكد تريد تستورد؟ رد "نعم" أو "لا"`,
      `📄 Found ${cleanRows.length} row(s) that look like they belong in "${cfg.displayName}".\n\nImport them? Reply "yes" or "no"`
    ));
  } catch (e) {
    await notifySeller.call(this, '⚠️ ' + e.message);
  }
}

async function handlePendingCsvImport(userText, lang) {
  const state = await getBotState.call(this);
  const { table, rows } = state.context || {};
  const isYes = /نعم|yes|ok|اي|ايه/i.test(userText);
  await setBotState.call(this, 'idle', {});
  if (!isYes) {
    await notifySeller.call(this, t(lang, '✅ تم الإلغاء، ما استوردنا شي.', '✅ Cancelled, nothing imported.'));
