}

async function handleBusinessManagement(userText, lang, fullLanguage, fullDialect) {
  const settings = await getPosSettings.call(this);
  if (!settings.confirmation_mode) {
    await askConfirmationModeChoice.call(this, userText, lang);
    return;
  }

  // General business process rules check — this intent path (manage_business)
  // can also receive process/rule-type instructions, not just structured data
  // edits. Route those through the same reliable general system used in the
  // update_knowledge path, rather than letting the old per-field matching
  // logic below handle it inconsistently depending on which intent fired.
  let processRuleMgmt = null;
  try {
    let existingTopicsTextMgmt = '(none yet)';
    try {
      const existingTopicsRespMgmt = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/business_process_rules?chat_id=eq.' + chatId + '&select=topic',
        headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
      });
      if (existingTopicsRespMgmt && existingTopicsRespMgmt.length > 0) {
        existingTopicsTextMgmt = existingTopicsRespMgmt.map(r => r.topic).join(', ');
      }
    } catch (eTopicsMgmt) { logSystemError.call(this, chatId, 'Fetching existing business rule topics', eTopicsMgmt && eTopicsMgmt.message); }

    const ruleCheckRespMgmt = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.anthropic.com/v1/messages',
      headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 200,
        system: `Is this seller message describing an OPERATIONAL RULE or PROCESS for how their business/sales conversations should work — e.g. when/how to collect delivery info, how to handle low-quantity orders, when to ask for payment, what qualification steps to follow, how to talk about pricing, or any other "how we do things" instruction? This is different from a plain FACT (like "our refund policy is X") — it's specifically about a PROCESS, SEQUENCE, or POLICY the AI should follow.

EXISTING TOPICS this seller already has rules for: ${existingTopicsTextMgmt}
If this message is UPDATING, CHANGING, or REPLACING a rule that's the same subject as one of these existing topics, you MUST reuse that EXACT existing topic string — do not invent a new, differently-worded label for the same subject. Only create a genuinely new topic label if this is a distinct subject not covered by any existing topic.

