  }

  const manageableTables = await getManageableSchema.call(this);
  const schemaDescription = Object.entries(manageableTables).map(([table, cfg]) =>
    `TABLE "${table}" (a ${cfg.displayName}): columns = ${cfg.columns.join(', ')}`
  ).join('\n');

  // Give the extraction a helpful anchor for vague follow-ups like "add that
