  // special_offers instead of delivery_info just because the message happened
  // to also mention something offer-like).
  let recentContextHint = '';
  try {
    const recentProduct = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_products?chat_id=eq.' + chatId + '&order=updated_at.desc&limit=1&select=product_name,key_features,target_customers,common_questions,payment_methods,delivery_info,competitors_difference,special_offers,escalation_rules,delivery_timing_preference,order_flow_type',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
    });
    if (recentProduct && recentProduct.length > 0) {
      const rp = recentProduct[0];
      recentContextHint = `\n\nCONTEXT: the seller's most recently added/edited product is "${rp.product_name}". If their message is vague and doesn't clearly name a different product (e.g. "add that offer", "we ship locally", "it's $20"), assume they mean this product.

CURRENT FIELD VALUES for this product (use these to correctly identify WHICH field a vague reference is actually about — e.g. if the seller says "remove that shipping note," check which field below actually contains shipping-related text, rather than guessing from the word "shipping" or "offer" alone):
delivery_info: ${rp.delivery_info || '(empty)'}
special_offers: ${rp.special_offers || '(empty)'}
key_features: ${rp.key_features || '(empty)'}
target_customers: ${rp.target_customers || '(empty)'}
common_questions: ${rp.common_questions || '(empty)'}
payment_methods: ${rp.payment_methods || '(empty)'}
competitors_difference: ${rp.competitors_difference || '(empty)'}
escalation_rules: ${rp.escalation_rules || '(empty)'}
