  } catch (e) { logSystemError.call(this, chatId, 'Building business rule profile summary', e && e.message); }

  let steps = null;
  let overallSummary = '';
  try {
    const resp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.anthropic.com/v1/messages',
      headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 800,
        system: `You translate a seller's natural-language business request into one or more structured database steps. Real business actions are often compound, and the seller will often NOT spell out every implied step — you must infer them yourself from normal business logic, the same way an experienced shop assistant would.

IMPLIED BUSINESS RULES — always apply these automatically, even if not explicitly stated:
- If the seller mentions a RETURN or something being RETURNED (e.g. "50 sets are returned", "customer returned 3 units"): this means (1) find and update the matching order's status to reflect the return, AND (2) increment the product's stock_quantity back up by that amount — automatically, without being told to "add it to stock."
- If the seller mentions a PURCHASE or buying stock from a supplier (e.g. "bought 100 units from Ali"): this means (1) record the purchase if a purchases-type table exists, AND (2) increment the product's stock_quantity by that amount.
- If the seller mentions DAMAGE, LOSS, THEFT, or something being "written off" (e.g. "20 units damaged"): decrement stock_quantity by that amount — this is a one-way adjustment, no restocking.
- If the seller mentions a RECOUNT or correcting a stock number (e.g. "actually we have 80, not 60"): treat this as a direct stock_quantity update to the new correct number, not an increment.
- If the seller describes selling something OUTSIDE of the normal WhatsApp order flow (e.g. "sold 5 units to a walk-in customer"): decrement stock_quantity by that amount.
- Always infer ALL the steps a real business action implies — never make the seller spell out something an experienced shop assistant would already know needs to happen.

Break the request into as many steps as genuinely needed to fully and correctly reflect what actually happens in the business, not just what was literally typed.
${recentContextHint}

TABLE SELECTION — READ CAREFULLY: seller_sales_config holds GLOBAL business-wide settings that apply to every product (e.g. a default MOQ, one flat shipping rate for the whole business, overall sales tone). It is NOT a place to store notes, offers, discounts, policies, warranties, support terms, or any other detail that belongs to ONE SPECIFIC product — those always belong on seller_products instead (fields like special_offers, key_features, delivery_info, payment_methods, competitors_difference). As a general rule: if the seller is adding, changing, or removing ANY detail about something they actually sell (a feature, benefit, guarantee, support offering, policy, or selling point tied to a specific product) — even if the wording doesn't obviously sound like "product info" — it belongs on seller_products, not on generic-sounding business-config fields like "custom_rules". Only use seller_sales_config for settings that are clearly about HOW the business operates across every product (shipping method, MOQ default, sales tone) — not WHAT is being sold or offered. When in doubt, prefer seller_products and use the CURRENT FIELD VALUES context above to pick the single best-matching field.

DELIVERY TIMING — SPECIFIC FIELD, NOT GENERIC KNOWLEDGE: if the seller tells you WHEN customer delivery/shipping address should be collected (e.g. "don't ask for address until the order is ready to ship," "collect address at checkout," "we ask for a freight forwarder later") — this ALWAYS updates the seller_products.delivery_timing_preference field directly via an "update" operation, using the seller's instruction as the new value. Do NOT save this as a generic seller_knowledge Q&A entry — this specific type of instruction has its own dedicated field precisely so it's read reliably every time, not buried in a general knowledge list.

PARTIAL REMOVAL — CRITICAL: if a field currently holds MULTIPLE separate facts (check the CURRENT FIELD VALUES above) and the seller wants to remove only ONE of them, you MUST reconstruct the field's new value as the CURRENT text with ONLY that one fact taken out — never set the whole field to empty/blank just because the request was to "remove" something, unless the seller is clearly asking to clear the entire field. For example, if special_offers currently reads "Trial orders for first-time customers under 1000 sets with packaging fee only. 5% discount for repeat customers." and the seller says "remove the 5% discount, keep the trial order info," the new value must be "Trial orders for first-time customers under 1000 sets with packaging fee only." — not an empty string.

PARTIAL ADDITION — CRITICAL: if the seller wants to ADD a new detail to a field that (per the CURRENT FIELD VALUES above) already has existing content, use the "text_append" operation instead of "update" — do NOT write the merged value yourself. For example, if key_features currently reads "Six formulas available: ..." and the seller says "add that we've been manufacturing for 20 years," use text_append with fact_to_add: "we have been manufacturing for 20 years" — never use "update" with just the new fact alone, since that would silently overwrite and lose everything already in that field. Only use "update" directly when the field shown in CURRENT FIELD VALUES is genuinely empty.

AVAILABLE TABLES:
${schemaDescription}

Reply with ONLY this JSON, nothing else:
{
  "steps": [
    {
      "table": "one of the table names above",
      "operation": "insert" | "update" | "delete" | "query" | "increment" | "export" | "report" | "text_remove" | "text_append",
      "group_by": "for report only — which column to group results by",
      "agg_column": "for report only — which numeric column to aggregate",
      "agg_func": "for report only — one of: sum, count, avg, max, min",
      "filters": { "column": "value" },
      "values": { "column": "value" },
      "column": "for increment/text_remove/text_append only — which field to change",
      "delta": "for increment only — a number, positive to increase, negative to decrease",
      "fact_to_remove": "for text_remove only — a short description of just the ONE piece of information to take out of that field, e.g. 'the 5% repeat customer discount' — never the whole field's content",
      "fact_to_add": "for text_append only — the new fact/detail to add to that field, e.g. 'we have been manufacturing for 20 years' — never the whole new field content"
    }
  ],
  "summary": "one short sentence describing everything that will happen overall, including every implied step, written in ${fullLanguage || 'English'}${fullDialect ? ' (' + fullDialect + ' dialect)' : ''}"
}

Rules:
- For "insert", put the new record's fields in "values", leave "filters" empty.
- For "update" or "delete", put identifying info (e.g. a name to match) in "filters", and for update put the new field values in "values".
- For "text_remove" (the seller wants to remove just ONE fact/detail from a field that currently holds MULTIPLE facts, while keeping the rest) — use "filters" to identify the row, "column" for which field, and "fact_to_remove" describing just the one piece to take out. Do NOT attempt to write the resulting text yourself in "values" — the actual text surgery happens separately, precisely because reconstructing "everything except this one part" reliably in a single pass is error-prone. If the seller wants to clear a field completely (not just remove one part of several), use "update" with an empty string in "values" instead.
- For "text_append" (the seller wants to ADD a new fact/detail to a field, using the CURRENT FIELD VALUES context above to check whether that field already has other content) — use "filters" to identify the row, "column" for which field, and "fact_to_add" describing just the new fact to add. Do NOT write the combined value yourself in "values" — the actual merge happens separately, since composing "everything that's already there, plus this one new thing" reliably in a single pass is error-prone and has caused real data loss before. If the field shown in CURRENT FIELD VALUES is empty/blank, use "update" instead with the new value directly, since there's nothing to merge with.
- For "increment", use "filters" to identify the row, "column" for which numeric field to change, and "delta" for the amount (can be negative).
- For "query" (the seller is just asking to see/count something), leave "values" empty, put any filter criteria in "filters".
- For "export" (the seller wants a CSV file of their data), just set "table" — no other fields needed.
- For "report" (the seller is asking an analytical/aggregate question like "sales by month" or "best-selling products" or "expenses by category"), set "group_by" to the column to group by, "agg_column" to the numeric column to total/count/average, and "agg_func" to sum/count/avg/max/min as appropriate.
- Only use column/table names exactly as listed above. Never invent one.
- If the request doesn't clearly match anything available, reply with {"steps": [], "summary": ""}`,
        messages: [{ role: 'user', content: userText }]
      })
    });
    await logAiUsage.call(this, resp, 'business_management_step_planning');
    const parsed = JSON.parse(resp.content[0].text.trim().replace(/```json|```/g, ''));
    steps = parsed.steps || [];
    overallSummary = parsed.summary || '';
  } catch (e) { steps = []; }

  if (!steps || steps.length === 0) {
    await notifySeller.call(this, t(lang, '⚠️ ما فهمت شنو تريد تسوي بالضبط. جرب تفصل أكثر.', "⚠️ I couldn't tell exactly what you want to do. Try being a bit more specific."));
    return;
  }

  // Validate every step against the real schema, force ownership, drop anything invalid
  const safeSteps = [];
  let hasDelete = false;
  for (const step of steps) {
    const cfg = manageableTables[step.table];
    if (!cfg) continue;
    const safeValues = {};
    for (const [k, v] of Object.entries(step.values || {})) {
      if (cfg.columns.includes(k)) safeValues[k] = v;
    }
    const safeFilters = {};
    for (const [k, v] of Object.entries(step.filters || {})) {
      if (cfg.columns.includes(k) || k === cfg.idField) safeFilters[k] = v;
    }
    if (step.operation === 'insert') safeValues[cfg.ownerField] = chatId;
    if (step.operation === 'delete') hasDelete = true;
    const safeColumn = (step.column && cfg.columns.includes(step.column)) ? step.column : null;
    safeSteps.push({
      table: step.table,
      operation: step.operation,
      filters: safeFilters,
      values: safeValues,
      column: safeColumn,
      delta: step.delta,
      group_by: step.group_by,
      agg_column: step.agg_column,
      agg_func: step.agg_func,
      fact_to_remove: step.fact_to_remove,
      fact_to_add: step.fact_to_add
    });
  }

  if (safeSteps.length === 0) {
    await notifySeller.call(this, t(lang, '⚠️ ما فهمت شنو تريد تسوي بالضبط. جرب تفصل أكثر.', "⚠️ I couldn't tell exactly what you want to do. Try being a bit more specific."));
    return;
  }

  const needsConfirm =
    settings.confirmation_mode === 'confirm_always' ||
    (settings.confirmation_mode === 'confirm_delete' && hasDelete);

  const isQueryOnly = safeSteps.every(s => s.operation === 'query' || s.operation === 'report' || s.operation === 'export');

  if (needsConfirm && !isQueryOnly) {
    await setBotState.call(this, 'pending_manage_confirm', { steps: safeSteps, summary: overallSummary });
    await notifySeller.call(this, t(lang, `⚠️ ${overallSummary}\n\nمتأكد؟ رد "نعم" أو "لا"`, `⚠️ ${overallSummary}\n\nAre you sure? Reply "yes" or "no"`));
    return;
  }

  await executeManagementSteps.call(this, safeSteps, lang, overallSummary);
}

async function handlePendingManageConfirm(userText, lang) {
  const state = await getBotState.call(this);
  const { steps, summary } = state.context || {};
  const isYes = /نعم|yes|ok|اي|ايه/i.test(userText);
  await setBotState.call(this, 'idle', {});
  if (!isYes) {
    await notifySeller.call(this, t(lang, '✅ تم الإلغاء، ما تغير شي.', '✅ Cancelled, nothing changed.'));
    return;
  }
  await executeManagementSteps.call(this, steps, lang, summary);
}

async function executeManagementSteps(steps, lang, summary) {
  const manageableTables = await getManageableSchema.call(this);
  const queryResults = [];
  const zeroAffectedSteps = [];
  try {
    for (const step of steps) {
      const cfg = manageableTables[step.table];
      if (!cfg) continue;

      let filterQuery = cfg.ownerField + '=eq.' + chatId;
      for (const [k, v] of Object.entries(step.filters || {})) {
        if (k === cfg.idField || cfg.columns.includes(k)) {
          filterQuery += '&' + k + '=ilike.*' + encodeURIComponent(v) + '*';
        }
      }

      if (step.operation === 'insert') {
        await this.helpers.httpRequest({
          method: 'POST',
          url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/' + step.table,
          headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
          body: JSON.stringify(step.values)
        });
      } else if (step.operation === 'update') {
        const updateValues = { ...step.values };
        if (cfg.hasUpdatedAt) updateValues.updated_at = new Date().toISOString();
        const updateResult = await this.helpers.httpRequest({
          method: 'PATCH',
          url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/' + step.table + '?' + filterQuery,
          headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=representation' },
          body: JSON.stringify(updateValues)
        });
        if (!updateResult || updateResult.length === 0) zeroAffectedSteps.push(step.table);
      } else if (step.operation === 'delete') {
        const deleteResult = await this.helpers.httpRequest({
          method: 'DELETE',
          url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/' + step.table + '?' + filterQuery,
          headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Prefer': 'return=representation' }
        });
        if (!deleteResult || deleteResult.length === 0) zeroAffectedSteps.push(step.table);
      } else if (step.operation === 'increment' && step.column) {
        // Generic numeric increment: read current value, compute new value, write it back.
        // Works for ANY numeric column on ANY manageable table — this is what lets
        // things like "increase stock by 20" or "reduce stock by 5" work without
        // needing hand-written logic per feature.
        const current = await this.helpers.httpRequest({
          method: 'GET',
          url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/' + step.table + '?' + filterQuery + '&select=' + step.column + ',' + cfg.idField + '&limit=1',
          headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
        });
        if (current && current.length > 0) {
          const row = current[0];
          const newValue = (Number(row[step.column]) || 0) + (Number(step.delta) || 0);
          await this.helpers.httpRequest({
            method: 'PATCH',
            url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/' + step.table + '?' + cfg.idField + '=eq.' + row[cfg.idField],
            headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
            body: JSON.stringify({ [step.column]: newValue })
          });
        }
      } else if (step.operation === 'text_remove' && step.column && step.fact_to_remove) {
        // Surgical partial-text removal, isolated into its own single-purpose step
        // rather than trusting one big classification call to both plan the edit
        // AND correctly reconstruct "everything except this one part" — that
        // combined approach proved unreliable (it kept blanking the whole field
        // instead of preserving the rest). This dedicated call has exactly one
        // job: take the current text and the one fact to remove, return the rest.
        const current = await this.helpers.httpRequest({
          method: 'GET',
          url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/' + step.table + '?' + filterQuery + '&select=' + step.column + ',' + cfg.idField + '&limit=1',
          headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
        });
        if (current && current.length > 0) {
          const row = current[0];
          const currentText = row[step.column] || '';
          if (!currentText.trim()) {
            zeroAffectedSteps.push(step.table + ' (field already empty)');
          } else {
            const surgeryResp = await this.helpers.httpRequest({
              method: 'POST',
              url: 'https://api.anthropic.com/v1/messages',
              headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
              body: JSON.stringify({
                model: 'claude-haiku-4-5-20251001',
                max_tokens: 300,
                system: `You will be given a piece of text and a description of ONE specific fact to remove from it. Output ONLY the remaining text with that one fact taken out, preserving every other sentence and detail exactly as-is, with natural punctuation/spacing. Do not add anything new, do not summarize, do not rephrase the parts you keep. If removing that one fact genuinely leaves nothing else meaningful, output exactly: (empty)`,
                messages: [{ role: 'user', content: `TEXT: "${currentText}"\n\nFACT TO REMOVE: ${step.fact_to_remove}` }]
              })
            });
            await logAiUsage.call(this, surgeryResp, 'text_remove_surgery');
            let newText = (surgeryResp.content[0].text || '').trim();
            if (newText === '(empty)') newText = '';
            await this.helpers.httpRequest({
              method: 'PATCH',
              url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/' + step.table + '?' + cfg.idField + '=eq.' + row[cfg.idField],
              headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
              body: JSON.stringify({ [step.column]: newText, ...(cfg.hasUpdatedAt ? { updated_at: new Date().toISOString() } : {}) })
            });
          }
        } else {
          zeroAffectedSteps.push(step.table);
        }
      } else if (step.operation === 'text_append' && step.column && step.fact_to_add) {
        // Surgical text merge, isolated into its own single-purpose step for
        // the same reason as text_remove: trusting one big classification call
        // to both plan the edit AND correctly compose "everything that's
        // already there, plus this one new thing" proved unreliable — it kept
        // overwriting the whole field with just the new fact, discarding
        // everything that was there before. This dedicated call has exactly
        // one job: take the current text and the new fact, merge them naturally.
        const currentForAppend = await this.helpers.httpRequest({
          method: 'GET',
          url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/' + step.table + '?' + filterQuery + '&select=' + step.column + ',' + cfg.idField + '&limit=1',
          headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
        });
        if (currentForAppend && currentForAppend.length > 0) {
          const rowForAppend = currentForAppend[0];
          const currentTextForAppend = rowForAppend[step.column] || '';
          let mergedText;
          if (!currentTextForAppend.trim()) {
            mergedText = step.fact_to_add;
          } else {
            const mergeResp = await this.helpers.httpRequest({
              method: 'POST',
              url: 'https://api.anthropic.com/v1/messages',
              headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
              body: JSON.stringify({
                model: 'claude-haiku-4-5-20251001',
                max_tokens: 300,
                system: `You will be given a piece of existing text and ONE new fact to add to it. Output ONLY the combined text — keep every existing sentence and detail exactly as-is, and naturally add the new fact as an additional sentence. Do not remove, summarize, or rephrase anything that was already there.`,
                messages: [{ role: 'user', content: `EXISTING TEXT: "${currentTextForAppend}"\n\nNEW FACT TO ADD: ${step.fact_to_add}` }]
              })
            });
            await logAiUsage.call(this, mergeResp, 'text_append_merge');
            mergedText = (mergeResp.content[0].text || '').trim();
          }
          await this.helpers.httpRequest({
            method: 'PATCH',
            url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/' + step.table + '?' + cfg.idField + '=eq.' + rowForAppend[cfg.idField],
            headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
            body: JSON.stringify({ [step.column]: mergedText, ...(cfg.hasUpdatedAt ? { updated_at: new Date().toISOString() } : {}) })
          });
        } else {
          zeroAffectedSteps.push(step.table);
        }
      } else if (step.operation === 'query') {
        const rows = await this.helpers.httpRequest({
          method: 'GET',
          url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/' + step.table + '?' + filterQuery + '&select=*&limit=20',
          headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
        });
        queryResults.push({ table: step.table, rows: rows || [] });
      } else if (step.operation === 'export') {
        const rows = await this.helpers.httpRequest({
          method: 'GET',
          url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/' + step.table + '?' + filterQuery + '&select=*',
          headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
        });
        if (!rows || rows.length === 0) {
          await notifySeller.call(this, t(lang, `📭 ما في بيانات بجدول ${step.table} للتصدير.`, `📭 No data in ${step.table} to export.`));
          continue;
        }
        const headers = Object.keys(rows[0]);
        const csvEscape = (v) => {
          const s = v == null ? '' : String(v);
          return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
        };
        const csvLines = [headers.join(',')].concat(rows.map(r => headers.map(h => csvEscape(r[h])).join(',')));
        const csvContent = csvLines.join('\n');
        if (sourceChannel === 'web') {
          await notifySeller.call(this, t(lang, `📎 ملف ${step.table}.csv جاهز (${rows.length} صف) — حالياً تحميل الملفات متوفر بس من تيليجرام. اكتب نفس الطلب هناك لتستلمه.`, `📎 Your ${step.table}.csv is ready (${rows.length} rows) — file downloads are only available from Telegram right now. Ask the same thing there to receive it.`));
        } else {
          await this.helpers.httpRequest({
            method: 'POST',
            url: 'https://api.telegram.org/bot' + botToken + '/sendDocument',
            formData: {
              chat_id: chatId,
              document: {
                value: Buffer.from(csvContent, 'utf-8'),
                options: { filename: step.table + '.csv', contentType: 'text/csv' }
              }
            }
          });
        }
      } else if (step.operation === 'report') {
        const rpcResult = await this.helpers.httpRequest({
          method: 'POST',
          url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/rpc/seller_report',
          headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json' },
          body: JSON.stringify({
            p_seller_id: chatId,
            p_table: step.table,
            p_group_by: step.group_by,
            p_agg_column: step.agg_column,
            p_agg_func: step.agg_func
          })
        });
        queryResults.push({ table: step.table + ' report', rows: rpcResult || [] });
      }
    }

    if (queryResults.length > 0) {
      let msg = '';

      for (const qr of queryResults) {
        msg += t(lang, `📋 ${qr.table}: لقيت ${qr.rows.length} نتيجة.\n`, `📋 ${qr.table}: found ${qr.rows.length} result(s).\n`);
        if (qr.rows.length > 0) msg += JSON.stringify(qr.rows.slice(0, 5), null, 0) + '\n\n';
      }
      await notifySeller.call(this, msg.trim());
      return;
    }

    if (zeroAffectedSteps.length > 0) {
      await notifySeller.call(this, t(lang,
        `⚠️ ما لقيت شي يطابق وصفك بجدول ${zeroAffectedSteps.join(', ')}، فما تغير شي. جرب تكون أدق بالوصف.`,
        `⚠️ Couldn't find anything matching your description in ${zeroAffectedSteps.join(', ')}, so nothing changed. Try being more specific.`
      ));
      return;
    }

    await notifySeller.call(this, t(lang, `✅ تم. ${summary || ''}`, `✅ Done. ${summary || ''}`));
  } catch (e) {
    await notifySeller.call(this, t(lang, '⚠️ صار خطأ: ' + e.message, '⚠️ Something went wrong: ' + e.message));
  }
}

