async function sendWeeklyReport(lang) {
  try {
    const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
    const lastWeek2Ago = new Date(Date.now() - 14 * 24 * 60 * 60 * 1000).toISOString();

    // This week orders
    const thisWeekOrders = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/orders?seller_id=eq.' + chatId + '&created_at=gte.' + weekAgo + '&select=order_total,order_status,product_name,bump_accepted,bump_value,upsell_accepted,upsell_value',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
