    const revenueChange = lastRevenue > 0 ? Math.round(((thisRevenue - lastRevenue) / lastRevenue) * 100) : 0;
    const revenueArrow = revenueChange > 0 ? '📈' : revenueChange < 0 ? '📉' : '➡️';

    const delivered = thisWeekOrders.filter(o => o.order_status === 'DELIVERED').length;
    const pending = thisWeekOrders.filter(o => o.order_status === 'PENDING').length;
