    // Silent customers count
    const fourteenDaysAgo = new Date(Date.now() - 14 * 24 * 60 * 60 * 1000).toISOString();
    const silentCount = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/customers?seller_id=eq.' + chatId + '&last_reply_date=lte.' + fourteenDaysAgo + '&select=phone&limit=100',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
    }) || [];

    if (lang === 'english') {
      await notifySeller.call(this, `📊 <b>Weekly Intelligence Report</b>
${new Date().toLocaleDateString('en-GB')}

<b>📦 Orders This Week</b>
Total: ${thisWeekOrders.length} orders
${revenueArrow} Revenue: ${thisRevenue.toLocaleString()} ${globalCurrencyLabel} (${revenueChange > 0 ? '+' : ''}${revenueChange}% vs last week)
✅ Delivered: ${delivered} | ⏳ Pending: ${pending}
${topProduct ? `🔥 Best product: ${topProduct[0]} (${topProduct[1]} orders)` : ''}

<b>💡 Revenue Boosters</b>
Bump: ${bumpAccepted} accepted → +${bumpRevenue.toLocaleString()} ${globalCurrencyLabel}
Upsell: ${upsellAccepted} accepted → +${upsellRevenue.toLocaleString()} ${globalCurrencyLabel}

<b>😴 Silent Customers</b>
${silentCount.length} customers haven't replied in 14+ days

${pbData ? `<b>🧠 AI Learning</b>
${aiName || 'Your AI'} learned from ${pbData.total_conversations} total conversations
Close rate: ${pbData.close_rate_percentage}% — getting smarter!` : ''}

Type "alerts" for immediate action items 👇`);
    } else {
      await notifySeller.call(this, `📊 <b>تقرير الذكاء الأسبوعي</b>
${new Date().toLocaleDateString('en-GB')}

<b>📦 طلبات هالأسبوع</b>
المجموع: ${thisWeekOrders.length} طلب
${revenueArrow} الإيراد: ${thisRevenue.toLocaleString()} ${globalCurrencyLabel} (${revenueChange > 0 ? '+' : ''}${revenueChange}% مقارنة بالأسبوع الماضي)
✅ وصل: ${delivered} | ⏳ معلق: ${pending}
${topProduct ? `🔥 أكثر منتج مطلوب: ${topProduct[0]} (${topProduct[1]} طلب)` : ''}

<b>💡 مضاعفات الربح</b>
Bump: ${bumpAccepted} قبلوا → +${bumpRevenue.toLocaleString()} ${globalCurrencyLabel}
Upsell: ${upsellAccepted} قبلوا → +${upsellRevenue.toLocaleString()} ${globalCurrencyLabel}

<b>😴 الزبائن الصامتين</b>
${silentCount.length} زبون ما ردوا من أكثر من أسبوعين

