async function isOrderQuery(txt) {
  // Fast, deterministic path: a phone-number-like sequence combined with a
  // delivery-outcome word should always be treated as order-related — don't
  // leave something this important to a probabilistic AI guess.
  const hasPhoneNumber = /\d{7,}/.test(txt);
  const hasDeliveryWord = /arriv|receiv|reject|deliver|half|partial|paid|وصل|رفض|استلم|نصف|جزئي/i.test(txt);
  if (hasPhoneNumber && hasDeliveryWord) return true;

  try {
    const claudeResponse = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.anthropic.com/v1/messages',
      headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 10,
        system: 'You detect if a message is about orders — viewing orders, updating order status, marking as shipped/delivered/cancelled, checking COD, order analytics, revenue, best products, sending order notifications to customers, OR reporting a delivery outcome for a specific order/phone number (e.g. "07701234567 arrived fine", "that order was rejected, nothing received", "07701234567 half arrived, 20000 received") — these delivery-outcome replies should also be YES even without the word "order" in them. Reply ONLY with YES or NO.',
        messages: [{ role: 'user', content: txt }]
      })
    });
    await logAiUsage.call(this, claudeResponse, 'is_order_query_classifier');
    return claudeResponse.content[0].text.trim().toUpperCase().startsWith('YES');
  } catch(e) { return false; }
}

async function handleOrderQuery(userText, lang) {
  const planResponse = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.anthropic.com/v1/messages',
    headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: 'claude-haiku-4-5-20251001',
      max_tokens: 500,
      system: `You are an order management planner for a wholesale/retail business.
Orders table columns: id, customer_id, phone, product_name, product_price, bump_offered, bump_accepted, bump_value, upsell_offered, upsell_accepted, upsell_product, upsell_value, order_total, delivery_address, order_status (PENDING/SHIPPED/DELIVERED/CANCELLED), confirmed_at, shipped_at, cod_collected (boolean), created_at, day_3_checkin_sent, day_7_referral_sent, amount_received
Analyze and return ONLY JSON:
{
  "action": "view" or "update_status" or "mark_cod" or "analytics" or "send_notification",
  "filter": { "status": null, "phone": null, "product": null, "date_range": null, "overdue_days": null, "cod_pending": null },
  "update": { "order_id": null, "phone": null, "new_status": null, "cod_collected": null, "amount_received": null },
  "notification": { "phone": null, "type": null, "custom_message": null },
  "analytics_type": null,
  "limit": 20
}

IMPORTANT for delivery check-in replies (the seller answering "did this order arrive?"):
- Any message describing what happened when an order was delivered (arrived fine, rejected, half arrived, etc.) is an "update_status" action, NOT "view" — even if it doesn't explicitly say "update" or "mark as."
- If the seller says it arrived fine / fully delivered / no issues: action = "update_status", new_status = "DELIVERED", amount_received = null (meaning: use the full order_total, nothing partial)
- If the seller says it was fully rejected / customer refused everything / nothing received: action = "update_status", new_status = "CANCELLED", amount_received should be 0
- If the seller describes a PARTIAL outcome (e.g. "half arrived, 200000 received", "customer took some and rejected some, we got 150000"): action = "update_status", new_status = "DELIVERED", amount_received = the specific number they mentioned as actually received
- Always put the phone number mentioned into update.phone so the right order can be found.
Return ONLY valid JSON.`,
      messages: [{ role: 'user', content: userText }]
    })
  });

  await logAiUsage.call(this, planResponse, 'order_query_plan');
  let plan = { action: 'view', filter: {}, update: {}, notification: {}, analytics_type: null, limit: 20 };
  try { plan = JSON.parse(planResponse.content[0].text.trim().replace(/```json|```/g, '')); } catch (e) { logSystemError.call(this, chatId, 'Parsing weekly analytics plan from AI response', e && e.message); }

  const today = new Date().toISOString().split('T')[0];

  if (plan.action === 'view') {
    let url = 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/orders?seller_id=eq.' + chatId + '&select=id,phone,product_name,order_total,order_status,delivery_address,cod_collected,created_at,shipped_at,bump_accepted,bump_value,upsell_accepted,upsell_product,upsell_value,amount_received&order=created_at.desc&limit=' + (plan.limit || 20);
    const f = plan.filter || {};
    if (f.status) url += '&order_status=eq.' + f.status;
    if (f.phone) url += '&phone=eq.' + f.phone;
    if (f.product) url += '&product_name=ilike.*' + encodeURIComponent(f.product) + '*';
    if (f.cod_pending === true) url += '&cod_collected=eq.false&order_status=eq.DELIVERED';
    if (f.date_range === 'today') url += '&created_at=gte.' + today + 'T00:00:00';
    else if (f.date_range === 'week') { const w = new Date(Date.now() - 7*24*60*60*1000).toISOString(); url += '&created_at=gte.' + w; }
    else if (f.date_range === 'month') { const m = new Date(Date.now() - 30*24*60*60*1000).toISOString(); url += '&created_at=gte.' + m; }

    let orders = [];
    try { orders = await this.helpers.httpRequest({ method: 'GET', url, headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey } }) || []; } catch(e) { await notifySeller.call(this, '⚠️ فشل جلب الطلبات.'); return; }

    if (f.overdue_days) { const cutoff = new Date(Date.now() - f.overdue_days * 24 * 60 * 60 * 1000); orders = orders.filter(o => o.order_status === 'PENDING' && new Date(o.created_at) < cutoff); }
    if (orders.length === 0) { await notifySeller.call(this, t(lang, '📭 ما في طلبات.', '📭 No orders found.')); return; }

    const statusEmoji = { PENDING: '⏳', SHIPPED: '🚚', DELIVERED: '✅', CANCELLED: '❌' };
    let msg = t(lang, `📦 <b>الطلبات (${orders.length})</b>\n\n`, `📦 <b>Orders (${orders.length})</b>\n\n`);
    for (const o of orders.slice(0, 15)) {
      const date = o.created_at ? new Date(o.created_at).toLocaleDateString('en-GB') : '';
      const emoji = statusEmoji[o.order_status] || '📦';
      const cod = o.cod_collected === false && o.order_status === 'DELIVERED' ? ' 💰 COD pending' : o.cod_collected === true ? ' 💰✅' : '';
      const extras = [];
      if (o.bump_accepted) extras.push('Bump ✅');
      if (o.upsell_accepted) extras.push('Upsell ✅');
      msg += `${emoji} <b>${o.phone}</b>\n${o.product_name || '—'} — ${(o.order_total || 0).toLocaleString()} ${globalCurrencyLabel}${cod}${extras.length > 0 ? ' | ' + extras.join(', ') : ''}\n📍 ${o.delivery_address || '—'} | 📅 ${date}\n🆔 <code>${o.id}</code>\n\n`;
    }
    if (orders.length > 15) msg += t(lang, `... و ${orders.length - 15} طلب آخر`, `... and ${orders.length - 15} more`);
    const totalRevenue = orders.reduce((s, o) => s + (o.order_total || 0), 0);
    msg += t(lang, `\n💰 <b>المجموع: ${totalRevenue.toLocaleString()} ${globalCurrencyLabel}</b>`, `\n💰 <b>Total: ${totalRevenue.toLocaleString()} ${globalCurrencyLabel}</b>`);
    if (msg.length > 3500) { const parts = msg.match(/.{1,3500}/gs) || [msg]; for (const part of parts) await notifySeller.call(this, part); }
    else await notifySeller.call(this, msg);
    return;
  }

  if (plan.action === 'update_status') {
    const u = plan.update || {};
    const newStatus = u.new_status;
    if (!newStatus) { await notifySeller.call(this, t(lang, '⚠️ حدد الحالة الجديدة', '⚠️ Specify new status')); return; }
    const updateData = { order_status: newStatus };
    if (u.amount_received !== null && u.amount_received !== undefined) updateData.amount_received = u.amount_received;
    if (newStatus === 'SHIPPED') updateData.shipped_at = new Date().toISOString();
    if (newStatus === 'DELIVERED') updateData.cod_collected = false;
    let updateUrl = '';
    let targetPhone = '';
    if (u.order_id) {
      updateUrl = 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/orders?id=eq.' + u.order_id + '&seller_id=eq.' + chatId;
    } else if (u.phone) {
      targetPhone = u.phone.replace(/=/g, '').replace(/\+/g, '').replace(/\s/g, '');
      try {
        const existing = await this.helpers.httpRequest({ method: 'GET', url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/orders?seller_id=eq.' + chatId + '&phone=eq.' + targetPhone + '&order_status=eq.PENDING&order=created_at.desc&limit=1&select=id', headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey } });
        if (!existing || existing.length === 0) {
          const any = await this.helpers.httpRequest({ method: 'GET', url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/orders?seller_id=eq.' + chatId + '&phone=eq.' + targetPhone + '&order=created_at.desc&limit=1&select=id,order_status', headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey } });
          if (!any || any.length === 0) { await notifySeller.call(this, t(lang, '⚠️ ما لقيت طلب.', '⚠️ No order found.')); return; }
          updateUrl = 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/orders?id=eq.' + any[0].id;
        } else { updateUrl = 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/orders?id=eq.' + existing[0].id; }
      } catch(e) { await notifySeller.call(this, '⚠️ ' + e.message); return; }
    } else { await notifySeller.call(this, t(lang, '⚠️ محتاج رقم العميل أو ID الطلب', '⚠️ Need customer phone or order ID')); return; }

    try {
      await this.helpers.httpRequest({ method: 'PATCH', url: updateUrl, headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=representation' }, body: JSON.stringify(updateData) })
        .then(async (updatedRows) => {
          const statusLabels = { SHIPPED: t(lang, '🚚 تم الشحن', '🚚 Shipped'), DELIVERED: t(lang, '✅ تم التوصيل', '✅ Delivered'), CANCELLED: t(lang, '❌ تم الإلغاء', '❌ Cancelled') };
          await notifySeller.call(this, t(lang, `✅ تم تحديث الطلب: ${statusLabels[newStatus] || newStatus}${targetPhone ? '\nللعميل: ' + targetPhone : ''}`, `✅ Order updated: ${statusLabels[newStatus] || newStatus}${targetPhone ? '\nCustomer: ' + targetPhone : ''}`));
          if (targetPhone && (newStatus === 'SHIPPED' || newStatus === 'DELIVERED')) {
            const msgs = { SHIPPED: lang === 'english' ? 'Your order has been shipped! 🚚' : 'طلبك انشحن وراح يوصلك قريب! 🚚', DELIVERED: lang === 'english' ? 'Your order has been delivered. Thank you! ✅' : 'طلبك وصل، شكراً لك! ✅' };
            try { await sendWhatsApp.call(this, targetPhone, msgs[newStatus]); await notifySeller.call(this, t(lang, '📱 تم إرسال إشعار للعميل', '📱 Customer notified on WhatsApp')); } catch (e) { logSystemError.call(this, chatId, 'Notifying customer of order status change on WhatsApp', e && e.message); }
            // Trigger learning after order delivered
            if (newStatus === 'DELIVERED') {
              extractAndLearnFromConversation.call(this, targetPhone, 'ordered');

              // ═══════════════════════════════════════════════
              // META CAPI — "Purchase" event, fired here at genuine DELIVERY
              // (not at order-confirmed) specifically to avoid reporting sales
              // to Meta that later get cancelled/refused before ever completing —
              // Meta has no way to "undo" a Purchase event once reported, so we
              // only report once the sale is actually real.
              // Skips silently if this seller doesn't have ads tracking enabled,
              // or if this customer never came in through a tracked ad click.
              // ═══════════════════════════════════════════════
              try {
                const deliveredOrder = (updatedRows && updatedRows[0]) || {};
                const adConfigResp = await this.helpers.httpRequest({
                  method: 'GET',
                  url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_ad_config?chat_id=eq.' + chatId + '&select=meta_dataset_id,meta_ads_token,waba_id,enabled&limit=1',
                  headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
                });
                const adConfig = adConfigResp && adConfigResp.length > 0 ? adConfigResp[0] : null;

                if (adConfig && adConfig.enabled === true && adConfig.meta_dataset_id && adConfig.meta_ads_token) {
                  const custAdResp = await this.helpers.httpRequest({
                    method: 'GET',
                    url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/customers?phone=eq.' + targetPhone + '&seller_id=eq.' + chatId + '&select=ctwa_clid&limit=1',
                    headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
                  });
                  const ctwaClid = custAdResp && custAdResp.length > 0 ? custAdResp[0].ctwa_clid : null;
                  const finalValue = (deliveredOrder.amount_received !== null && deliveredOrder.amount_received !== undefined) ? deliveredOrder.amount_received : (deliveredOrder.order_total || 0);

                  if (ctwaClid && finalValue > 0) {
                    const crypto = require('crypto');
                    const hashedPhone = crypto.createHash('sha256').update(targetPhone.trim().toLowerCase()).digest('hex');

                    await this.helpers.httpRequest({
                      method: 'POST',
                      url: 'https://graph.facebook.com/v19.0/' + adConfig.meta_dataset_id + '/events',
                      headers: { 'Authorization': 'Bearer ' + adConfig.meta_ads_token, 'Content-Type': 'application/json' },
                      body: JSON.stringify({
                        data: [{
                          event_name: 'Purchase',
                          event_time: Math.floor(Date.now() / 1000),
                          action_source: 'business_messaging',
                          messaging_channel: 'whatsapp',
                          user_data: {
                            whatsapp_business_account_id: adConfig.waba_id,
                            ctwa_clid: ctwaClid,
                            ph: hashedPhone
                          },
                          custom_data: {
                            currency: globalCurrencyLabel || 'USD',
                            value: finalValue
                          }
                        }]
                      })
                    });
                  }
                }
              } catch(e) {
                // never let a CAPI failure block the actual delivery flow
              }
            }
          }
        });
    } catch(e) { await notifySeller.call(this, '⚠️ ' + e.message); }
    return;
  }

  if (plan.action === 'mark_cod') {
    const u = plan.update || {};
    let updateUrl = '';
    let targetPhone = '';
if (u.order_id) { updateUrl = 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/orders?id=eq.' + u.order_id + '&seller_id=eq.' + chatId; }
    else if (u.phone) {
      targetPhone = u.phone.replace(/=/g, '').replace(/\+/g, '').replace(/\s/g, '');
      try {
        const existing = await this.helpers.httpRequest({ method: 'GET', url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/orders?seller_id=eq.' + chatId + '&phone=eq.' + targetPhone + '&cod_collected=eq.false&order_status=eq.DELIVERED&order=created_at.desc&limit=1&select=id', headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey } });
        if (!existing || existing.length === 0) { await notifySeller.call(this, t(lang, '⚠️ ما لقيت طلب COD معلق.', '⚠️ No pending COD order found.')); return; }
        updateUrl = 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/orders?id=eq.' + existing[0].id;
      } catch(e) { await notifySeller.call(this, '⚠️ ' + e.message); return; }
    } else { await notifySeller.call(this, t(lang, '⚠️ محتاج رقم العميل', '⚠️ Need customer phone')); return; }
    try {
      await this.helpers.httpRequest({ method: 'PATCH', url: updateUrl, headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' }, body: JSON.stringify({ cod_collected: true }) });
      await notifySeller.call(this, t(lang, '💰✅ تم تسجيل استلام الكاش' + (targetPhone ? ' للعميل ' + targetPhone : ''), '💰✅ COD marked as collected' + (targetPhone ? ' for ' + targetPhone : '')));
    } catch(e) { await notifySeller.call(this, '⚠️ ' + e.message); }
    return;
  }

  if (plan.action === 'analytics') {
    let orders = [];
    try {
      let url = 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/orders?seller_id=eq.' + chatId + '&select=phone,product_name,order_total,order_status,bump_offered,bump_accepted,bump_value,upsell_offered,upsell_accepted,upsell_value,cod_collected,created_at&limit=1000';
      const f = plan.filter || {};
      if (f.date_range === 'today') url += '&created_at=gte.' + today + 'T00:00:00';
      else if (f.date_range === 'week') { const w = new Date(Date.now() - 7*24*60*60*1000).toISOString(); url += '&created_at=gte.' + w; }
      else if (f.date_range === 'month') { const m = new Date(Date.now() - 30*24*60*60*1000).toISOString(); url += '&created_at=gte.' + m; }
      orders = await this.helpers.httpRequest({ method: 'GET', url, headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey } }) || [];
    } catch(e) { await notifySeller.call(this, '⚠️ ' + e.message); return; }

    const total = orders.length;
    const pending = orders.filter(o => o.order_status === 'PENDING').length;
    const shipped = orders.filter(o => o.order_status === 'SHIPPED').length;
    const delivered = orders.filter(o => o.order_status === 'DELIVERED').length;
    const cancelled = orders.filter(o => o.order_status === 'CANCELLED').length;
    const totalRevenue = orders.reduce((s, o) => s + (o.order_total || 0), 0);
    const avgOrder = total > 0 ? Math.round(totalRevenue / total) : 0;
    const codPending = orders.filter(o => o.order_status === 'DELIVERED' && o.cod_collected === false).length;
    const bumpOffered = orders.filter(o => o.bump_offered).length;
    const bumpAccepted = orders.filter(o => o.bump_accepted).length;
    const bumpRevenue = orders.reduce((s, o) => s + (o.bump_value || 0), 0);
    const upsellOffered = orders.filter(o => o.upsell_offered).length;
    const upsellAccepted = orders.filter(o => o.upsell_accepted).length;
    const upsellRevenue = orders.reduce((s, o) => s + (o.upsell_value || 0), 0);
    const productCount = {};
    orders.forEach(o => { if (o.product_name) productCount[o.product_name] = (productCount[o.product_name] || 0) + 1; });
    const topProducts = Object.entries(productCount).sort((a, b) => b[1] - a[1]).slice(0, 3);
    const todayOrders = orders.filter(o => o.created_at && o.created_at.startsWith(today));
    const todayRevenue = todayOrders.reduce((s, o) => s + (o.order_total || 0), 0);

    if (lang === 'english') {
      await notifySeller.call(this, `📊 <b>Order Analytics</b>
Total: ${total} | Today: ${todayOrders.length}
⏳ Pending: ${pending} | 🚚 Shipped: ${shipped} | ✅ Delivered: ${delivered} | ❌ Cancelled: ${cancelled}
💰 COD pending: ${codPending}

Revenue Total: ${totalRevenue.toLocaleString()} ${globalCurrencyLabel} | Today: ${todayRevenue.toLocaleString()} ${globalCurrencyLabel} | Avg: ${avgOrder.toLocaleString()} ${globalCurrencyLabel}
🔥 Top: ${topProducts.map((p, i) => `${i+1}. ${p[0]} (${p[1]})`).join(', ') || 'No data'}

Bump: ${bumpAccepted}/${bumpOffered} (${bumpOffered > 0 ? Math.round(bumpAccepted/bumpOffered*100) : 0}%) → +${bumpRevenue.toLocaleString()} ${globalCurrencyLabel}
Upsell: ${upsellAccepted}/${upsellOffered} (${upsellOffered > 0 ? Math.round(upsellAccepted/upsellOffered*100) : 0}%) → +${upsellRevenue.toLocaleString()} ${globalCurrencyLabel}`);
    } else {
      await notifySeller.call(this, `📊 <b>تحليل الطلبات</b>
المجموع: ${total} | اليوم: ${todayOrders.length}
⏳ معلق: ${pending} | 🚚 شُحن: ${shipped} | ✅ وصل: ${delivered} | ❌ ملغي: ${cancelled}
💰 COD لم يُحصّل: ${codPending}

الإيراد: ${totalRevenue.toLocaleString()} ${globalCurrencyLabel} | اليوم: ${todayRevenue.toLocaleString()} | متوسط: ${avgOrder.toLocaleString()} ${globalCurrencyLabel}
🔥 الأكثر: ${topProducts.map((p, i) => `${i+1}. ${p[0]} (${p[1]})`).join('، ') || 'لا بيانات'}

Bump: ${bumpAccepted}/${bumpOffered} (${bumpOffered > 0 ? Math.round(bumpAccepted/bumpOffered*100) : 0}%) ← +${bumpRevenue.toLocaleString()} ${globalCurrencyLabel}
Upsell: ${upsellAccepted}/${upsellOffered} (${upsellOffered > 0 ? Math.round(upsellAccepted/upsellOffered*100) : 0}%) ← +${upsellRevenue.toLocaleString()} ${globalCurrencyLabel}`);
    }
    return;
  }

  if (plan.action === 'send_notification') {
    const n = plan.notification || {};
    const targetPhone = (n.phone || '').replace(/=/g, '').replace(/\+/g, '').replace(/\s/g, '');
    if (!targetPhone) { await notifySeller.call(this, t(lang, '⚠️ محتاج رقم العميل', '⚠️ Need customer phone')); return; }
    let msg = n.custom_message || '';
    if (!msg) {
      if (n.type === 'shipped') msg = lang === 'english' ? 'Your order has been shipped! 🚚' : 'طلبك انشحن وراح يوصلك قريب! 🚚';
      else if (n.type === 'delivered') msg = lang === 'english' ? 'Your order has been delivered. Thank you! ✅' : 'طلبك وصل، شكراً لك! ✅';
      else msg = lang === 'english' ? 'Update regarding your order.' : 'تحديث بخصوص طلبك.';
    }
    try { await sendWhatsApp.call(this, targetPhone, msg); await notifySeller.call(this, t(lang, '✅ تم إرسال الإشعار للعميل ' + targetPhone, '✅ Notification sent to ' + targetPhone)); } catch(e) { await notifySeller.call(this, '⚠️ ' + e.message); }
    return;
  }

  await notifySeller.call(this, t(lang, '⚠️ ما فهمت طلب الطلبات.', '⚠️ Could not understand order request.'));
}

// ═══ INTELLIGENT CRM EXPORT ═══
async function handleExportQuery(userText, lang) {
  await notifySeller.call(this, t(lang, '⏳ جاري تحضير الملف...', '⏳ Preparing your file...'));
  let plan = { format: 'excel', filename: 'customers', needs_orders: false, customer_filter: {}, customer_columns: ['phone', 'name', 'is_wholesale', 'total_orders', 'total_spent', 'last_purchase_date', 'is_vip', 'list_status'], sort_by: null, sort_direction: 'desc', add_summary_row: false, include_order_history: false };
  try {
    const planResponse = await this.helpers.httpRequest({
      method: 'POST', url: 'https://api.anthropic.com/v1/messages',
      headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001', max_tokens: 600,
        system: `You are an intelligent data export planner for a WhatsApp sales CRM.
customers table columns: phone, name, is_wholesale, total_orders, total_spent, last_purchase_date, is_vip, list_status, last_reply_date, created_at
orders table columns: phone, product_name, order_total, order_status, created_at
Return ONLY JSON:
{ "format": "csv" or "excel" or "pdf", "filename": "descriptive_name", "needs_orders": true or false, "customer_filter": { "is_wholesale": null, "is_vip": null, "list_status": null, "specific_phone": null, "silent_days": null, "new_days": null, "order_product": null }, "customer_columns": ["phone","name","is_wholesale","total_orders","total_spent","last_purchase_date","is_vip","list_status"], "sort_by": null, "sort_direction": "desc", "add_summary_row": false, "include_order_history": false }`,
        messages: [{ role: 'user', content: userText }]
      })
    });
    await logAiUsage.call(this, planResponse, 'export_query_plan');
    try { plan = JSON.parse(planResponse.content[0].text.trim().replace(/```json|```/g, '')); } catch (e) { logSystemError.call(this, chatId, 'Parsing report plan from AI response', e && e.message); }
  } catch (e) {
    // This call previously had no error handling at all - a single failed
    // request here (network blip, Anthropic API hiccup) would silently
    // crash the entire export with zero explanation. Now it's logged, and
    // we fall back to sensible defaults (export everything as Excel)
    // instead of losing the whole request.
    logSystemError.call(this, chatId, 'Building export plan from AI response', e && e.message, { userText: (userText || '').slice(0, 200) });
  }

  const validCustomerCols = ['phone', 'name', 'is_wholesale', 'total_orders', 'total_spent', 'last_purchase_date', 'is_vip', 'list_status', 'last_reply_date', 'created_at'];
  let selectCols = (plan.customer_columns || validCustomerCols).filter(c => validCustomerCols.includes(c));
  if (!selectCols.includes('phone')) selectCols.unshift('phone');

  let customerUrl = 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/customers?seller_id=eq.' + chatId + '&select=' + selectCols.join(',') + '&limit=1000';
  const filter = plan.customer_filter || {};
  if (filter.is_wholesale === true) customerUrl += '&is_wholesale=eq.true';
  else if (filter.is_wholesale === false) customerUrl += '&is_wholesale=eq.false';
  if (filter.is_vip === true) customerUrl += '&is_vip=eq.true';
  if (filter.list_status) customerUrl += '&list_status=eq.' + filter.list_status;
  if (filter.specific_phone) customerUrl += '&phone=eq.' + filter.specific_phone;
  if (plan.sort_by && validCustomerCols.includes(plan.sort_by)) customerUrl += '&order=' + plan.sort_by + '.' + (plan.sort_direction || 'desc');

  let customers = [];
  try { customers = await this.helpers.httpRequest({ method: 'GET', url: customerUrl, headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey } }) || []; }
  catch(e) { await notifySeller.call(this, t(lang, '⚠️ فشل جلب البيانات: ' + e.message, '⚠️ Failed to fetch data: ' + e.message)); return; }

  if (filter.silent_days) { const cutoff = new Date(Date.now() - filter.silent_days * 24 * 60 * 60 * 1000); customers = customers.filter(c => !c.last_reply_date || new Date(c.last_reply_date) < cutoff); }
  if (filter.new_days) { const cutoff = new Date(Date.now() - filter.new_days * 24 * 60 * 60 * 1000); customers = customers.filter(c => c.created_at && new Date(c.created_at) >= cutoff); }

  let ordersMap = {};
  if (plan.needs_orders || plan.include_order_history) {
    try {
      const ordersRes = await this.helpers.httpRequest({ method: 'GET', url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/orders?seller_id=eq.' + chatId + '&select=phone,product_name,order_total,order_status,created_at&order=created_at.desc&limit=5000', headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey } }) || [];
      let filteredOrders = ordersRes;
      if (filter.order_product) { filteredOrders = ordersRes.filter(o => o.product_name && o.product_name.toLowerCase().includes(filter.order_product.toLowerCase())); const phonesWithProduct = new Set(filteredOrders.map(o => o.phone)); customers = customers.filter(c => phonesWithProduct.has(c.phone)); }
      filteredOrders.forEach(o => { if (!ordersMap[o.phone]) ordersMap[o.phone] = []; ordersMap[o.phone].push(o); });
    } catch (e) { logSystemError.call(this, chatId, 'Grouping filtered orders by phone', e && e.message); }
  }

  if (customers.length === 0) { await notifySeller.call(this, t(lang, '📭 ما في زبائن.', '📭 No customers found.')); return; }

  const columnHeaderMap = { phone: lang === 'english' ? 'Phone' : 'رقم الهاتف', name: lang === 'english' ? 'Name' : 'الاسم', is_wholesale: lang === 'english' ? 'Type' : 'النوع', total_orders: lang === 'english' ? 'Total Orders' : 'عدد الطلبات', total_spent: lang === 'english' ? `Total Spent (${globalCurrencyLabel})` : `إجمالي الإنفاق (${globalCurrencyLabel})`, last_purchase_date: lang === 'english' ? 'Last Purchase' : 'آخر طلب', is_vip: lang === 'english' ? 'VIP' : 'VIP', list_status: lang === 'english' ? 'Status' : 'الحالة', last_reply_date: lang === 'english' ? 'Last Reply' : 'آخر رد', created_at: lang === 'english' ? 'Added Date' : 'تاريخ الإضافة' };
  const displayCols = selectCols.filter(c => columnHeaderMap[c]);
  const columns = displayCols.map(c => columnHeaderMap[c]);
  if (plan.include_order_history) columns.push(lang === 'english' ? 'Order History' : 'تاريخ الطلبات');

  const formattedCustomers = customers.map(c => {
    const row = {};
    displayCols.forEach(col => {
      const header = columnHeaderMap[col];
      if (col === 'is_wholesale') row[header] = c.is_wholesale === true ? (lang === 'english' ? 'Wholesale' : 'جملة') : c.is_wholesale === false ? (lang === 'english' ? 'Retail' : 'مفرد') : '';
      else if (col === 'is_vip') row[header] = c.is_vip ? '⭐ VIP' : '';
      else if (['last_purchase_date', 'last_reply_date', 'created_at'].includes(col)) row[header] = c[col] ? new Date(c[col]).toLocaleDateString('en-GB') : '';
      else row[header] = c[col] !== null && c[col] !== undefined ? String(c[col]) : '';
    });
    if (plan.include_order_history) { const orders = ordersMap[c.phone] || []; const orderHeader = lang === 'english' ? 'Order History' : 'تاريخ الطلبات'; row[orderHeader] = orders.length > 0 ? orders.map(o => `${o.product_name || '—'} - ${(o.order_total || 0).toLocaleString()} ${globalCurrencyLabel} - ${o.order_status || ''} (${o.created_at ? new Date(o.created_at).toLocaleDateString('en-GB') : ''})`).join(' | ') : ''; }
    return row;
  });

  if (plan.add_summary_row && formattedCustomers.length > 0) {
    const summaryRow = {}; columns.forEach(col => { summaryRow[col] = ''; });
    summaryRow[columns[0]] = lang === 'english' ? `TOTAL: ${customers.length} customers` : `المجموع: ${customers.length} زبون`;
    const tsh = columnHeaderMap['total_spent']; const toh = columnHeaderMap['total_orders'];
    if (columns.includes(tsh)) summaryRow[tsh] = customers.reduce((s, c) => s + (c.total_spent || 0), 0).toLocaleString();
    if (columns.includes(toh)) summaryRow[toh] = String(customers.reduce((s, c) => s + (c.total_orders || 0), 0));
    formattedCustomers.push(summaryRow);
  }

  try {
    await this.helpers.httpRequest({ method: 'POST', url: exportServiceUrl, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ chat_id: chatId, customers: formattedCustomers, columns, format: plan.format || 'excel', filename: (plan.filename || 'customers') + '_' + new Date().toISOString().split('T')[0] }) });
  } catch(e) { await notifySeller.call(this, t(lang, '⚠️ فشل إرسال الملف: ' + e.message, '⚠️ Failed to send file: ' + e.message)); }
}

async function isExportQuery(txt) {
  try {
    const claudeResponse = await this.helpers.httpRequest({ method: 'POST', url: 'https://api.anthropic.com/v1/messages', headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' }, body: JSON.stringify({ model: 'claude-haiku-4-5-20251001', max_tokens: 10, system: 'You detect if a message is asking to export, download, get a file, or extract data about customers — including customer lists, chat history, order history, reports, or any data export request. Reply ONLY with YES or NO.', messages: [{ role: 'user', content: txt }] }) });
