}

async function handleConversationQuery(userText, lang, fullLanguage, fullDialect) {
  const phoneMatch = userText.match(/964\d{9,}|\d{10,}/);
  if (!phoneMatch) { await notifySeller.call(this, t(lang, '⚠️ محتاج رقم العميل.', '⚠️ Need customer number.')); return; }
  const customerPhone = phoneMatch[0];
  let conversations = [];
  try { conversations = await this.helpers.httpRequest({ method: 'GET', url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/conversations?phone_number=eq.' + customerPhone + '&seller_id=eq.' + chatId + '&select=role,message,timestamp&order=timestamp.asc&limit=200', headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey } }) || []; } catch(e) { await notifySeller.call(this, t(lang, '⚠️ ما قدرت أجيب المحادثة.', '⚠️ Could not fetch conversation.')); return; }
  if (conversations.length === 0) { await notifySeller.call(this, t(lang, '📭 ما في محادثات لهذا الرقم: ' + customerPhone, '📭 No conversations found for: ' + customerPhone)); return; }
  const formattedConversations = conversations.map(m => { const time = m.timestamp ? new Date(m.timestamp).toLocaleString('en-GB', { timeZone: 'Asia/Baghdad' }) : ''; return `[${time}] ${m.role === 'user' ? '👤 Customer' : '🤖 Ahmad'}: ${m.message}`; }).join('\n');
