async function addToBatch(newMessage) {
  try {
    const now = new Date().toISOString();
    const existing = await this.helpers.httpRequest({ method: 'GET', url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/pending_telegram_messages?chat_id=eq.' + chatId + '&status=eq.pending&select=*&limit=1', headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey } });
    if (existing && existing.length > 0) {
      const current = existing[0];
      await this.helpers.httpRequest({ method: 'PATCH', url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/pending_telegram_messages?id=eq.' + current.id, headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' }, body: JSON.stringify({ messages: [...(current.messages || []), newMessage], last_message_at: now }) });
      return { batchId: current.id, myTimestamp: now };
    } else {
      const result = await this.helpers.httpRequest({ method: 'POST', url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/pending_telegram_messages', headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=representation' }, body: JSON.stringify({ chat_id: chatId, messages: [newMessage], last_message_at: now, status: 'pending' }) });
      return { batchId: result && result[0] ? result[0].id : null, myTimestamp: now };
    }
  } catch(e) { return { batchId: null, myTimestamp: new Date().toISOString() }; }
}

async function getBatchAndProcess(batchId, myTimestamp) {
  try {
    await new Promise(resolve => setTimeout(resolve, 4000));
    const batch = await this.helpers.httpRequest({ method: 'GET', url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/pending_telegram_messages?id=eq.' + batchId + '&select=*&limit=1', headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey } });
    if (!batch || batch.length === 0 || batch[0].status !== 'pending') return null;
    if (new Date(batch[0].last_message_at).getTime() > new Date(myTimestamp).getTime() + 500) return null;
    await this.helpers.httpRequest({ method: 'PATCH', url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/pending_telegram_messages?id=eq.' + batchId, headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' }, body: JSON.stringify({ status: 'processing' }) });
    return (batch[0].messages || []).join('\n');
  } catch(e) { return null; }
}

