// Meta's WhatsApp API needs an explicit mime_type for document sends — inferring
// purely from the filename extension isn't reliable enough and can cause a 400,
// especially for common business file types like Excel spreadsheets.
function getMimeTypeForFilename(fileName) {
  const ext = (fileName || '').toLowerCase().split('.').pop();
  const map = {
    pdf: 'application/pdf',
    doc: 'application/msword',
    docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    xls: 'application/vnd.ms-excel',
    xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    ppt: 'application/vnd.ms-powerpoint',
    pptx: 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
    csv: 'text/csv',
    txt: 'text/plain'
  };
  return map[ext] || 'application/pdf';
}

