async function extractMedia() {
  let mediaUrl = '', mediaType = '';
  if (isPhoto) { const photo = message.photo[message.photo.length - 1]; if ((photo.file_size || 0) > 5000000) { await notifySeller.call(this, '⚠️ الصورة كبيرة جداً.'); return null; } const r = await transferFile.call(this, photo.file_id, photo.file_id + '.jpg'); if (r.success && r.url) { mediaUrl = r.url; mediaType = 'photo'; } }
  else if (isVideo) { const video = message.video; if ((video.file_size || 0) > 16000000) { await notifySeller.call(this, '⚠️ الفيديو كبير جداً.'); return null; } const r = await transferFile.call(this, video.file_id, video.file_id + '.mp4'); if (r.success && r.url) { mediaUrl = r.url; mediaType = 'video'; } }
  else if (isDocument) { if ((message.document.file_size || 0) > 20000000) { await notifySeller.call(this, '⚠️ الملف كبير جداً.'); return null; } const r = await transferFile.call(this, message.document.file_id, message.document.file_name || 'file.pdf'); if (r.success && r.url) { mediaUrl = r.url; mediaType = 'document'; } }
  return { mediaUrl, mediaType };
}

