async function sendAIFollowUp(customerPhone, question, answer) {
  try {
    const historyResponse = await this.helpers.httpRequest({ method: 'GET', url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/conversations?phone_number=eq.' + customerPhone + '&select=role,message,timestamp&order=timestamp.asc&limit=20', headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey } });
    const history = (historyResponse || []).map(m => ({ role: m.role === 'user' ? 'user' : 'assistant', content: m.message }));

    // Detect language from the customer's actual LAST message, using the same
    // robust AI-based detection used elsewhere — not a fragile regex over the
    // whole conversation history, which defaulted to Arabic the moment any
    // single character (an apostrophe, a $ sign, an emoji) appeared anywhere
    // in the history, even in an entirely English conversation.
    const lastCustomerMsg = [...history].reverse().find(h => h.role === 'user');
    const langDetection = await detectSellerLanguageFull.call(this, (lastCustomerMsg && lastCustomerMsg.content) || '');
    const fullLanguage = langDetection.language || 'English';
    const fullDialect = langDetection.dialect || '';
    const langRule = `Reply in ${fullLanguage}${fullDialect ? ' (' + fullDialect + ' dialect/accent)' : ''} ONLY.`;

    const claudeResponse = await this.helpers.httpRequest({ method: 'POST', url: 'https://api.anthropic.com/v1/messages', headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' }, body: JSON.stringify({ model: 'claude-haiku-4-5-20251001', max_tokens: 200, system: `${aiName ? `You are ${aiName}, a` : 'You are a'} real Iraqi wholesale salesperson. ${langRule} Continue naturally to close the sale. Max 1-2 lines. ONE question only. No markdown.`, messages: [...history, { role: 'assistant', content: answer }] }) });
    await logAiUsage.call(this, claudeResponse, 'ai_followup_message');
    const followUpMsg = claudeResponse.content[0].text.trim().replace('[ORDER_CONFIRMED]', '').replace(/\[ASK_SELLER:.*?\]/g, '').replace('[BUMP_OFFERED]', '').replace('[UPSELL_OFFERED]', '').trim();
    if (followUpMsg) {
      await sendWhatsApp.call(this, customerPhone, followUpMsg);
      await this.helpers.httpRequest({ method: 'POST', url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/conversations', headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' }, body: JSON.stringify({ phone_number: customerPhone, role: 'assistant', message: followUpMsg, timestamp: new Date().toISOString(), seller_id: chatId }) });
    }
  } catch (e) { logSystemError.call(this, chatId, 'Saving automated follow-up message to history', e && e.message); }
}

async function sendOfferNow(broadcastMsg, mediaUrl, mediaType) {
  const settings = await getSettings.call(this);
  const targetAudience = settings.target_audience || 'both';
  const customers = await this.helpers.httpRequest({ method: 'GET', url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/broadcast_log?seller_id=eq.' + chatId + '&select=*', headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey } });
  let sentCount = 0;
  for (const customer of customers) {
    if (customer.status === 'blocked') continue;
    const p = customer.phone_number.replace(/=/g, '').replace(/\+/g, '');
    let shouldSend = targetAudience === 'both' || (targetAudience === 'wholesale' && customer.is_wholesale === true) || (targetAudience === 'retail' && customer.is_wholesale === false);
    if (!shouldSend) continue;
    try {
      if (broadcastMsg) await sendWhatsApp.call(this, p, broadcastMsg);
      if (mediaUrl && mediaType) { let mb; if (mediaType === 'photo') mb = { messaging_product: 'whatsapp', to: p, type: 'image', image: { link: mediaUrl, caption: '' } }; else if (mediaType === 'video') mb = { messaging_product: 'whatsapp', to: p, type: 'video', video: { link: mediaUrl, caption: '' } }; else mb = { messaging_product: 'whatsapp', to: p, type: 'document', document: { link: mediaUrl, caption: '' } }; await this.helpers.httpRequest({ method: 'POST', url: 'https://graph.facebook.com/v19.0/' + phoneNumberId + '/messages', headers: { 'Authorization': 'Bearer ' + metaToken, 'Content-Type': 'application/json' }, body: JSON.stringify(mb) }); }
      await this.helpers.httpRequest({ method: 'PATCH', url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/broadcast_log?phone_number=eq.' + customer.phone_number + '&seller_id=eq.' + chatId, headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' }, body: JSON.stringify({ last_broadcast_at: new Date().toISOString() }) });
      sentCount++;
    } catch (e) { logSystemError.call(this, chatId, 'Updating broadcast last-sent timestamp', e && e.message); }
  }
  return sentCount;
}

