async function checkAndCoach(settings, lang) {
  const recentCoaching = await this.helpers.httpRequest({ method: 'GET', url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/coaching_log?select=feature,status,next_suggest_at&order=suggested_at.desc&limit=20', headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey } });
  const now = new Date(); const coached = {};
  (recentCoaching || []).forEach(c => { if (c.status === 'rejected' && c.next_suggest_at && new Date(c.next_suggest_at) > now) coached[c.feature] = true; else if (c.status === 'pending') coached[c.feature] = true; });
  const checks = [
    { key: 'followup', active: settings.followup_active === 'true' }, { key: 'broadcast', active: settings.broadcast_active === 'true' },
    { key: 'bump', active: settings.bump_active === 'true' }, { key: 'upsell', active: settings.upsell_active === 'true' },
    { key: 'crosssell', active: settings.crosssell_active === 'true' }, { key: 'winback', active: settings.winback_active === 'true' },
    { key: 'referral', active: !!(settings.referral_reward) }, { key: 'vip', active: !!(settings.vip_threshold) }
  ];
  for (const check of checks) { if (!check.active && !coached[check.key]) { await sendCoaching.call(this, check.key, settings, lang); return true; } }
  return false;
}

