// ═══ MAIN PROCESSING FUNCTION ═══
async function processMessage(effectiveText, lang, isMediaMessage, fullLanguage, fullDialect) {
  const textTrimmed = effectiveText.trim();
  const captionTrimmed = caption.trim();
  const parts = textTrimmed.split(' ');
  const firstPart = (parts[0] || '').replace(/=/g, '').replace(/\+/g, '');
  const isPhoneNumber = /^964\d{9,}$/.test(firstPart) || /^\d{10,}$/.test(firstPart);

  // ═══ GENERAL CSV IMPORT — works anytime a .csv file is sent, not just during onboarding ═══
  if (isDocument && message.document && (message.document.file_name || '').toLowerCase().endsWith('.csv')) {
    const _stateForCsv = await getBotState.call(this);
    if (_stateForCsv.state !== 'onboarding') {
      await handleCsvImport.call(this, lang, fullLanguage, fullDialect);
      return;
    }
  }

  if (isMediaMessage && captionTrimmed.startsWith('/sendoffernow')) { const offerMsg = captionTrimmed.replace('/sendoffernow', '').trim(); const media = await extractMedia.call(this); if (!media) return; const sentCount = await sendOfferNow.call(this, offerMsg, media.mediaUrl, media.mediaType); await notifySeller.call(this, t(lang, '✅ تم إرسال العرض لـ ' + sentCount + ' زبون!', '✅ Offer sent to ' + sentCount + ' customers!')); return; }
  if (isMediaMessage && captionTrimmed.startsWith('/sendbroadcast')) { const broadcastMsg = captionTrimmed.replace('/sendbroadcast', '').trim(); await updateSetting.call(this, 'broadcast_message', broadcastMsg); const media = await extractMedia.call(this); if (!media) return; await updateSetting.call(this, 'broadcast_media_url', media.mediaUrl); await updateSetting.call(this, 'broadcast_media_type', media.mediaType); await notifySeller.call(this, t(lang, '✅ تم حفظ البث!', '✅ Broadcast saved!')); return; }

  if (textTrimmed === '/start') { await sendWelcome.call(this, lang); return; }

  // ═══ AUTO-TRIGGER ONBOARDING FOR NEW/RESET SELLERS ═══
  // Without this, a seller with no business profile yet (brand new, or reset for
  // testing) just gets generic small talk with no path forward, since onboarding
  // was previously only reachable via an explicit "add new product"-style request.
  const _stateForAutoOnboard = await getBotState.call(this);
  if (_stateForAutoOnboard.state !== 'onboarding') {
    try {
      const _profileCheck = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/sellers?chat_id=eq.' + chatId + '&select=business_name_location&limit=1',
        headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
      });
      const _hasProfile = _profileCheck && _profileCheck.length > 0 && _profileCheck[0].business_name_location;
            if (!_hasProfile) {
        await startOnboarding.call(this, textTrimmed, lang, fullLanguage, fullDialect);
        return;
      }
    } catch (e) { logSystemError.call(this, chatId, 'Checking if seller has completed onboarding', e && e.message); }
  }
  if (textTrimmed === '/commands' || textTrimmed === 'commands' || textTrimmed === 'أوامر') { await showCommandsStatus.call(this, lang); return; }
  if (textTrimmed === '/help' || textTrimmed === 'help' || textTrimmed === 'ساعدني') { await executeIntent.call(this, 'show_help', {}, {}, lang); return; }
  if (textTrimmed === 'وقف الكل' || textTrimmed === 'pause all' || textTrimmed === '/pauseall') { const s = await getSettings.call(this); await executeIntent.call(this, 'pause_all', {}, s, lang); return; }
  if (textTrimmed === 'شغل الكل' || textTrimmed === 'resume all' || textTrimmed === '/resumeall') { const s = await getSettings.call(this); await executeIntent.call(this, 'resume_all', {}, s, lang); return; }
  if (textTrimmed.startsWith('/resume') && textTrimmed.length > 7) { const s = await getSettings.call(this); await executeIntent.call(this, 'resume_ai', { phone: textTrimmed.replace('/resume', '').trim() }, s, lang); return; }
  if (textTrimmed.startsWith('/pause') && textTrimmed.length > 6) { const s = await getSettings.call(this); await executeIntent.call(this, 'pause_ai', { phone: textTrimmed.replace('/pause', '').trim() }, s, lang); return; }

// ═══ INTELLIGENCE SYSTEM — AI DETECTION (only when NOT in onboarding) ═══
  const _stateCheck = await getBotState.call(this);
  let _reportContextHint = '';
  if (_stateCheck.context && _stateCheck.context.last_report_intent && _stateCheck.context.last_report_intent_at) {
    const _secondsAgo = Math.round((Date.now() - _stateCheck.context.last_report_intent_at) / 1000);
    if (_secondsAgo < 600) {
      _reportContextHint = `\n\nCONTEXT: The seller's previous message (${_secondsAgo} seconds ago) was about ${_stateCheck.context.last_report_intent}. If THIS message is a short, vague follow-up with no other clear topic of its own — e.g. just a different date range like "last 30 days", "this month", "yesterday", or a vague "how about X"/"what about X" — keep the SAME intent (${_stateCheck.context.last_report_intent}), since it's almost certainly continuing that same conversation. Only pick a different intent if this message clearly signals a new, different topic on its own.`;
    }
  }
  if (_stateCheck.state !== 'onboarding' && _stateCheck.state !== 'confirm_delete_business' && _stateCheck.state !== 'awaiting_confirmation_mode_choice' && _stateCheck.state !== 'pending_manage_confirm' && _stateCheck.state !== 'pending_csv_import' && _stateCheck.state !== 'awaiting_barcode_link' && _stateCheck.state !== 'awaiting_answer_scope' && _stateCheck.state !== 'pending_ads_edit_confirm') {
    try {
      const intelligencePlan = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api.anthropic.com/v1/messages',
        headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: 'claude-haiku-4-5-20251001',
          max_tokens: 20,
          system: `Detect what the seller wants. Reply ONLY with one of these exact words:
ONBOARDING - wants to add or register a new product to sell
SHOW_PRODUCTS - wants to see their registered products
DELETE_PRODUCT - wants to delete or remove a single product
DELETE_BUSINESS - wants to delete their ENTIRE business/account/profile, not just one product (e.g. "delete my whole business", "remove my account", "امسح بزنسي بالكامل")
POS_MENU - wants to see their POS dashboard, POS settings, or what POS features are available (e.g. "show my POS", "POS settings", "what features do I have")
POS_TOGGLE - wants to turn a specific POS feature on or off (e.g. "turn on inventory tracking", "enable low stock alerts", "disable auto invoice") — this is about built-in POS features only, NOT setting a custom ad-metric alert threshold (that's MANAGE_ADS — e.g. "alert me if CPC goes above $1" is MANAGE_ADS, not POS_TOGGLE).
STOCK_UPDATE - wants to set or update the stock quantity for a specific product (e.g. "set [product] stock to 50", "update stock for [product] to 20")
STOCK_VIEW - wants to see current stock/inventory levels
MANAGE_BUSINESS - wants to add, edit, or delete a pricing tier, customer, order, expense, or anything else about their business not covered by the categories above (general CRUD-style requests, e.g. "add a customer named Karim", "change the wholesale tier to -20%", "delete the kilogram unit", "log an expense of 50000 for fuel"). ALSO use this for adding, editing, or removing a specific DETAIL, FEATURE, or NOTE on an existing product — e.g. "add that we offer free shipping for containers", "remove that shipping note, that was just a test", "update the MOQ to 500 sets" — these are edits to ONE FIELD of a product, not deleting the whole product (that's DELETE_PRODUCT instead). If in doubt whether "remove"/"delete" refers to a small detail/note versus the entire product, check whether they name a specific product to delete entirely ("delete product X" = DELETE_PRODUCT) versus describing a specific fact/feature to remove from it ("remove that note about X" = MANAGE_BUSINESS).
GENERATE_INVOICE - wants to generate, create, or send an invoice for an order (e.g. "generate invoice for Karim", "send invoice to 07701234567", "make invoice for the last order")
REGISTER_AD - wants to link/register a Meta ad ID to a specific product and offer, so Ahmad knows what to lead with when a customer clicks that ad (e.g. "ad 120211234567 is for WAK brake pads, offer is 20% off", "link ad ID xyz to the summer sale product")
SET_AD_ACCOUNT_ID - wants to set/save their Meta Ad Account ID for ads tracking (e.g. "my ad account id is act_123456789", "set ad account to 987654321"), or is asking where/how to find their ad account ID
MANAGE_ADS - wants to see ad performance/metrics/reports, ROAS/return on ad spend/ad profitability, how many people messaged/started a conversation because of a specific ad or campaign, pause/resume/change budget/rename a campaign or ad, or discuss ad strategy/ideas/what to test (e.g. "how are my ads doing", "what's my real ROAS", "am I profitable on ads", "how many people messaged us from this campaign", "pause the summer sale campaign", "what should I test next"). If the request mentions ads, campaigns, ROAS, or ad spend in any way, use this — NOT WEEKLY_REPORT, NOT MESSAGE_VOLUME. ALSO use this for any Meta ad-metric vocabulary even if the words "ad"/"campaign" are never said — e.g. "how many clicks did I get", "what's my CTR", "what's my cost per click", "what's my CPM", "what's my reach", "what's my frequency", "how many purchases came from my ads" all mean MANAGE_ADS, not MESSAGE_VOLUME or WEEKLY_REPORT. ALSO use this for setting a custom AD alert/threshold — e.g. "alert me if CPC goes above $1", "tell me if CTR drops below 2%", "notify me if my ad spend goes over $50" — these mean MANAGE_ADS (NOT ALERTS, NOT POS_TOGGLE), since they're about creating a new ad-metric monitoring rule, not viewing existing alerts or toggling a POS feature. ALSO use this for structural questions about ad account contents — e.g. "how many ad sets do I have", "how many ad sets are in my [campaign name] campaign", "what campaigns do I have", "list my ads" — these mean MANAGE_ADS too, not MANAGE_BUSINESS.
ALERTS - wants to see EXISTING alerts, notifications, pending issues, overdue orders, silent customers — NOT a question about how many messages/conversations they've received, and NOT a request to set up a NEW custom ad-metric alert rule (that's MANAGE_ADS — e.g. "alert me if CPC goes above $1" is MANAGE_ADS, not ALERTS).
MESSAGE_VOLUME - wants to know how many messages/conversations customers have sent overall, optionally within a specific date range (e.g. "how many messages did I get this month", "how many customers messaged me from 1/1/2026 to 1/7/2026") — does NOT mention a campaign, ad, or ad account, and does NOT use ad-metric words like clicks/CTR/CPC/CPM/reach/frequency/impressions/spend. If the question mentions "campaign," "ad," "ad account," or any ad-metric term in any way, use MANAGE_ADS instead, even if it's about message/conversation counts or sounds like a generic "how many X" question.
WEEKLY_REPORT - wants a general weekly or monthly SALES performance report (orders, revenue, customers) — does NOT mention ads, campaigns, ROAS, or ad spend at all
NONE - none of the above
CLARIFY_REPORT_TYPE - the message is a vague report/performance follow-up with NO clear topic of its own (e.g. just a date range like "last 30 days", "this month", "how about yesterday", with nothing else indicating sales vs ads vs messages) AND no CONTEXT hint above tells you what the previous topic was. Use this ONLY when you genuinely cannot tell whether they mean ad metrics, general sales, or message volume — do not use this if a CONTEXT hint above already tells you the recent topic, and do not use this if the message itself contains any clear topic words (ads/campaign/spend/clicks = MANAGE_ADS; orders/revenue/sales = WEEKLY_REPORT; messages/conversations = MESSAGE_VOLUME).${_reportContextHint}`,
          messages: [{ role: 'user', content: textTrimmed }]
        })
