      await logAiUsage.call(this, intelligencePlan, 'top_level_intent_classifier');
      const intelligenceIntent = intelligencePlan.content[0].text.trim().toUpperCase();
            if (intelligenceIntent === 'ONBOARDING') { await startOnboarding.call(this, textTrimmed, lang, fullLanguage, fullDialect); return; }
