      if (intelligenceIntent === 'DELETE_PRODUCT') { const productName = textTrimmed.replace(/احذف منتج/i, '').replace(/delete product/i, '').replace(/remove product/i, '').trim(); if (!productName) { await notifySeller.call(this, t(lang, '⚠️ شنو اسم المنتج اللي تريد تحذفه؟', '⚠️ Which product name?')); return; } await deleteProduct.call(this, productName, lang); return; }
      if (intelligenceIntent === 'DELETE_BUSINESS') {
