      return;
    }

    if (botState.state === 'setup_followup1') { await updateSetting.call(this, 'followup1_message', textTrimmed.replace(/رسالة متابعة \d+:/i, '').trim()); await notifySeller.call(this, t(lang, '✅ تم!\nرسالة المتابعة الثانية (بعد 24 ساعة). أو "تخطي"', '✅ Done!\nFollow-up 2 (after 24h). Or "skip"')); await setBotState.call(this, 'setup_followup2', {}); return; }
    if (botState.state === 'setup_followup2') { if (!textTrimmed.includes('تخطي') && !textTrimmed.includes('skip')) await updateSetting.call(this, 'followup2_message', textTrimmed.replace(/رسالة متابعة \d+:/i, '').trim()); await notifySeller.call(this, t(lang, '✅ تم!\nرسالة المتابعة الثالثة (بعد 72 ساعة). أو "تخطي"', '✅ Done!\nFollow-up 3 (after 72h). Or "skip"')); await setBotState.call(this, 'setup_followup3', {}); return; }
    if (botState.state === 'setup_followup3') { if (!textTrimmed.includes('تخطي') && !textTrimmed.includes('skip')) await updateSetting.call(this, 'followup3_message', textTrimmed.replace(/رسالة متابعة \d+:/i, '').trim()); await setBotState.call(this, 'idle', {}); await notifySeller.call(this, t(lang, '🎉 المتابعة جاهزة!', '🎉 Follow-up ready!')); return; }
    if (botState.state === 'setup_broadcast') { await updateSetting.call(this, 'broadcast_message', textTrimmed); await setBotState.call(this, 'idle', {}); await notifySeller.call(this, t(lang, '✅ تم حفظ البث!', '✅ Broadcast saved!')); return; }
    if (botState.state === 'setup_bump') { const d = await detectIntent.call(this, textTrimmed, settings); await executeIntent.call(this, 'set_bump', d.params, settings, lang); await setBotState.call(this, 'idle', {}); return; }
    if (botState.state === 'setup_upsell') { const d = await detectIntent.call(this, textTrimmed, settings); await executeIntent.call(this, 'set_upsell', d.params, settings, lang); await setBotState.call(this, 'idle', {}); return; }
    if (botState.state === 'setup_crosssell') { const d = await detectIntent.call(this, textTrimmed, settings); await executeIntent.call(this, 'set_crosssell', d.params, settings, lang); await setBotState.call(this, 'idle', {}); return; }
    if (botState.state === 'setup_referral') { const d = await detectIntent.call(this, textTrimmed, settings); await executeIntent.call(this, 'set_referral', d.params, settings, lang); await setBotState.call(this, 'idle', {}); return; }

    const detected = await detectIntent.call(this, textTrimmed, settings);
    if (detected.intent !== 'unknown') { await executeIntent.call(this, detected.intent, detected.params, settings, lang); }
    else { await handleBusinessConversation.call(this, textTrimmed, settings, lang, history, fullLanguage, fullDialect); }
    return;
  }

  if (isPhoneNumber) {
    const answer = parts.slice(1).join(' ');
    if (answer.length > 0) { await sendWhatsApp.call(this, firstPart, answer); await notifySeller.call(this, t(lang, '✅ تم إرسال الرسالة للعميل ' + firstPart, '✅ Message sent to ' + firstPart)); }
  }
}

// ═══ SET BEST-GUESS LANGUAGE FIRST (in case transcription fails below) ═══
const earlyPrefs = await getSellerPreferences.call(this);
globalFullLanguage = (earlyPrefs && earlyPrefs.full_language) || 'English';
globalFullDialect = (earlyPrefs && earlyPrefs.full_dialect) || '';

// ═══ FETCH THIS SELLER'S CURRENCY LABEL (generic, not hardcoded IQD) ═══
try {
  const currencyResp = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_sales_config?chat_id=eq.' + chatId + '&select=currency_label&limit=1',
    headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
  });
  if (currencyResp && currencyResp.length > 0 && currencyResp[0].currency_label) {
    globalCurrencyLabel = currencyResp[0].currency_label;
  }
} catch (e) { logSystemError.call(this, chatId, 'Fetching seller currency setting', e && e.message); }

// ═══ TRANSCRIBE VOICE ═══
if ((isVoice || isAudio) && !replyToMessageId) {
  transcribedText = await transcribeVoice.call(this);
  if (!transcribedText) { await notifySeller.call(this, '⚠️ ما قدرت أفهم الصوت. جرب مرة ثانية أو اكتب.\n(Could not understand the audio. Please try again or type instead.)'); return [{ json: { success: false } }]; }
}

// ═══ DETECT LANGUAGE ═══
const currentText = transcribedText || text || caption;
// Short, pure-ASCII phrases (e.g. campaign/ad set names like "wak ad set") carry no real
// grammatical language signal — running full AI detection on them risks a one-off
// misclassification that flips the seller's whole conversation language unexpectedly.
// Trust their established preference for these instead of re-detecting from scratch.
const isShortAsciiPhrase = !/[^\x00-\x7F]/.test(currentText) && currentText.trim().length > 0 && currentText.trim().length < 40;
let currentFullLanguage, currentFullDialect;
if (isShortAsciiPhrase && earlyPrefs && earlyPrefs.full_language) {
  currentFullLanguage = earlyPrefs.full_language;
  currentFullDialect = earlyPrefs.full_dialect || '';
} else {
  const fullLangResult = await detectSellerLanguageFull.call(this, currentText);
  currentFullLanguage = fullLangResult.language;
  currentFullDialect = fullLangResult.dialect;
}
globalFullLanguage = currentFullLanguage;
globalFullDialect = currentFullDialect;
let lang = currentFullLanguage.toLowerCase().includes('kurdish') ? 'kurdish' : currentFullLanguage.toLowerCase().includes('arabic') ? 'arabic' : 'english';
const prefs = earlyPrefs;
const wordCount = currentText.trim().split(/\s+/).filter(Boolean).length;
if (prefs && prefs.language && (currentText.trim().length < 3 || wordCount <= 4)) lang = prefs.language;
await saveSellerPreferences.call(this, { language: lang, full_language: currentFullLanguage, full_dialect: currentFullDialect });

// ═══ HANDLE REPLIES ═══
if (replyToMessageId) {
  const ordersResponse = await this.helpers.httpRequest({ method: 'GET', url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/pending_orders?telegram_message_id=eq.' + replyToMessageId + '&select=phone_number', headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey } });
  if (ordersResponse && ordersResponse.length > 0) { phone = ordersResponse[0].phone_number.toString().replace(/=/g, '').replace(/\+/g, ''); isInvoiceReply = true; }
  if (!isInvoiceReply) {
    const questionsResponse = await this.helpers.httpRequest({ method: 'GET', url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/pending_questions?telegram_message_id=eq.' + replyToMessageId + '&select=phone_number,question', headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey } });
    if (questionsResponse && questionsResponse.length > 0) {
      phone = questionsResponse[0].phone_number.toString().replace(/=/g, '').replace(/\+/g, '');
      const question = questionsResponse[0].question;
      isInvoiceReply = true; isQuestionReply = true;
      if (isText && text.length > 0) {
        await setBotState.call(this, 'awaiting_answer_scope', {
          phone, question, replyToMessageId,
          answerType: 'text', answerText: text
        });
        await notifySeller.call(this, t(lang,
          `قبل ما أرسلها — هذا الجواب:\n1️⃣ عام (بتذكره لأي زبون ثاني يسأل نفس السؤال)\n2️⃣ خاص بهذا الزبون بس\n\nرد بـ "عام" أو "خاص"`,
          `Before I send this — is this answer:\n1️⃣ General (I'll remember it for any future customer who asks the same thing)\n2️⃣ Specific to just this customer\n\nReply "general" or "specific"`
        ));
        return [{ json: { success: true, awaitingScope: true } }];
      } else if (isPhoto || isVideo || isDocument) {
        // Seller answered a price/code inquiry with a file/image instead of typing —
        // this is a completely normal, expected way to answer (e.g. a pricing sheet
        // or quote photo), so it needs the exact same forwarding treatment as a text
        // answer, not silent failure.
        try {
          let mediaResult = null;
          let mediaType = null;
          let answerNote = caption || '';
          let docFileName = null;
          if (isPhoto) {
            const photo = message.photo[message.photo.length - 1];
            if ((photo.file_size || 0) > 5000000) { await notifySeller.call(this, '⚠️ الصورة كبيرة جداً.'); return [{ json: { success: false } }]; }
            mediaResult = await transferFile.call(this, photo.file_id, photo.file_id + '.jpg');
            mediaType = 'image';
            answerNote = answerNote || '[Sent pricing as an image]';
          } else if (isVideo) {
            const video = message.video;
            if ((video.file_size || 0) > 16000000) { await notifySeller.call(this, '⚠️ الفيديو كبير جداً.'); return [{ json: { success: false } }]; }
            mediaResult = await transferFile.call(this, video.file_id, video.file_id + '.mp4');
            mediaType = 'video';
            answerNote = answerNote || '[Sent pricing as a video]';
          } else if (isDocument) {
            if ((message.document.file_size || 0) > 20000000) { await notifySeller.call(this, '⚠️ الملف كبير جداً.'); return [{ json: { success: false } }]; }
            mediaResult = await transferFile.call(this, message.document.file_id, message.document.file_name || 'pricing.pdf');
            mediaType = 'document';
            docFileName = message.document.file_name || 'pricing.pdf';
            answerNote = answerNote || '[Sent pricing as a file: ' + docFileName + ']';
          }

          if (!mediaResult || !mediaResult.success || !mediaResult.url) {
            await notifySeller.call(this, t(lang, '⚠️ فشل نقل الملف.', '⚠️ Failed to transfer the file.'));
            return [{ json: { success: false } }];
          }

          await setBotState.call(this, 'awaiting_answer_scope', {
            phone, question, replyToMessageId,
            answerType: 'media', mediaType, mediaUrl: mediaResult.url, caption: caption || '', answerNote, docFileName
          });
          await notifySeller.call(this, t(lang,
            `قبل ما أرسله — هذا الجواب:\n1️⃣ عام (بتذكره لأي زبون ثاني يسأل نفس السؤال)\n2️⃣ خاص بهذا الزبون بس\n\nرد بـ "عام" أو "خاص"`,
            `Before I send this — is this answer:\n1️⃣ General (I'll remember it for any future customer who asks the same thing)\n2️⃣ Specific to just this customer\n\nReply "general" or "specific"`
          ));
          return [{ json: { success: true, awaitingScope: true } }];
        } catch (e) {
          const metaErrorMsg = extractMetaErrorMessage(e);
          await notifySeller.call(this, t(lang, '⚠️ فشل تجهيز الملف — ' + metaErrorMsg, '⚠️ Failed to prepare the file — ' + metaErrorMsg));
          return [{ json: { success: false } }];
        }
      }
    }
  }
}

// ═══ HANDLE MEDIA REPLIES ═══
if (isInvoiceReply && !isQuestionReply) {
  if (isText) { try { await sendWhatsApp.call(this, phone, text); await notifySeller.call(this, t(lang, '✅ تم إرسال الرسالة!', '✅ Message sent!')); } catch(e) { await notifySeller.call(this, '⚠️ ' + e.message); }
  } else if (isPhoto) {
    const photo = message.photo[message.photo.length - 1];
    if ((photo.file_size || 0) > 5000000) { await notifySeller.call(this, '⚠️ الصورة كبيرة جداً.'); return [{ json: { success: false } }]; }
    const r = await transferFile.call(this, photo.file_id, photo.file_id + '.jpg');
    if (!r.success || !r.url) { await notifySeller.call(this, '⚠️ فشل نقل الصورة.'); return [{ json: { error: 'Transfer failed' } }]; }
    await this.helpers.httpRequest({ method: 'POST', url: 'https://graph.facebook.com/v19.0/' + phoneNumberId + '/messages', headers: { 'Authorization': 'Bearer ' + metaToken, 'Content-Type': 'application/json' }, body: JSON.stringify({ messaging_product: 'whatsapp', to: phone, type: 'image', image: { link: r.url, caption: caption || '' } }) });
    await notifySeller.call(this, t(lang, '✅ تم إرسال الصورة!', '✅ Image sent!'));
  } else if (isVideo) {
    const video = message.video;
    if ((video.file_size || 0) > 16000000) { await notifySeller.call(this, '⚠️ الفيديو كبير جداً.'); return [{ json: { success: false } }]; }
    const r = await transferFile.call(this, video.file_id, video.file_id + '.mp4');
    if (!r.success || !r.url) { await notifySeller.call(this, '⚠️ فشل.'); return [{ json: { error: 'Transfer failed' } }]; }
    await this.helpers.httpRequest({ method: 'POST', url: 'https://graph.facebook.com/v19.0/' + phoneNumberId + '/messages', headers: { 'Authorization': 'Bearer ' + metaToken, 'Content-Type': 'application/json' }, body: JSON.stringify({ messaging_product: 'whatsapp', to: phone, type: 'video', video: { link: r.url, caption: caption || '' } }) });
    await notifySeller.call(this, t(lang, '✅ تم إرسال الفيديو!', '✅ Video sent!'));
  } else if (isDocument) {
    if ((message.document.file_size || 0) > 20000000) { await notifySeller.call(this, '⚠️ الملف كبير جداً.'); return [{ json: { success: false } }]; }
    const r = await transferFile.call(this, message.document.file_id, message.document.file_name || 'invoice.pdf');
    if (!r.success || !r.url) { await notifySeller.call(this, '⚠️ فشل.'); return [{ json: { error: 'Transfer failed' } }]; }
    await this.helpers.httpRequest({ method: 'POST', url: 'https://graph.facebook.com/v19.0/' + phoneNumberId + '/messages', headers: { 'Authorization': 'Bearer ' + metaToken, 'Content-Type': 'application/json' }, body: JSON.stringify({ messaging_product: 'whatsapp', to: phone, type: 'document', document: { link: r.url, filename: message.document.file_name || 'invoice.pdf', caption: caption || '' } }) });
    await notifySeller.call(this, t(lang, '✅ تم إرسال الملف!', '✅ File sent!'));
  }
  return [{ json: { success: true } }];
}

// ═══ PHOTO BARCODE LOOKUP (works anytime, any state, if not in onboarding, and not a command photo like /sendoffernow) ═══
if (isPhoto && message.photo && message.photo.length > 0 && !caption.trim().startsWith('/')) {
  await handlePhotoBarcode.call(this, lang);
  return [{ json: { success: true } }];
}

// ═══ MESSAGE BATCHING ═══
if (!isInvoiceReply) {
  const isMediaMessage = isPhoto || isVideo || isDocument;
  const messageContent = transcribedText || text;
 const isIntelligenceCmd = await isIntelligenceQuery.call(this, messageContent.trim());

  try {
    if (messageContent.trim().startsWith('/') || isMediaMessage || isVoice || isAudio || isIntelligenceCmd) {
      await processMessage.call(this, messageContent, lang, isMediaMessage, currentFullLanguage, currentFullDialect);
    } else if (messageContent.trim()) {
      const { batchId, myTimestamp } = await addToBatch.call(this, messageContent);
      if (batchId) {
        const combinedText = await getBatchAndProcess.call(this, batchId, myTimestamp);
        if (combinedText) { await clearBatch.call(this, batchId); await processMessage.call(this, combinedText, lang, false, currentFullLanguage, currentFullDialect); }
      }
    }
  } catch (globalErr) {
    // Last-resort safety net: whatever failed, tell the seller something readable
    // instead of letting a raw n8n/axios crash reach them with no explanation.
    try {
      const isAnthropicFailure = (globalErr.config?.url || '').includes('api.anthropic.com');
      if (isAnthropicFailure) {
        await notifySeller.call(this, t(lang,
          '⚠️ يبدو أن رصيد Anthropic API خلص أو صار فيه مشكلة بالفوترة. تحقق من حسابك بموقع Anthropic وأعد الشحن، وبعدين جرب مرة ثانية.',
          "⚠️ It looks like the Anthropic API credit balance may be exhausted (or there's a billing issue). Please check your Anthropic account and top up, then try again."
        ));
      } else {
        await notifySeller.call(this, t(lang,
          `⚠️ صار خطأ غير متوقع: ${globalErr.message || 'Unknown error'}`,
          `⚠️ Something unexpected went wrong: ${globalErr.message || 'Unknown error'}`
        ));
      }
    } catch (notifyErr) { logSystemError.call(this, chatId, 'Notifying seller of an unexpected error', notifyErr && notifyErr.message); }
  }
}

return [{ json: { success: true, phone, isInvoiceReply, isQuestionReply } }];
